--
-- Name: reload_t_merchant_payments(); Type: PROCEDURE; Schema: auto_views; Owner: -
--

CREATE PROCEDURE auto_views.reload_t_merchant_payments()
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE NOTICE 'Step 1: Dropping and Creating backup table BK_t_merchant_payments...';
  DROP TABLE IF EXISTS auto_views.BK_t_merchant_payments;  
  CREATE TABLE IF NOT EXISTS auto_views.BK_t_merchant_payments AS 
  SELECT * FROM auto_views.v_merchant_payments WITH NO DATA;
  RAISE NOTICE 'Step 2: Inserting data from v_merchant_payments to BK_t_merchant_payments...';
  INSERT INTO auto_views.BK_t_merchant_payments
  SELECT * FROM auto_views.v_merchant_payments;
  RAISE NOTICE 'Backup completed. Rows inserted: %', (SELECT COUNT(*) FROM auto_views.BK_t_merchant_payments);
  RAISE NOTICE 'Step 3: Swapping backup with t_merchant_payments...';
  ALTER TABLE auto_views.t_merchant_payments RENAME TO t_merchant_payments_old;
  ALTER TABLE auto_views.BK_t_merchant_payments RENAME TO t_merchant_payments;
  --ALTER TABLE auto_views.t_merchant_payments_old RENAME TO BK_t_merchant_payments;
  CREATE OR REPLACE VIEW public.mv_merchant_payments AS SELECT * from auto_views.t_merchant_payments;
  RAISE NOTICE 'Swapping tables completed. Rows loaded: %', (SELECT COUNT(*) FROM auto_views.t_merchant_payments);
  --RAISE NOTICE 'Creating indexes ...';
  --PERFORM auto_views.create_index_merchant_payments();
  RAISE NOTICE 'Step 4: Dropping backup table t_merchant_payments_old...';
  DROP TABLE IF EXISTS auto_views.t_merchant_payments_old;
  RAISE NOTICE '✅ Reload process completed successfully.';
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING '⚠️ Error occurred: %, restoring data from backup...', SQLERRM;
    TRUNCATE TABLE auto_views.t_merchant_payments;
    INSERT INTO auto_views.t_merchant_payments
    SELECT * FROM auto_views.v_merchant_payments;
    CREATE OR REPLACE VIEW public.mv_merchant_payments AS SELECT * from auto_views.t_merchant_payments;
    RAISE NOTICE 'Data restored from backup successfully.';
END;
$$;


--
-- Name: rename_table_create_view(text, text, text, text); Type: PROCEDURE; Schema: auto_views; Owner: -
--

CREATE PROCEDURE auto_views.rename_table_create_view(IN old_table_name text, IN current_table_name text, IN backup_name text, IN mv text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Optional: terminate blockers (only sessions using this table)
    PERFORM  pg_terminate_backend(a.pid)
    FROM pg_locks l
	JOIN pg_class c ON c.oid = l.relation
	JOIN pg_namespace n ON n.oid = c.relnamespace
	JOIN pg_stat_activity a ON a.pid = l.pid  
	WHERE c.relname = current_table_name  -- table name only
    AND n.nspname = 'auto_views'        -- schema
    AND a.pid <> pg_backend_pid();

    -- Lock table
    EXECUTE format('LOCK TABLE %I.%I IN ACCESS EXCLUSIVE MODE;','auto_views', current_table_name);
    EXECUTE format('LOCK TABLE %I.%I IN ACCESS EXCLUSIVE MODE;','public',mv);

    -- Rename table
    EXECUTE format('ALTER TABLE %I.%I RENAME TO %I;', 'auto_views', current_table_name, old_table_name);
    EXECUTE format('ALTER TABLE %I.%I RENAME TO %I;', 'auto_views', backup_name, current_table_name);
    EXECUTE format('CREATE OR REPLACE VIEW %I.%I AS SELECT * from %I.%I','public',mv,'auto_views',current_table_name);
    RAISE NOTICE 'Renamed table % to %', old_table_name, current_table_name;
END;
$$;


--
-- Name: update_collection_segmentation_logs(); Type: PROCEDURE; Schema: auto_views; Owner: -
--

CREATE PROCEDURE auto_views.update_collection_segmentation_logs()
    LANGUAGE plpgsql
    AS $$
BEGIN

    INSERT INTO public.mv_collection_segmentation_logs
    SELECT
        today.*,
        CURRENT_DATE AS updated_at
    FROM public.mv_collection_segmentation_v0 AS today
    LEFT JOIN (
        SELECT
            consumer_id,
            collection_segment
        FROM (
            SELECT
                consumer_id,
                collection_segment,
                updated_at,
                ROW_NUMBER() OVER (
                    PARTITION BY consumer_id
                    ORDER BY updated_at DESC
                ) AS rn
            FROM public.mv_collection_segmentation_logs
        ) AS ranked
        WHERE rn = 1
    ) AS latest
        ON today.consumer_id = latest.consumer_id
    WHERE latest.consumer_id IS NULL
       OR today.collection_segment <> latest.collection_segment;

END;
$$;


--
-- Name: log_ddl_commands(); Type: FUNCTION; Schema: history_tables; Owner: -
--

CREATE FUNCTION history_tables.log_ddl_commands() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
BEGIN
    FOR rec IN SELECT * FROM pg_event_trigger_ddl_commands()
    LOOP
        INSERT INTO schema_change_alerts (
            username, event_type, command_tag, object_type, schema_name, object_identity, column_name
        )
        VALUES (
            current_user,
            'ddl_command',
            rec.command_tag,
            rec.object_type,
            rec.schema_name,
            rec.object_identity,
            CASE 
                WHEN rec.objsubid > 0 THEN (
                    SELECT attname
                    FROM pg_attribute
                    WHERE attrelid = rec.objid 
                      AND attnum = rec.objsubid
                )
                ELSE NULL 
            END
        );
    END LOOP;
END;
$$;


--
-- Name: log_dropped_objects(); Type: FUNCTION; Schema: history_tables; Owner: -
--

CREATE FUNCTION history_tables.log_dropped_objects() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
BEGIN
    FOR rec IN SELECT * FROM pg_event_trigger_dropped_objects()
    LOOP
        INSERT INTO schema_change_alerts (
            username, event_type, command_tag, object_type, schema_name, object_identity, column_name
        )
        VALUES (
            current_user,
            'drop',
            'DROP',
            rec.object_type,
            rec.schema_name,
            rec.object_identity,
            NULL
        );
    END LOOP;
END;
$$;


--
-- Name: update_installment_due_dates_for_es(); Type: FUNCTION; Schema: loan_management; Owner: -
--

CREATE FUNCTION loan_management.update_installment_due_dates_for_es() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    rows_updated integer;
BEGIN
    WITH es_schedules AS (
        SELECT 
            MAX(ls.line_item_sequence) AS sid,
            ls.loan_account_id AS lid
        FROM loan_management.loan_account_ammortisation_line_item ls
        JOIN loan_management.loan_account l 
            ON l.id = ls.loan_account_id
        WHERE l.sub_state = 'EARLY_SETTLEMENT_REQUESTED'
        GROUP BY ls.loan_account_id
    ),
    es_payments AS (
        SELECT 
            sc.sid,
            sc.lid,
            lap.booked_at
        FROM es_schedules sc
        JOIN loan_management.loan_account_payment lap
            ON sc.lid = lap.loan_account_id
           AND sc.sid = lap.ammortisation_line_item_sequence
    )
    UPDATE loan_management.loan_account_ammortisation_line_item lai
    SET installment_due_date = ep.booked_at
    FROM es_payments ep
    WHERE lai.loan_account_id = ep.lid
      AND lai.line_item_sequence = ep.sid
      AND (lai.installment_due_date IS DISTINCT FROM ep.booked_at)
    RETURNING 1
    INTO rows_updated;

    -- If multiple rows updated, count them:
    IF FOUND THEN
        -- Count how many rows were updated (optional)
        GET DIAGNOSTICS rows_updated = ROW_COUNT;
        RAISE NOTICE 'update_installment_due_dates_for_es: % rows updated', rows_updated;
    ELSE
        RAISE NOTICE 'update_installment_due_dates_for_es: no rows updated';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'update_installment_due_dates_for_es: failed with %: %', SQLERRM, SQLSTATE;
        -- Optionally re-raise if you want the error to be visible to caller:
        -- RAISE;
END;
$$;


--
-- Name: awsdms_intercept_ddl(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.awsdms_intercept_ddl() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
  declare _qry text;
BEGIN
  if (tg_tag='CREATE TABLE' or tg_tag='ALTER TABLE' or tg_tag='DROP TABLE' or tg_tag = 'CREATE TABLE AS') then
	    SELECT current_query() into _qry;
	    insert into public.awsdms_ddl_audit
	    values
	    (
	    default,current_timestamp,current_user,cast(TXID_CURRENT()as varchar(16)),tg_tag,0,'',current_schema,_qry
	    );
	    delete from public.awsdms_ddl_audit;
 end if;
END;
$$;


