--
-- Name: calc_annualized_interest_amount(integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_annualized_interest_amount(tenor_months integer, total_interest_amount numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    annualized_interest_amount NUMERIC;
BEGIN
    annualized_interest_amount := ROUND((((total_interest_amount::FLOAT / tenor_months::FLOAT) * 12)::NUMERIC), 2);
    return annualized_interest_amount;
END;
$$;


--
-- Name: calc_average_weighted_reducing_apr_percent(integer, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_average_weighted_reducing_apr_percent(tenor_months integer, total_interest_amount numeric, total_financed_amount numeric, gross_loan_book_size numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
	reducing_apr_percent NUMERIC;
	portfolio_weight_percent NUMERIC;
BEGIN
    reducing_apr_percent := calc_reducing_apr_percent(tenor_months, total_interest_amount, total_financed_amount);
    portfolio_weight_percent := calc_portfolio_weight_percent(total_financed_amount, gross_loan_book_size);
    return (((reducing_apr_percent / 100) * (portfolio_weight_percent / 100)) * 100);
END;
$$;


--
-- Name: calc_flat_apr_percent(integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_flat_apr_percent(tenor_months integer, total_interest_amount numeric, total_financed_amount numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    flat_apr_percent NUMERIC;
    annualized_interest_amount NUMERIC;
BEGIN
    annualized_interest_amount := calc_annualized_interest_amount(tenor_months, total_interest_amount);
    flat_apr_percent := (annualized_interest_amount::NUMERIC / total_financed_amount::NUMERIC) * 100;
    return flat_apr_percent;
END;
$$;


--
-- Name: calc_lifetime_flat_apr_percent(integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_lifetime_flat_apr_percent(tenor_months integer, total_interest_amount numeric, total_financed_amount numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    flat_apr_percent NUMERIC;
    lifetime_flat_apr_percent NUMERIC;
BEGIN
    flat_apr_percent := calc_flat_apr_percent(tenor_months, total_interest_amount, total_financed_amount);
    lifetime_flat_apr_percent := (flat_apr_percent / 12) * tenor_months;
    return lifetime_flat_apr_percent;
END;
$$;


--
-- Name: calc_monthly_installment_amount(integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_monthly_installment_amount(tenor_months integer, total_interest_amount numeric, total_financed_amount numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    monthly_installment_amount NUMERIC;
BEGIN
    monthly_installment_amount := (total_financed_amount/tenor_months)+(total_financed_amount*((calc_lifetime_flat_apr_percent(tenor_months, total_interest_amount, total_financed_amount) / 100) / tenor_months));
    return monthly_installment_amount;
END;
$$;


--
-- Name: calc_portfolio_weight_percent(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_portfolio_weight_percent(total_financed_amount numeric, gross_loan_book_size numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    portfolio_weight_percent NUMERIC;
BEGIN
    portfolio_weight_percent := (total_financed_amount / gross_loan_book_size) * 100;
    return portfolio_weight_percent;
END;
$$;


--
-- Name: calc_reducing_apr_percent(integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_reducing_apr_percent(tenor_months integer, total_interest_amount numeric, total_financed_amount numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
		monthly_installment_amount NUMERIC;
   	rate NUMERIC;
BEGIN
		monthly_installment_amount := calc_monthly_installment_amount(tenor_months, total_interest_amount, total_financed_amount);
    rate := calculate_rate(tenor_months, monthly_installment_amount, total_financed_amount);
		return (rate * 100);
END;
$$;


