--
-- Name: calculate_pv(numeric, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_pv(rate numeric, months integer, payment numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    pv NUMERIC;
BEGIN
    IF rate = 0 THEN
        pv := payment * months;
    ELSE
        pv := payment * (1 - (1 + rate)^(-months)) / rate;
    END IF;
    RETURN pv;
END;
$$;


--
-- Name: calculate_rate(integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_rate(tenor_months integer, monthly_installment numeric, total_financed_amount numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    rate NUMERIC := 0.05; -- Initial guess (5%)
    tolerance NUMERIC := 1e-7;
    max_iterations INTEGER := 1000;
    iteration INTEGER := 0;
    pv NUMERIC;
    diff NUMERIC;
    derivative NUMERIC;
BEGIN
    LOOP
        pv := calculate_pv(rate, tenor_months, monthly_installment);
        diff := pv - total_financed_amount;

        -- Check for convergence
        IF abs(diff) < tolerance THEN
            RETURN rate * 12; -- Convert monthly rate to annual rate
        END IF;

        -- Calculate the derivative (dPV/drate)
        derivative := (calculate_pv(rate + tolerance, tenor_months, monthly_installment) - pv) / tolerance;

        -- Update the rate using Newton-Raphson
        rate := rate - diff / derivative;

        iteration := iteration + 1;
        IF iteration > max_iterations THEN
            RAISE EXCEPTION 'Newton-Raphson method did not converge';
        END IF;
    END LOOP;
END;
$$;


--
-- Name: create_daily_segmentation_backup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_daily_segmentation_backup() RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
    backup_table_name TEXT;
    current_date_val DATE;
    yesterday_date DATE;
    week_old_date DATE;
    table_to_drop TEXT;

BEGIN
    -- Get current date
    current_date_val := CURRENT_DATE;

 -- Calculate yesterday's date
    yesterday_date := current_date_val - INTERVAL '1 day';
    
    -- Create backup table name in format: backup_YYYY_MM_DD
    backup_table_name := 'segmentation_snapshot_' || TO_CHAR(yesterday_date, 'YYYY_MM_DD');
    
    -- Check if backup for today already exists
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_name = backup_table_name
    ) THEN
        -- Create backup table from source table
        EXECUTE format(
            'CREATE TABLE history_tables.%I AS TABLE public.consumer_segmentation',
            backup_table_name
        );
        
        RAISE NOTICE 'Backup table created: %', backup_table_name;
    ELSE
        RAISE NOTICE 'Backup table already exists: %', backup_table_name;
    END IF;
    
    -- Calculate date 7 days ago for cleanup
    week_old_date := yesterday_date - INTERVAL '7 days';
    
    -- Drop tables older than 7 days
    FOR table_to_drop IN (
        SELECT table_name 
        FROM information_schema.tables 
        WHERE table_name LIKE 'segmentation_snapshot_%'
        AND table_name ~ '^segmentation_snapshot_[0-9]{4}_[0-9]{2}_[0-9]{2}$'
        AND TO_DATE(SUBSTRING(table_name FROM 'segmentation_snapshot_([0-9]{4}_[0-9]{2}_[0-9]{2})$'), 'YYYY_MM_DD') <= week_old_date
    )
    LOOP
        EXECUTE format('DROP TABLE IF EXISTS history_tables.%I', table_to_drop);
        RAISE NOTICE 'Dropped old backup table: %', table_to_drop;
    END LOOP;
    
END;
$_$;


--
-- Name: create_next_loan_partition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_next_loan_partition() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    next_month DATE := date_trunc('month', NOW()) + INTERVAL '1 month';
    next_partition TEXT := 'reporting_loans_' || to_char(next_month, 'YYYY_MM');
    start_date TEXT := to_char(next_month, 'YYYY-MM-DD');
    end_date TEXT := to_char(next_month + INTERVAL '1 month', 'YYYY-MM-DD');
BEGIN
    EXECUTE format(
        'CREATE TABLE IF NOT EXISTS %I PARTITION OF reporting_loans_partitioned
        FOR VALUES FROM (%L) TO (%L);',
        next_partition, start_date, end_date
    );
END;
$$;


--
-- Name: create_next_partition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_next_partition() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    next_month DATE;
    next_partition TEXT;
BEGIN
    next_month := DATE_TRUNC('month', NOW()) + INTERVAL '1 month';
    next_partition := 'merchant_payments_' || TO_CHAR(next_month, 'YYYY_MM');

    EXECUTE format(
        'CREATE TABLE %I PARTITION OF merchant_payments_partitioned
        FOR VALUES FROM (%L) TO (%L);',
        next_partition, next_month, next_month + INTERVAL '1 month'
    );

    RAISE NOTICE 'New partition created: %', next_partition;
END;
$$;


--
-- Name: log_ddl_commands(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_ddl_commands() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
BEGIN
    FOR rec IN SELECT * FROM pg_event_trigger_ddl_commands()
    LOOP
        INSERT INTO schema_change_alerts (
            username, event_type, command_tag, object_type, schema_name, object_identity, column_name
        )
        VALUES (
            current_user,
            'ddl_command',
            rec.command_tag,
            rec.object_type,
            rec.schema_name,
            rec.object_identity,
            CASE 
                WHEN rec.objsubid > 0 THEN (
                    SELECT attname
                    FROM pg_attribute
                    WHERE attrelid = rec.objid 
                      AND attnum = rec.objsubid
                )
                ELSE NULL 
            END
        );
    END LOOP;
END;
$$;


--
-- Name: parse_national_id_dob(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parse_national_id_dob(national_id text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
    dob_text TEXT;
    dob DATE;
BEGIN
    -- Check format first (must be 14 digits and start with 2 or 3)
    IF national_id ~ '^[23][0-9]{13}$' THEN
        dob_text := 
            (1700 + 100 * SUBSTRING(national_id FROM 1 FOR 1)::int +
             SUBSTRING(national_id FROM 2 FOR 2)::int)::text || '-' ||
            LPAD(SUBSTRING(national_id FROM 4 FOR 2), 2, '0') || '-' ||
            LPAD(SUBSTRING(national_id FROM 6 FOR 2), 2, '0');
        
        -- Try converting to date
        BEGIN
            dob := TO_DATE(dob_text, 'YYYY-MM-DD');
        EXCEPTION WHEN others THEN
            RETURN NULL; -- Invalid date like Feb 29 in a non-leap year 1970
        END;

        RETURN dob;
    ELSE
        RETURN NULL; -- Invalid format
    END IF;
END;
$_$;


