--
-- Name: refresh_company_payed_off_loans(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.refresh_company_payed_off_loans()
    LANGUAGE sql
    AS $$
    DROP TABLE IF EXISTS company_payed_off_loans;
    CREATE TABLE company_payed_off_loans AS
    SELECT
        eswc.national_id,
        eswc.egbank_customer_id,
        eswc.invoice_loan_id,
        eswc.egbank_loan_id,
        eswc.consumer_id AS company_customer_id,
        la.updated_at AS booked_at,
        la.sub_state AS type,
        la.merchant_id AS merchant_id
    FROM
        (
            SELECT DISTINCT 
                national_id,
                egbank_customer_id,
                invoice_loan_id,
                egbank_loan_id,
                consumer_id
            FROM mylo.public.egbank_schedule_with_consumers
        ) eswc
    INNER JOIN mylo.loan_management.loan_account la 
        ON la.id = eswc.invoice_loan_id
        AND la.sub_state IN ('EARLY_SETTLEMENT_REQUESTED', 'WITHDRAWN');
$$;


--
-- Name: refresh_company_payed_schedules(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.refresh_company_payed_schedules()
    LANGUAGE sql
    AS $$
    DROP TABLE IF EXISTS company_payed_schedules;
    CREATE TABLE company_payed_schedules AS
    SELECT
        eswc.*,
        laali.loan_account_id,
        lap.booked_at,
        la.merchant_id
    FROM mylo.public.egbank_schedule_with_consumers eswc
    JOIN mylo.loan_management.loan_account la 
        ON la.id = eswc.invoice_loan_id
        AND la.sub_state != 'EARLY_SETTLEMENT_REQUESTED'
    JOIN mylo.loan_management.loan_account_ammortisation_line_item laali 
        ON laali.loan_account_id = eswc.invoice_loan_id
        AND laali.canceled = false
        AND laali.total_paid_units > 0
        AND ((laali.installment_due_date AT TIME ZONE 'Africa/Cairo') 
              AT TIME ZONE 'UTC')::date = 
              TO_CHAR(TO_DATE(payment_maturity_date::text, 'YYYYMMDD'), 'YYYY-MM-DD')::date
    JOIN mylo.loan_management.loan_account_payment lap 
        ON lap.loan_account_id = laali.loan_account_id
        AND lap.ammortisation_line_item_sequence = laali.line_item_sequence;
$$;


--
-- Name: refresh_consumer_analytics_partitioned(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_consumer_analytics_partitioned() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Step 1: Refresh Materialized View
    REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_consumer_analytics;

    -- Step 2: Truncate All Partitions Before Insert
    EXECUTE 'TRUNCATE TABLE public.consumer_analytics_partitioned RESTART IDENTITY CASCADE';

    -- Step 3: Insert New Data into Partitioned Table
    INSERT INTO public.consumer_analytics_partitioned
    SELECT * FROM public.mv_consumer_analytics;

END;
$$;


--
-- Name: refresh_consumer_segmentations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_consumer_segmentations() RETURNS void
    LANGUAGE plpgsql
    AS $_$
BEGIN
    TRUNCATE TABLE public.consumer_segmentation;

    INSERT INTO public.consumer_segmentation (
        consumer_id,
        risk_segment,
        sub_segment
    )
    WITH cons_state AS (
        SELECT
            consumer_id,
            state,
            active_since,
            comment,
            branch
        FROM (
            SELECT
                *,
                RANK() OVER (
                    PARTITION BY consumer_id
                    ORDER BY active_since DESC
                ) AS activation_rank
            FROM consumer_state
        ) t
        WHERE activation_rank = 1
    ),
    region_calc AS (
        SELECT
            "governorate id",
            "cities adjusted",
            CASE
                WHEN "governorate id" = 21
                    THEN 'Giza'
                ELSE "governorate name_en"
            END AS "governorate name_en",
            CASE
                WHEN "governorate id" = 21
                    THEN 'Cairo'
                ELSE regions
            END AS regions
        FROM cities_adjusted_full
    ),
    activ_region AS (
        SELECT DISTINCT
            t1.activation_branch_adjusted,
            t1.unified_city,
            t2.regions
        FROM branches t1
        LEFT JOIN region_calc t2
            ON t1.unified_city = t2."governorate name_en"
    ),
    consumer_address_calc AS (
        SELECT
            consumer_id,
            governorate_id,
            city_id
        FROM consumer_address
        WHERE is_primary = true
    ),
    cons_region AS (
        SELECT DISTINCT
            ca.consumer_id,
            ci.regions
        FROM consumer_address_calc ca
        LEFT JOIN region_calc ci
            ON ca.governorate_id = ci."governorate id"
        WHERE ca.city_id IS NOT NULL
    ),
    active_consumers AS (
        SELECT *
        FROM (
            SELECT
                c.consumer_id,
                c.national_id,
                cp.phone_number_e164 AS phone_number,
                c.origination_channel,
                cons_state.state AS status,
                cons_state.branch,
                cons_region.regions AS home_region,
                activ_region.regions AS activation_region
            FROM consumer_kyc c
            LEFT JOIN consumer_phone cp
                ON cp.consumer_id = c.consumer_id
            LEFT JOIN cons_state
                ON cons_state.consumer_id = c.consumer_id
            LEFT JOIN cons_region
                ON c.consumer_id = cons_region.consumer_id
            LEFT JOIN activ_region
                ON activ_region.activation_branch_adjusted = cons_state.branch
        ) t
        WHERE status IN ('ACTIVE', 'FROZEN')
    ),
    loan_status_calc AS (
        SELECT
            id,
            state,
            sub_state,
            borrower_id
        FROM (
            SELECT
                id,
                state,
                sub_state,
                borrower_id,
                ROW_NUMBER() OVER (
                    PARTITION BY id
                    ORDER BY created_at DESC
                ) AS row_num,
                created_at
            FROM loan_management.loan_account
        ) t
        WHERE row_num = 1
    ),
    dpd_days_per_consumer AS (
        SELECT
            ac.consumer_id,
            SUM(
                GREATEST(
                    0,
                    FLOOR(
                        EXTRACT(
                            DAYS FROM
                            CASE
                                WHEN lap.booked_at IS NULL
                                    THEN NOW() - laa.installment_due_date
                                ELSE lap.booked_at - laa.installment_due_date
                            END
                        )
                    )
                )
            ) AS total_dpd_days,
            COUNT(*) AS installments_due,
            COUNT(
                DISTINCT DATE_TRUNC(
                    'month',
                    laa.installment_due_date
                )::date
            ) AS distinct_installments_due,
            AVG(
                GREATEST(
                    0,
                    FLOOR(
                        EXTRACT(
                            DAYS FROM
                            CASE
                                WHEN lap.booked_at IS NULL
                                    THEN NOW() - laa.installment_due_date
                                ELSE lap.booked_at - laa.installment_due_date
                            END
                        )
                    )
                )
            ) AS avg_dpd_days
        FROM loan_management.loan_account_ammortisation_line_item laa
        LEFT JOIN loan_management.loan_account_payment lap
            ON laa.loan_account_id = lap.loan_account_id
           AND laa.line_item_sequence =
               lap.ammortisation_line_item_sequence
        JOIN loan_status_calc lsc
            ON laa.loan_account_id = lsc.id
        JOIN active_consumers ac
            ON lsc.borrower_id::uuid = ac.consumer_id
        WHERE lsc.state IN ('ACTIVE', 'CLOSED')
          AND laa.installment_due_date <= NOW()
          AND laa.canceled IS false
        GROUP BY ac.consumer_id
    ),
    conc_behave AS (
        SELECT
            consumer_id,
            SUM(
                CASE
                    WHEN merchant_type <> 'NON_BTECH'
                        THEN 1
                    ELSE 0
                END
            ) AS btech_trnx,
            SUM(
                CASE
                    WHEN merchant_type = 'NON_BTECH'
                        THEN 1
                    ELSE 0
                END
            ) AS mylo_trnx
        FROM (
            SELECT
                borrower_id AS consumer_id,
                CASE
                    WHEN merchant_id::text =
                         '09bebad1-8352-4e77-938e-eed5b16fcdf3'::text
                        THEN 'BTECH'
                    ELSE 'NON_BTECH'
                END AS merchant_type
            FROM loan_management.loan_account
            WHERE state = 'ACTIVE'
        ) t
        GROUP BY consumer_id
    ),
    results AS (
        SELECT
            ac.consumer_id,
            ac.national_id,
            ac.phone_number,
            ac.origination_channel,
            ac.branch,
            dp.total_dpd_days,
            dp.installments_due,
            dp.distinct_installments_due,
            dp.avg_dpd_days,
            cb.btech_trnx,
            cb.mylo_trnx,
            CASE
                WHEN dp.avg_dpd_days > 5
                    THEN 'C'
                WHEN dp.avg_dpd_days <= 5
                 AND dp.distinct_installments_due < 3
                    THEN 'B'
                WHEN dp.distinct_installments_due IS NULL
                 AND (
                        COALESCE(cb.btech_trnx, 0)
                        + COALESCE(cb.mylo_trnx, 0)
                     ) > 0
                 AND ac.origination_channel = 'mylo'
                    THEN 'B-Zero_Payments_mylo'
                WHEN dp.distinct_installments_due IS NULL
                 AND (
                        COALESCE(cb.btech_trnx, 0)
                        + COALESCE(cb.mylo_trnx, 0)
                     ) > 0
                 AND ac.origination_channel = 'minicash'
                    THEN 'A-Zero_Payments_minicash'
                WHEN dp.distinct_installments_due IS NULL
                 AND (
                        COALESCE(cb.btech_trnx, 0)
                        + COALESCE(cb.mylo_trnx, 0)
                     ) <= 0
                 AND ac.origination_channel = 'mylo'
                    THEN 'B-mylo'
                WHEN dp.distinct_installments_due IS NULL
                 AND (
                        COALESCE(cb.btech_trnx, 0)
                        + COALESCE(cb.mylo_trnx, 0)
                     ) <= 0
                 AND ac.origination_channel = 'minicash'
                    THEN 'A-minicash'
                WHEN dp.avg_dpd_days <= 5
                 AND dp.distinct_installments_due >= 3
                    THEN 'A-Returning'
                ELSE 'Test'
            END AS sub_class,
            COALESCE(
                ac.home_region,
                ac.activation_region
            ) AS region,
            ac.home_region,
            ac.activation_region
        FROM active_consumers ac
        LEFT JOIN dpd_days_per_consumer dp
            ON dp.consumer_id = ac.consumer_id
        LEFT JOIN conc_behave cb
            ON ac.consumer_id::text = cb.consumer_id::text
    ),
    base_risk_segment AS (
        SELECT
            r.*,
            CASE
                WHEN me.employee_id IS NOT NULL
                 AND r.sub_class <> 'C'
                    THEN 'M'
                WHEN r.sub_class IN (
                    'A-Returning',
                    'A-minicash',
                    'A-Zero_Payments_minicash'
                )
                    THEN 'A'
                WHEN r.sub_class = 'B'
                    THEN 'B'
                WHEN r.sub_class IN (
                    'B-mylo',
                    'B-Zero_Payments_mylo'
                )
                    THEN 'B-'
                ELSE r.sub_class
            END AS original_risk_segment
        FROM results r
        LEFT JOIN mylo_employees me
            ON r.national_id::text = me.employee_id::text
    ),
    -- Select the latest non-null MRI grade, breaking timestamp ties by evaluation_id.
    crg_calc AS (
        SELECT
            br.consumer_id,
            crg.customer_risk_grade,
            crg.created_at,
            CASE
                WHEN crg.created_at >= TIMESTAMPTZ '2026-09-02 21:08:05+00'
                    THEN 'v2'
                ELSE 'v1'
            END AS model_version,
            CASE
                WHEN crg.customer_risk_grade ~ '^CRG[0-9]{1,2}$'
                    THEN REGEXP_REPLACE(crg.customer_risk_grade, '[^0-9]', '', 'g')::integer
                ELSE NULL
            END AS crg_number
        FROM (
            SELECT DISTINCT consumer_id, national_id
            FROM base_risk_segment
            WHERE original_risk_segment = 'B-'
        ) br
        LEFT JOIN LATERAL (
            SELECT
                ooefl.mri_result ->> 'customer_risk_grade' AS customer_risk_grade,
                ooefl.created_at
            FROM midas.orca_open_end_full_evaluation_log ooefl
            WHERE ooefl.consumer_nid = br.national_id
              AND ooefl.mri_result <> 'null'::jsonb
              AND ooefl.mri_result ->> 'customer_risk_grade' IS NOT NULL
            ORDER BY ooefl.created_at DESC NULLS LAST, ooefl.evaluation_id DESC
            LIMIT 1
        ) crg ON TRUE
    ),
    risk_tiers AS (
        SELECT
            cc.*,
            CASE
                WHEN model_version = 'v2' THEN
                    CASE
                        WHEN crg_number BETWEEN 1 AND 7 THEN 'Low'
                        WHEN crg_number BETWEEN 8 AND 11 THEN 'Medium'
                        WHEN crg_number BETWEEN 12 AND 14 THEN 'High'
                        WHEN crg_number BETWEEN 15 AND 16 THEN 'Very high'
                    END
                ELSE
                    CASE
                        WHEN crg_number BETWEEN 1 AND 6 THEN 'Low'
                        WHEN crg_number BETWEEN 7 AND 9 THEN 'Medium'
                        WHEN crg_number BETWEEN 10 AND 11 THEN 'High'
                        WHEN crg_number BETWEEN 12 AND 13 THEN 'Very high'
                    END
            END AS risk_tier
        FROM crg_calc cc
    ),
    final_res AS (
        SELECT
            br.consumer_id,
            CASE
				-- TEMPORARY OVERRIDE: Customer assigned to segment M.
    			-- This adjustment is temporary and should be reverted by 1 Dec 2026.
				WHEN br.consumer_id = 'f0c7a38d-d8db-4475-9ecd-3c7890068d01'::uuid
        		THEN 'M'
                WHEN br.original_risk_segment <> 'B-' THEN br.original_risk_segment
                WHEN cc.risk_tier = 'Low' THEN 'A'
                WHEN cc.risk_tier = 'Medium' THEN 'B'
                WHEN cc.risk_tier = 'High' THEN 'B-'
                WHEN cc.risk_tier = 'Very high' THEN 'C'
                ELSE br.original_risk_segment
            END AS risk_segment,
            CASE
                WHEN br.original_risk_segment <> 'B-' THEN br.sub_class
                WHEN cc.risk_tier = 'Low' THEN 'CRG_LOW'
                WHEN cc.risk_tier = 'Medium' THEN 'CRG_MEDIUM'
                WHEN cc.risk_tier = 'High' THEN 'CRG_HIGH'
                WHEN cc.risk_tier = 'Very high' THEN 'CRG_V_HIGH'
                ELSE br.sub_class
            END AS sub_segment
        FROM base_risk_segment br
        LEFT JOIN risk_tiers cc ON cc.consumer_id = br.consumer_id
    )
    SELECT DISTINCT
        consumer_id,
        risk_segment,
        sub_segment
    FROM final_res
    ON CONFLICT (consumer_id) DO NOTHING;
END;
$_$;


--
-- Name: refresh_loans_schedule_view_and_table(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_loans_schedule_view_and_table() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Step 1: Refresh the Materialized View
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_reporting_loans_schedule;

    -- Step 2: Truncate the partitioned table (to remove old data)
    TRUNCATE TABLE reporting_loans_schedule_partitioned;

    -- Step 3: Insert fresh data from the refreshed Materialized View
    INSERT INTO reporting_loans_schedule_partitioned
SELECT 
    loan_schedule_id, 
    loan_id::UUID,  -- Explicitly cast loan_id to UUID
    due_date, 
    total_financed_amount, 
    due_principal, 
    due_interest, 
    cumulative_principal, 
    remaining_balance, 
    reducing_apr, 
    grace_period_ends_on, 
    paid_date, 
    paid_principal, 
    paid_interest
FROM mv_reporting_loans_schedule;

    -- Log Success (Optional)
    RAISE NOTICE 'Loans Schedule View and Partitioned Table refreshed successfully at %', NOW();
END;
$$;


