-- Name: refresh_merchant_payments_view_ptable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_merchant_payments_view_ptable() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Refresh the materialized view
    REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_merchant_payments;

    -- Truncate the partitioned table and cascade to partitions
    TRUNCATE TABLE public.merchant_payments_partitioned CASCADE;

    -- Insert new records into the partitioned table
    INSERT INTO public.merchant_payments_partitioned
    SELECT 
        merchant_id, 
        merchant_name, 
        id, 
        merchant_account_id, 
        payable_amount, 
        transaction_date, 
        status_timestamp, 
        status, 
        local_transaction_date, 
        expected_payment_date
    FROM public.mv_merchant_payments;

END;
$$;


