--
-- Name: refresh_specific_materialized_views(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_specific_materialized_views() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN 
    EXECUTE 'REFRESH MATERIALIZED VIEW ' || quote_ident('mv_consumer_analytics');
    EXECUTE 'REFRESH MATERIALIZED VIEW ' || quote_ident('mv_migrated_customer');
END; 
$$;


--
-- Name: refresh_view_and_table(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_view_and_table() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Step 1: Refresh the Materialized View
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_reporting_loans;

    -- Step 2: Truncate the partitioned table (remove old data)
    TRUNCATE TABLE reporting_loans_partitioned;

    -- Step 3: Insert fresh data from the refreshed Materialized View
    INSERT INTO reporting_loans_partitioned
    SELECT 
        loan_id::uuid,  -- Ensure loan_id is UUID
        loan_booked_at_utc::timestamp with time zone,  -- Ensure time zone consistency
        loan_created_at_utc::timestamp with time zone, 
        loan_booked_date_local::date, 
        checkout_time_minutes::double precision, 
        loan_status_activated_at_utc::timestamp with time zone, 
        loan_status_cancelled_at_utc::timestamp with time zone, 
        loan_status_early_settled_at_utc::timestamp with time zone, 
        basket_value::double precision, 
        loan_downpayment::double precision, 
        loan_financed_amount::double precision, 
        loan_expected_interest_amount::double precision, 
        loan_admin_fee_amount::double precision, 
        linked_fp_key::text, 
        linked_fp_version::text, 
        linked_fp_selected_tenure::integer, 
        tenor_interest_percent::double precision, 
        annual_interest_percent::double precision, 
        is_profit_bearing::boolean, 
        retail_category::text, 
        consumer_id::uuid,  -- Ensure consumer_id is UUID
        consumer_marital_status::text, 
        consumer_origination_channel::text, 
        consumer_governorate::text, 
        consumer_gender::text, 
        consumer_dob::date, 
        consumer_age::integer,  -- Ensure consumer_age is integer
        consumer_age_range::text, 
        merchant_id::uuid,  -- Ensure merchant_id is UUID
        merchant_name::text, 
        merchant_created_at::timestamp without time zone, 
        merchant_created_at_utc::timestamp with time zone, 
        transacted_merchant_branch_id::uuid,  -- Ensure transacted_merchant_branch_id is UUID
        transacted_merchant_branch_governorate::text, 
        merchant_type::text, 
        consumer_loan_sequence_number::integer,  -- Ensure integer
        merchant_loan_sequence_number::integer, 
        view_last_refreshed_time::timestamp with time zone
    FROM mv_reporting_loans;

    -- Log Success (Optional)
    RAISE NOTICE 'Materialized View and Partitioned Table refreshed successfully at %', NOW();
END;
$$;


