--
-- Name: v_collection_segmentation_v0; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_collection_segmentation_v0 AS
 WITH base AS (
         SELECT unnamed_subquery_1.consumer_id,
            unnamed_subquery_1.due_date,
            unnamed_subquery_1.overdue_flg,
            unnamed_subquery_1.paid_flg,
            unnamed_subquery_1.installment_amount,
            unnamed_subquery_1.delinquency,
                CASE
                    WHEN (unnamed_subquery_1.delinquency <= 30) THEN '1-30'::text
                    WHEN (unnamed_subquery_1.delinquency <= 60) THEN '31-60'::text
                    WHEN (unnamed_subquery_1.delinquency <= 90) THEN '61-90'::text
                    WHEN (unnamed_subquery_1.delinquency > 90) THEN '90+'::text
                    ELSE NULL::text
                END AS delinquency_bucket,
            COALESCE(sum(unnamed_subquery_1.installment_amount) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING), (0)::numeric) AS total_due_amount_acc,
            COALESCE(sum(
                CASE
                    WHEN (unnamed_subquery_1.paid_flg = 1) THEN unnamed_subquery_1.installment_amount
                    ELSE (0)::numeric
                END) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING), (0)::numeric) AS total_paid_acc,
            COALESCE(sum(
                CASE
                    WHEN ((unnamed_subquery_1.paid_flg = 1) AND (unnamed_subquery_1.overdue_flg = 0)) THEN unnamed_subquery_1.installment_amount
                    ELSE (0)::numeric
                END) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING), (0)::numeric) AS total_self_cure_acc,
            COALESCE(sum(
                CASE
                    WHEN (unnamed_subquery_1.overdue_flg = 1) THEN unnamed_subquery_1.installment_amount
                    ELSE (0)::numeric
                END) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING), (0)::numeric) AS total_overdue_amount_acc,
            COALESCE(sum(
                CASE
                    WHEN ((unnamed_subquery_1.overdue_flg = 1) AND (unnamed_subquery_1.paid_flg = 1)) THEN unnamed_subquery_1.installment_amount
                    ELSE (0)::numeric
                END) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING), (0)::numeric) AS total_overdue_paid_acc,
            COALESCE(sum(
                CASE
                    WHEN ((unnamed_subquery_1.overdue_flg = 1) AND (unnamed_subquery_1.paid_flg = 1) AND (unnamed_subquery_1.delinquency <= 30)) THEN unnamed_subquery_1.installment_amount
                    ELSE (0)::numeric
                END) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING), (0)::numeric) AS total_overdue_paid_30_acc,
            COALESCE(sum(
                CASE
                    WHEN ((unnamed_subquery_1.paid_flg = 1) AND ((unnamed_subquery_1.delinquency <= 30) OR (unnamed_subquery_1.delinquency IS NULL))) THEN unnamed_subquery_1.installment_amount
                    ELSE (0)::numeric
                END) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING), (0)::numeric) AS total_paid_30_acc,
            COALESCE(sum(unnamed_subquery_1.installment_amount) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW), (0)::numeric) AS total_due_amount_acc_current,
            COALESCE(sum(
                CASE
                    WHEN (unnamed_subquery_1.paid_flg = 1) THEN unnamed_subquery_1.installment_amount
                    ELSE (0)::numeric
                END) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW), (0)::numeric) AS total_paid_acc_current,
            COALESCE(sum(
                CASE
                    WHEN ((unnamed_subquery_1.paid_flg = 1) AND (unnamed_subquery_1.overdue_flg = 0)) THEN unnamed_subquery_1.installment_amount
                    ELSE (0)::numeric
                END) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW), (0)::numeric) AS total_self_cure_acc_current,
            COALESCE(sum(
                CASE
                    WHEN (unnamed_subquery_1.overdue_flg = 1) THEN unnamed_subquery_1.installment_amount
                    ELSE (0)::numeric
                END) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW), (0)::numeric) AS total_overdue_amount_acc_current,
            COALESCE(sum(
                CASE
                    WHEN ((unnamed_subquery_1.overdue_flg = 1) AND (unnamed_subquery_1.paid_flg = 1)) THEN unnamed_subquery_1.installment_amount
                    ELSE (0)::numeric
                END) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW), (0)::numeric) AS total_overdue_paid_acc_current,
            COALESCE(sum(
                CASE
                    WHEN ((unnamed_subquery_1.overdue_flg = 1) AND (unnamed_subquery_1.paid_flg = 1) AND (unnamed_subquery_1.delinquency <= 30)) THEN unnamed_subquery_1.installment_amount
                    ELSE (0)::numeric
                END) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW), (0)::numeric) AS total_overdue_paid_30_acc_current,
            COALESCE(sum(
                CASE
                    WHEN ((unnamed_subquery_1.paid_flg = 1) AND ((unnamed_subquery_1.delinquency <= 30) OR (unnamed_subquery_1.delinquency IS NULL))) THEN unnamed_subquery_1.installment_amount
                    ELSE (0)::numeric
                END) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.due_date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW), (0)::numeric) AS total_paid_30_acc_current,
            unnamed_subquery_1.rn
           FROM ( SELECT unnamed_subquery_2.consumer_id,
                    unnamed_subquery_2.due_date,
                    unnamed_subquery_2.overdue_flg,
                    unnamed_subquery_2.paid_flg,
                    unnamed_subquery_2.installment_amount,
                    unnamed_subquery_2.delinquency,
                    row_number() OVER (PARTITION BY unnamed_subquery_2.consumer_id ORDER BY unnamed_subquery_2.due_date DESC) AS rn
                   FROM ( SELECT DISTINCT mcb.consumer_id,
                            mcb.due_date,
                            max(mcb.overdue_flg) AS overdue_flg,
                            max(mcb.paid_flg) AS paid_flg,
                            sum(mcb.installment_amount) AS installment_amount,
                            max(mcb.delinquency) AS delinquency
                           FROM public.mv_collection_base mcb
                          WHERE (mcb.due_date < CURRENT_DATE)
                          GROUP BY mcb.consumer_id, mcb.due_date) unnamed_subquery_2) unnamed_subquery_1
          WHERE (unnamed_subquery_1.rn <= 7)
          ORDER BY unnamed_subquery_1.consumer_id, unnamed_subquery_1.due_date DESC
        ), customer_delinq AS (
         SELECT unnamed_subquery_1.consumer_id,
            unnamed_subquery_1.min_due_date,
            unnamed_subquery_1.paid_date,
            unnamed_subquery_1.customer_delinquency,
            lag(unnamed_subquery_1.min_due_date) OVER (PARTITION BY unnamed_subquery_1.consumer_id ORDER BY unnamed_subquery_1.min_due_date DESC) AS nxt_cycle
           FROM ( SELECT mv_consumer_delinquency.consumer_id,
                    mv_consumer_delinquency.min_due_date,
                    max(mv_consumer_delinquency.paid_date) AS paid_date,
                    max(mv_consumer_delinquency.customer_delinq) AS customer_delinquency
                   FROM public.mv_consumer_delinquency
                  GROUP BY mv_consumer_delinquency.consumer_id, mv_consumer_delinquency.min_due_date) unnamed_subquery_1
          ORDER BY unnamed_subquery_1.consumer_id, unnamed_subquery_1.min_due_date
        ), collection_data AS (
         SELECT base.consumer_id,
            base.due_date,
            base.overdue_flg,
            base.paid_flg,
            base.installment_amount,
            base.delinquency,
            base.delinquency_bucket,
            base.total_due_amount_acc,
            base.total_paid_acc,
            base.total_self_cure_acc,
            base.total_overdue_amount_acc,
            base.total_overdue_paid_acc,
            base.total_overdue_paid_30_acc,
            base.total_paid_30_acc,
            base.total_due_amount_acc_current,
            base.total_paid_acc_current,
            base.total_self_cure_acc_current,
            base.total_overdue_amount_acc_current,
            base.total_overdue_paid_acc_current,
            base.total_overdue_paid_30_acc_current,
            base.total_paid_30_acc_current,
            base.rn,
                CASE
                    WHEN (customer_delinq.customer_delinquency <= 30) THEN '1-30'::text
                    WHEN (customer_delinq.customer_delinquency <= 60) THEN '31-60'::text
                    WHEN (customer_delinq.customer_delinquency <= 90) THEN '61-90'::text
                    WHEN (customer_delinq.customer_delinquency > 90) THEN '90+'::text
                    ELSE '0'::text
                END AS cycel_delinquency_bucket
           FROM (base
             LEFT JOIN customer_delinq ON ((((base.consumer_id)::text = (customer_delinq.consumer_id)::text) AND (base.due_date >= customer_delinq.min_due_date) AND (base.due_date < COALESCE(customer_delinq.nxt_cycle, CURRENT_DATE)))))
        ), frequent_bucket AS (
         SELECT collection_data.consumer_id,
            mode() WITHIN GROUP (ORDER BY collection_data.cycel_delinquency_bucket) AS frequent_delinquncy_bucket
           FROM collection_data
          GROUP BY collection_data.consumer_id
        ), final_data AS (
         SELECT collection_data.consumer_id,
            collection_data.due_date,
            collection_data.overdue_flg,
            collection_data.paid_flg,
            collection_data.installment_amount,
            collection_data.delinquency,
            collection_data.delinquency_bucket,
            collection_data.total_due_amount_acc,
            collection_data.total_paid_acc,
            collection_data.total_self_cure_acc,
            collection_data.total_overdue_amount_acc,
            collection_data.total_overdue_paid_acc,
            collection_data.total_overdue_paid_30_acc,
            collection_data.total_paid_30_acc,
            collection_data.total_due_amount_acc_current,
            collection_data.total_paid_acc_current,
            collection_data.total_self_cure_acc_current,
            collection_data.total_overdue_amount_acc_current,
            collection_data.total_overdue_paid_acc_current,
            collection_data.total_overdue_paid_30_acc_current,
            collection_data.total_paid_30_acc_current,
            collection_data.rn,
            collection_data.cycel_delinquency_bucket,
            frequent_bucket.frequent_delinquncy_bucket
           FROM (collection_data
             LEFT JOIN frequent_bucket ON (((collection_data.consumer_id)::text = (frequent_bucket.consumer_id)::text)))
        ), recovery_data AS (
         SELECT DISTINCT final_data.consumer_id,
            final_data.cycel_delinquency_bucket,
            final_data.frequent_delinquncy_bucket,
            COALESCE(final_data.total_due_amount_acc, (0)::numeric) AS total_due_amount_acc,
            COALESCE(final_data.total_overdue_amount_acc, (0)::numeric) AS total_overdue_amount_acc,
                CASE
                    WHEN (final_data.total_overdue_amount_acc > (0)::numeric) THEN (final_data.total_overdue_paid_30_acc / final_data.total_overdue_amount_acc)
                    ELSE (0)::numeric
                END AS rr_30d
           FROM final_data
          WHERE (final_data.rn = 1)
        )
 SELECT consumer_id,
        CASE
            WHEN (collection_score <= 1.9) THEN 'High-Risk'::text
            WHEN (collection_score < 2.80) THEN 'Medium-Risk'::text
            WHEN (collection_score >= 2.80) THEN 'Low-Risk'::text
            ELSE 'Un-known'::text
        END AS collection_segment
   FROM ( SELECT unnamed_subquery_1.consumer_id,
            unnamed_subquery_1.cycel_delinquency_bucket,
            unnamed_subquery_1.frequent_delinquncy_bucket,
            unnamed_subquery_1.total_due_amount_acc,
            unnamed_subquery_1.total_overdue_amount_acc,
            unnamed_subquery_1.rr_30d,
            unnamed_subquery_1.rr_30d_segment,
            unnamed_subquery_1.rr_30d_segment_score,
            unnamed_subquery_1.delinquncy_bucket_score,
            (((unnamed_subquery_1.rr_30d_segment_score)::numeric * 0.6) + ((unnamed_subquery_1.delinquncy_bucket_score)::numeric * 0.4)) AS collection_score
           FROM ( SELECT unnamed_subquery_2.consumer_id,
                    unnamed_subquery_2.cycel_delinquency_bucket,
                    unnamed_subquery_2.frequent_delinquncy_bucket,
                    unnamed_subquery_2.total_due_amount_acc,
                    unnamed_subquery_2.total_overdue_amount_acc,
                    unnamed_subquery_2.rr_30d,
                    unnamed_subquery_2.rr_30d_segment,
                        CASE
                            WHEN (unnamed_subquery_2.rr_30d_segment = 'Red-Flag'::text) THEN 1
                            WHEN (unnamed_subquery_2.rr_30d_segment = 'High-Risk_Late_Paid'::text) THEN 1
                            WHEN (unnamed_subquery_2.rr_30d_segment = 'High-Risk'::text) THEN 1
                            WHEN (unnamed_subquery_2.rr_30d_segment = 'Med-Risk'::text) THEN 2
                            WHEN (unnamed_subquery_2.rr_30d_segment = 'First-Time'::text) THEN 2
                            WHEN (unnamed_subquery_2.rr_30d_segment = 'Low-Risk'::text) THEN 3
                            WHEN (unnamed_subquery_2.rr_30d_segment = 'Zero-Risk'::text) THEN 4
                            ELSE 1000
                        END AS rr_30d_segment_score,
                        CASE
                            WHEN (unnamed_subquery_2.frequent_delinquncy_bucket = '90+'::text) THEN 1
                            WHEN (unnamed_subquery_2.frequent_delinquncy_bucket = '61-90'::text) THEN 2
                            WHEN (unnamed_subquery_2.frequent_delinquncy_bucket = '31-60'::text) THEN 2
                            WHEN (unnamed_subquery_2.frequent_delinquncy_bucket = '1-30'::text) THEN 3
                            WHEN (unnamed_subquery_2.frequent_delinquncy_bucket = '0'::text) THEN 3
                            WHEN (unnamed_subquery_2.frequent_delinquncy_bucket IS NULL) THEN 3
                            ELSE 1000
                        END AS delinquncy_bucket_score
                   FROM ( SELECT recovery_data.consumer_id,
                            recovery_data.cycel_delinquency_bucket,
                            recovery_data.frequent_delinquncy_bucket,
                            recovery_data.total_due_amount_acc,
                            recovery_data.total_overdue_amount_acc,
                            recovery_data.rr_30d,
                                CASE
                                    WHEN ((recovery_data.rr_30d = (0)::numeric) AND (recovery_data.total_due_amount_acc = (0)::numeric)) THEN 'Red-Flag'::text
                                    WHEN ((recovery_data.rr_30d = (0)::numeric) AND (recovery_data.total_due_amount_acc > (0)::numeric) AND (recovery_data.total_overdue_amount_acc = (0)::numeric)) THEN 'First-Time'::text
                                    WHEN ((recovery_data.rr_30d = (0)::numeric) AND (recovery_data.total_due_amount_acc > (0)::numeric) AND (recovery_data.total_overdue_amount_acc > (0)::numeric)) THEN 'High-Risk_Late_Paid'::text
                                    WHEN (recovery_data.cycel_delinquency_bucket = '90+'::text) THEN 'High-Risk'::text
                                    WHEN (recovery_data.rr_30d <= 0.5) THEN 'High-Risk'::text
                                    WHEN (recovery_data.cycel_delinquency_bucket = '61-90'::text) THEN 'Med-Risk'::text
                                    WHEN (recovery_data.rr_30d <= 0.85) THEN 'Med-Risk'::text
                                    WHEN (recovery_data.rr_30d < (1)::numeric) THEN 'Low-Risk'::text
                                    WHEN ((recovery_data.rr_30d = (1)::numeric) AND (recovery_data.cycel_delinquency_bucket = '31-60'::text)) THEN 'Low-Risk'::text
                                    WHEN (recovery_data.rr_30d = (1)::numeric) THEN 'Zero-Risk'::text
                                    ELSE '0'::text
                                END AS rr_30d_segment
                           FROM recovery_data) unnamed_subquery_2) unnamed_subquery_1) unnamed_subquery;


--
-- Name: checkout_baskets; Type: TABLE; Schema: public; Owner: -
