)
WITH (parallel_workers='8');


--
-- Name: v_collections_v1; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_collections_v1 AS
 WITH params AS (
         SELECT ((date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone) + '1 mon -1 days'::interval))::date AS cutoff_date
        ), loan_current_status AS (
         SELECT unnamed_subquery.loan_id,
            unnamed_subquery.status
           FROM ( SELECT loan_status.loan_id,
                    loan_status.status,
                    loan_status.created_at,
                    row_number() OVER (PARTITION BY loan_status.loan_id ORDER BY loan_status.created_at DESC) AS rn
                   FROM public.loan_status) unnamed_subquery
          WHERE (unnamed_subquery.rn = 1)
        ), loan_flag AS (
         SELECT loan_schedule.loan_id,
                CASE
                    WHEN (count(*) = count(loan_schedule.paid_date)) THEN 'FINISHED'::text
                    ELSE 'RUNNING'::text
                END AS loan_status_flag
           FROM public.loan_schedule
          GROUP BY loan_schedule.loan_id
        ), loan_det_all AS (
         SELECT l.id AS l_id,
            l.financial_product_key,
            l.financial_product_version,
            l.correlation_id,
            l.booked_at,
            l.created_at AS l_created_at,
            l.created_by AS l_created_by,
            l.consumer_id,
            ls.id AS ls_id,
            ls.loan_id,
            ls.due_date,
            ls.loan_balance,
            ls.grace_period_end_date,
            ls.paid_date,
            ls.due_principal,
            ls.due_interest,
            ls.due_late_fee,
            ls.paid_principal,
            ls.paid_interest,
            ls.paid_late_fee,
            ls.created_at AS ls_created_at,
            ls.created_by AS ls_created_by,
            ls.updated_at,
            ls.updated_by,
            ls.ref_id,
            ls.is_cancelled,
            lcs.status AS loan_status,
                CASE
                    WHEN ((lcs.status)::text = 'EARLY_SETTLED'::text) THEN 'FINISHED'::text
                    ELSE lf.loan_status_flag
                END AS loan_status_flag
           FROM (((public.loan l
             JOIN public.loan_schedule ls ON (((l.id)::text = (ls.loan_id)::text)))
             JOIN loan_current_status lcs ON (((lcs.loan_id)::text = (l.id)::text)))
             JOIN loan_flag lf ON (((lf.loan_id)::text = (l.id)::text)))
          WHERE ((lcs.status)::text = ANY (ARRAY[('ACTIVE'::character varying)::text, ('EARLY_SETTLED'::character varying)::text]))
        ), loan_det_active AS (
         SELECT lda.l_id AS loan_id,
            lda.consumer_id,
            (((co.financed_amount)::double precision / (100)::double precision) + ((co.down_payment)::double precision / (100)::double precision)) AS basket_value,
            ((co.down_payment)::double precision / (100)::double precision) AS loan_downpayment,
            ((co.financed_amount)::double precision / (100)::double precision) AS loan_financed_amount,
            ((((co.financed_amount)::double precision / (100)::double precision) * (co.interest_rate_per_tenure)::double precision) / (100)::double precision) AS loan_expected_interest_amount,
            lda.due_date,
            date_trunc('month'::text, lda.due_date) AS due_month_year,
            lda.paid_date,
            max(lda.paid_date) FILTER (WHERE (lda.paid_date <= ( SELECT params.cutoff_date
                   FROM params))) OVER (PARTITION BY lda.loan_id) AS last_paid_date,
            min(lda.due_date) FILTER (WHERE (lda.due_date >= ( SELECT params.cutoff_date
                   FROM params))) OVER (PARTITION BY lda.loan_id) AS next_due_date,
            lda.loan_status,
            lda.loan_status_flag,
            (split_part((co.tenure)::text, '_'::text, 1))::integer AS tenor,
            (((lda.due_principal)::double precision + (lda.due_interest)::double precision) / (100)::double precision) AS loan_installment_amount,
            ((((lda.paid_principal)::double precision + (lda.paid_interest)::double precision) + (lda.paid_late_fee)::double precision) / (100)::double precision) AS paid_installment_amount,
            sum(((((lda.due_principal)::double precision / (100)::double precision) + ((lda.due_interest)::double precision / (100)::double precision)) + (lda.paid_late_fee)::double precision)) FILTER (WHERE (lda.paid_date IS NOT NULL)) OVER (PARTITION BY lda.loan_id) AS total_paid_installment_amount,
            sum((((lda.due_principal)::double precision / (100)::double precision) + ((lda.due_interest)::double precision / (100)::double precision))) FILTER (WHERE (lda.paid_date IS NULL)) OVER (PARTITION BY lda.loan_id) AS total_remaining_installment_amount_per_loan,
            count(lda.due_date) FILTER (WHERE (lda.paid_date IS NULL)) OVER (PARTITION BY lda.loan_id) AS num_of_remaining_installments_per_loan,
            COALESCE(sum((((lda.due_principal)::double precision / (100)::double precision) + ((lda.due_interest)::double precision / (100)::double precision))) FILTER (WHERE ((lda.paid_date IS NULL) AND (lda.due_date <= ( SELECT params.cutoff_date
                   FROM params)))) OVER (PARTITION BY lda.loan_id), (0)::double precision) AS total_overdue_installment_amount_per_loan,
            count(lda.paid_date) FILTER (WHERE ((lda.paid_date IS NOT NULL) AND (lda.paid_date <= ( SELECT params.cutoff_date
                   FROM params)))) OVER (PARTITION BY lda.loan_id) AS num_of_paid_installments_per_loan,
            count(lda.due_date) FILTER (WHERE ((lda.paid_date IS NULL) AND (lda.due_date <= ( SELECT params.cutoff_date
                   FROM params)) AND ((lda.loan_status)::text = 'ACTIVE'::text))) OVER (PARTITION BY lda.loan_id) AS num_of_overdue_installments_per_loan,
            sum((((lda.due_principal)::double precision / (100)::double precision) + ((lda.due_interest)::double precision / (100)::double precision))) FILTER (WHERE (((lda.paid_date IS NULL) AND ((lda.loan_status)::text = 'ACTIVE'::text)) OR ((lda.paid_date IS NULL) AND ((lda.loan_status)::text = 'EARLY_SETTLED'::text) AND (lda.paid_date >= ( SELECT params.cutoff_date
                   FROM params))))) OVER (PARTITION BY lda.consumer_id) AS total_remaining_installment_amount_per_consumer,
            count(lda.due_date) FILTER (WHERE (((lda.paid_date IS NULL) AND ((lda.loan_status)::text = 'ACTIVE'::text)) OR ((lda.paid_date IS NULL) AND ((lda.loan_status)::text = 'EARLY_SETTLED'::text) AND (lda.paid_date >= ( SELECT params.cutoff_date
                   FROM params))))) OVER (PARTITION BY lda.consumer_id) AS num_of_remaining_installments_per_consumer,
            COALESCE(sum((((lda.due_principal)::double precision / (100)::double precision) + ((lda.due_interest)::double precision / (100)::double precision))) FILTER (WHERE ((lda.paid_date IS NULL) AND (lda.due_date <= ( SELECT params.cutoff_date
                   FROM params)) AND ((lda.loan_status)::text = 'ACTIVE'::text))) OVER (PARTITION BY lda.consumer_id), (0)::double precision) AS total_overdue_installment_amount_per_consumer,
            count(lda.due_date) FILTER (WHERE ((lda.paid_date IS NULL) AND (lda.due_date <= ( SELECT params.cutoff_date
                   FROM params)) AND ((lda.loan_status)::text = 'ACTIVE'::text))) OVER (PARTITION BY lda.consumer_id) AS num_of_overdue_installments_per_consumer,
            count(lda.paid_date) FILTER (WHERE ((lda.paid_date IS NOT NULL) AND (lda.paid_date <= ( SELECT params.cutoff_date
                   FROM params)))) OVER (PARTITION BY lda.consumer_id) AS num_of_paid_installments_per_consumer,
            cb.category,
                CASE
                    WHEN (COALESCE((((date_part('year'::text, ( SELECT params.cutoff_date
                       FROM params)) - date_part('year'::text, (lda.due_date)::date)) * (12)::double precision) + (date_part('month'::text, ( SELECT params.cutoff_date
                       FROM params)) - date_part('month'::text, (lda.due_date)::date))), (1000)::double precision) >= (0)::double precision) THEN ((COALESCE((((date_part('year'::text, ( SELECT params.cutoff_date
                       FROM params)) - date_part('year'::text, (lda.due_date)::date)) * (12)::double precision) + (date_part('month'::text, ( SELECT params.cutoff_date
                       FROM params)) - date_part('month'::text, (lda.due_date)::date))), (1000)::double precision) + (1)::double precision) * (30)::double precision)
                    ELSE (0)::double precision
                END AS bucket_per_loan
           FROM ((loan_det_all lda
             JOIN public.checkout_baskets cb ON ((((cb.loan_id)::text = (lda.l_id)::text) AND ((cb.status)::text = 'LOAN_ACTIVATED'::text))))
             JOIN public.commercial_offer co ON (((cb.selected_commercial_offer_id)::text = (co.id)::text)))
        ), loan_det_active_1 AS (
         SELECT lda.loan_id,
            lda.consumer_id,
            lda.basket_value,
            lda.loan_downpayment,
            lda.loan_financed_amount,
            lda.loan_expected_interest_amount,
            lda.due_date,
            lda.due_month_year,
            lda.paid_date,
            lda.last_paid_date,
            lda.next_due_date,
            lda.loan_status,
            lda.tenor,
            lda.loan_installment_amount,
            lda.paid_installment_amount,
            lda.total_paid_installment_amount,
                CASE
                    WHEN (((lda.loan_status)::text = 'EARLY_SETTLED'::text) AND (lda.last_paid_date <= ( SELECT params.cutoff_date
                       FROM params))) THEN (0)::double precision
                    ELSE lda.total_remaining_installment_amount_per_loan
                END AS total_remaining_installment_amount_per_loan,
                CASE
                    WHEN (((lda.loan_status)::text = 'EARLY_SETTLED'::text) AND (lda.last_paid_date <= ( SELECT params.cutoff_date
                       FROM params))) THEN (0)::bigint
                    ELSE lda.num_of_remaining_installments_per_loan
                END AS num_of_remaining_installments_per_loan,
                CASE
                    WHEN (((lda.loan_status)::text = 'EARLY_SETTLED'::text) AND (lda.last_paid_date <= ( SELECT params.cutoff_date
                       FROM params))) THEN (0)::double precision
                    ELSE lda.total_overdue_installment_amount_per_loan
                END AS total_overdue_installment_amount_per_loan,
            lda.num_of_paid_installments_per_loan,
            lda.num_of_overdue_installments_per_loan,
            COALESCE(lda.total_remaining_installment_amount_per_consumer, (0)::double precision) AS total_remaining_installment_amount_per_consumer,
            lda.num_of_remaining_installments_per_consumer,
            lda.total_overdue_installment_amount_per_consumer,
            lda.num_of_overdue_installments_per_consumer,
            lda.num_of_paid_installments_per_consumer,
            lda.category,
            lda.bucket_per_loan,
            max(lda.bucket_per_loan) OVER (PARTITION BY lda.consumer_id) AS bucket_per_consumer
           FROM loan_det_active lda
        )
 SELECT loan_id,
    consumer_id,
    basket_value,
    loan_downpayment,
    loan_financed_amount,
    loan_expected_interest_amount,
    due_date,
    due_month_year,
    paid_date,
    last_paid_date,
    next_due_date,
    loan_status,
    tenor,
    loan_installment_amount,
    paid_installment_amount,
    total_paid_installment_amount,
    total_remaining_installment_amount_per_loan,
    num_of_remaining_installments_per_loan,
    total_overdue_installment_amount_per_loan,
    num_of_paid_installments_per_loan,
    num_of_overdue_installments_per_loan,
    total_remaining_installment_amount_per_consumer,
    num_of_remaining_installments_per_consumer,
    total_overdue_installment_amount_per_consumer,
    num_of_overdue_installments_per_consumer,
    num_of_paid_installments_per_consumer,
    category,
    bucket_per_loan,
    bucket_per_consumer
   FROM loan_det_active_1;


--
-- Name: v_consumer_delinquency; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_consumer_delinquency AS
 WITH calendar AS (
         SELECT (generate_series((date_trunc('MONTH'::text, (CURRENT_DATE)::timestamp with time zone) - '5 mons'::interval), (CURRENT_DATE)::timestamp with time zone, '1 day'::interval))::date AS cal_day
        ), customer_delinquency AS (
         SELECT unnamed_subquery.cal_day,
            unnamed_subquery.consumer_id,
            min(unnamed_subquery.due_date) AS min_due_date,
            max(unnamed_subquery.due_date) AS max_due_date,
            min(unnamed_subquery.installment_number) AS min_installment_due,
            max(unnamed_subquery.installment_number) AS max_installment_due,
            max(unnamed_subquery.paid_date) AS paid_date,
            max(unnamed_subquery.customer_delq) AS customer_delinq,
            max(unnamed_subquery.delinquency) AS delinquency,
            sum(unnamed_subquery.installment_amount) AS overdue_amount,
            sum(unnamed_subquery.paid_amount) AS paid_amount
           FROM ( SELECT calendar.cal_day,
                    base.consumer_id,
                    base.due_date,
                    base.installment_number,
                        CASE
                            WHEN (base.paid_date > calendar.cal_day) THEN NULL::date
                            ELSE base.paid_date
                        END AS paid_date,
                    (calendar.cal_day - base.due_date) AS customer_delq,
                    base.delinquency,
                    base.installment_amount,
                        CASE
                            WHEN ((base.paid_date > calendar.cal_day) OR (base.paid_date IS NULL)) THEN (0)::numeric
                            ELSE base.paid_amount
                        END AS paid_amount
                   FROM (calendar
                     JOIN ( SELECT mv_collection_base.loan_id,
                            mv_collection_base.consumer_id,
                            mv_collection_base.loan_schedule_id,
                            mv_collection_base.installment_number,
                            mv_collection_base.principal_amount,
                            mv_collection_base.interest_amount,
                            mv_collection_base.late_fee,
                            mv_collection_base.installment_amount,
                            mv_collection_base.due_date,
                            mv_collection_base.paid_date,
                            mv_collection_base.overdue_flg,
                            mv_collection_base.paid_flg,
                            mv_collection_base.days_paid_after_due,
                            mv_collection_base.delinquency,
                            mv_collection_base.paid_amount,
                            mv_collection_base.paid_late_fee,
                            mv_collection_base.tenor,
                            mv_collection_base.merchant_name,
                            mv_collection_base.transacted_merchant_branch_governorate,
                            mv_collection_base.merchant_region,
                            mv_collection_base.merchant_type,
                            mv_collection_base.retail_category,
                            mv_collection_base.checkout_channel,
                            mv_collection_base.loan_batch_status,
                            mv_collection_base.is_postponed,
                            mv_collection_base.is_rescheduled,
                            mv_collection_base.national_id,
                            mv_collection_base.consumer_gender,
                            mv_collection_base.consumer_age_range,
                            mv_collection_base.job_sector,
                            mv_collection_base.job_category,
                            mv_collection_base.job_name,
                            mv_collection_base.company,
                            mv_collection_base.governorate_home,
                            mv_collection_base.utilization_bucket,
                            mv_collection_base.region,
                            mv_collection_base.first_activated_at,
                            mv_collection_base.origination_channel,
                            mv_collection_base.activation_branch_adjusted,
                            mv_collection_base.activation_type,
                            mv_collection_base.consumer_status,
                            mv_collection_base.i_score,
                            mv_collection_base.classification,
                            mv_collection_base.collection_swat_portfolio_flg
                           FROM public.mv_collection_base
                          WHERE (mv_collection_base.overdue_flg = 1)) base ON (((base.due_date < calendar.cal_day) AND (calendar.cal_day <= COALESCE(base.paid_date, CURRENT_DATE)))))) unnamed_subquery
          GROUP BY unnamed_subquery.cal_day, unnamed_subquery.consumer_id
        ), consumer_info AS (
         SELECT mv_consumers_info.consumer_id,
            mv_consumers_info.national_id,
            mv_consumers_info.full_name,
            mv_consumers_info.consumer_gender,
            mv_consumers_info.consumer_age_range,
            mv_consumers_info.job_sector,
            mv_consumers_info.job_category,
            mv_consumers_info.job_name,
            mv_consumers_info.company,
            mv_consumers_info.governorate_home,
            mv_consumers_info.region,
            mv_consumers_info.first_activated_at,
            mv_consumers_info.origination_channel,
            mv_consumers_info.comment,
            mv_consumers_info.activation_branch_adjusted,
            mv_consumers_info.utilization_bucket,
            mv_consumers_info.status AS consumer_status,
            mv_consumers_info.classification,
            mv_consumers_info.i_score,
            mv_consumers_info.updated_at
           FROM public.mv_consumers_info
        )
 SELECT cd.cal_day,
    cd.consumer_id,
    date_trunc('month'::text, ci.first_activated_at) AS activation_month,
    ci.consumer_gender,
    ci.consumer_age_range,
    ci.utilization_bucket,
    ci.i_score,
    cd.min_due_date,
    cd.max_due_date,
    cd.min_installment_due,
    cd.max_installment_due,
    cd.paid_date,
    cd.customer_delinq,
    cd.delinquency AS max_delinquency,
    cd.overdue_amount,
    cd.paid_amount,
    ci.updated_at
   FROM (customer_delinquency cd
     LEFT JOIN consumer_info ci ON ((((ci.consumer_id)::character varying)::text = (cd.consumer_id)::text)));


