--
-- Name: v_consumer_profile; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_consumer_profile AS
 WITH latest_state AS (
         SELECT DISTINCT ON (consumer_state.consumer_id) consumer_state.consumer_id,
            consumer_state.state,
            consumer_state.active_since
           FROM public.consumer_state
          ORDER BY consumer_state.consumer_id, consumer_state.active_since DESC
        ), core AS (
         SELECT c.id,
            c.created_at,
            ls.state,
            ls.active_since
           FROM (public.new_consumers c
             JOIN latest_state ls ON ((ls.consumer_id = c.id)))
        )
 SELECT core.id,
    core.created_at,
    core.state,
    core.active_since,
    cd.full_name,
    cd.national_id,
    cp.phone_number_e164
   FROM ((core
     LEFT JOIN public.consumer_user_details cd ON ((cd.consumer_id = core.id)))
     LEFT JOIN public.consumer_phone cp ON ((cp.consumer_id = core.id)));


