    is_senior_gov_official boolean,
    scoring_channel character varying(8000),
    job_category text,
    job_sector text,
    mobile_os_type character varying(255),
    verified_income_reason character varying(50),
    other_verified_income_reason text,
    verified_income integer,
    onboarding_channel character varying(50),
    old_club character varying(150),
    old_car_model character varying(150),
    old_house_level character varying(150),
    old_marital_status character varying(150),
