--
-- Name: v_consumers_info; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_consumers_info AS
 WITH deletion_log AS (
         SELECT cal.consumer_id,
            cal.deletion_reason
           FROM public.consumer_archive_log cal
        ), cons_state_calc1 AS (
         SELECT consumer_state.consumer_id,
            consumer_state.state,
            consumer_state.active_since,
            consumer_state.created_by,
            consumer_state.comment,
            consumer_state.branch,
            row_number() OVER (PARTITION BY consumer_state.consumer_id ORDER BY consumer_state.active_since DESC) AS rn_last_overall,
            row_number() OVER (PARTITION BY consumer_state.consumer_id ORDER BY
                CASE
                    WHEN ((consumer_state.state)::text = 'ACTIVE'::text) THEN consumer_state.active_since
                    ELSE NULL::timestamp with time zone
                END) AS rn_first_active,
            row_number() OVER (PARTITION BY consumer_state.consumer_id ORDER BY
                CASE
                    WHEN ((consumer_state.state)::text = 'ACTIVE'::text) THEN consumer_state.active_since
                    ELSE NULL::timestamp with time zone
                END DESC NULLS LAST) AS rn_last_active
           FROM public.consumer_state
        ), cons_state_calc2 AS (
         SELECT cons_state_calc1.consumer_id,
            max(
                CASE
                    WHEN ((cons_state_calc1.rn_first_active = 1) AND ((cons_state_calc1.state)::text = 'ACTIVE'::text)) THEN cons_state_calc1.active_since
                    ELSE NULL::timestamp with time zone
                END) AS first_active_since,
            max(
                CASE
                    WHEN ((cons_state_calc1.rn_last_active = 1) AND ((cons_state_calc1.state)::text = 'ACTIVE'::text)) THEN cons_state_calc1.active_since
                    ELSE NULL::timestamp with time zone
                END) AS last_active_since,
            max(
                CASE
                    WHEN ((cons_state_calc1.rn_first_active = 1) AND ((cons_state_calc1.state)::text = 'ACTIVE'::text)) THEN (cons_state_calc1.branch)::text
                    ELSE NULL::text
                END) AS first_activation_branch,
            max(
                CASE
                    WHEN ((cons_state_calc1.rn_last_active = 1) AND ((cons_state_calc1.state)::text = 'ACTIVE'::text)) THEN (cons_state_calc1.branch)::text
                    ELSE NULL::text
                END) AS last_activation_branch,
            max(
                CASE
                    WHEN ((cons_state_calc1.rn_last_active = 1) AND ((cons_state_calc1.state)::text = 'ACTIVE'::text)) THEN (cons_state_calc1.created_by)::text
                    ELSE NULL::text
                END) AS activated_by,
            max(
                CASE
                    WHEN (cons_state_calc1.rn_last_overall = 1) THEN (cons_state_calc1.state)::text
                    ELSE NULL::text
                END) AS last_state,
            max(
                CASE
                    WHEN (cons_state_calc1.rn_last_overall = 1) THEN cons_state_calc1.active_since
                    ELSE NULL::timestamp with time zone
                END) AS last_active_since_overall,
            max(
                CASE
                    WHEN (cons_state_calc1.rn_last_overall = 1) THEN cons_state_calc1.comment
                    ELSE NULL::text
                END) AS last_comment
           FROM cons_state_calc1
          GROUP BY cons_state_calc1.consumer_id
        ), cons_addr_unified AS (
         SELECT ca.consumer_id,
            max((
                CASE
                    WHEN ((ca.type)::text = 'home'::text) THEN COALESCE(g.name_en, g2.name_en)
                    ELSE NULL::character varying
                END)::text) AS gov_home_en,
            max((
                CASE
                    WHEN ((ca.type)::text = 'national_id'::text) THEN COALESCE(g.name_en, g2.name_en)
                    ELSE NULL::character varying
                END)::text) AS gov_national_id_en,
            max((
                CASE
                    WHEN ((ca.type)::text = 'work'::text) THEN COALESCE(g.name_en, g2.name_en)
                    ELSE NULL::character varying
                END)::text) AS gov_work_en,
            max((
                CASE
                    WHEN ((ca.type)::text = 'home'::text) THEN COALESCE(g.name_ar, g2.name_ar)
                    ELSE NULL::character varying
                END)::text) AS gov_home_ar,
            max((
                CASE
                    WHEN ((ca.type)::text = 'national_id'::text) THEN COALESCE(g.name_ar, g2.name_ar)
                    ELSE NULL::character varying
                END)::text) AS gov_national_id_ar,
            max((
                CASE
                    WHEN ((ca.type)::text = 'work'::text) THEN COALESCE(g.name_ar, g2.name_ar)
                    ELSE NULL::character varying
                END)::text) AS gov_work_ar,
            max((
                CASE
                    WHEN ((ca.type)::text = 'home'::text) THEN c.name_en
                    ELSE NULL::character varying
                END)::text) AS city_home_en,
            max((
                CASE
                    WHEN ((ca.type)::text = 'national_id'::text) THEN c.name_en
                    ELSE NULL::character varying
                END)::text) AS city_national_id_en,
            max((
                CASE
                    WHEN ((ca.type)::text = 'work'::text) THEN c.name_en
                    ELSE NULL::character varying
                END)::text) AS city_work_en,
            max((
                CASE
                    WHEN ((ca.type)::text = 'home'::text) THEN c.name_ar
                    ELSE NULL::character varying
                END)::text) AS city_home_ar,
            max((
                CASE
                    WHEN ((ca.type)::text = 'national_id'::text) THEN c.name_ar
                    ELSE NULL::character varying
                END)::text) AS city_national_id_ar,
            max((
                CASE
                    WHEN ((ca.type)::text = 'work'::text) THEN c.name_ar
                    ELSE NULL::character varying
                END)::text) AS city_work_ar,
            max(
                CASE
                    WHEN ((ca.type)::text = 'home'::text) THEN ca.address_line_1
                    ELSE NULL::text
                END) AS address_home,
            max(
                CASE
                    WHEN ((ca.type)::text = 'national_id'::text) THEN ca.address_line_1
                    ELSE NULL::text
                END) AS address_national_id,
            max(
                CASE
                    WHEN ((ca.type)::text = 'work'::text) THEN ca.address_line_1
                    ELSE NULL::text
                END) AS address_work,
            max(
                CASE
                    WHEN ((ca.type)::text = 'home'::text) THEN ca.governorate_id
                    ELSE NULL::integer
                END) AS id_governorate_home,
            max(
                CASE
                    WHEN ((ca.type)::text = 'home'::text) THEN ca.city_id
                    ELSE NULL::integer
                END) AS id_city_home,
            max(
                CASE
                    WHEN ((ca.type)::text = 'home'::text) THEN ca.area_id
                    ELSE NULL::integer
                END) AS id_area_home,
            max(
                CASE
                    WHEN ((ca.type)::text = 'work'::text) THEN ca.governorate_id
                    ELSE NULL::integer
                END) AS id_governorate_work,
            max(
                CASE
                    WHEN ((ca.type)::text = 'work'::text) THEN ca.city_id
                    ELSE NULL::integer
                END) AS id_city_work,
            max(
                CASE
                    WHEN ((ca.type)::text = 'work'::text) THEN ca.area_id
                    ELSE NULL::integer
                END) AS id_area_work,
            max(
                CASE
                    WHEN ((ca.type)::text = 'national_id'::text) THEN ca.governorate_id
                    ELSE NULL::integer
                END) AS id_governorate_national_id,
            max(
                CASE
                    WHEN ((ca.type)::text = 'national_id'::text) THEN ca.city_id
                    ELSE NULL::integer
                END) AS id_city_national_id,
            max(
                CASE
                    WHEN ((ca.type)::text = 'national_id'::text) THEN ca.area_id
                    ELSE NULL::integer
                END) AS id_area_national_id
           FROM (((( SELECT DISTINCT ON (consumer_address.consumer_id, consumer_address.type) consumer_address.consumer_id,
                    consumer_address.type,
                    consumer_address.address_line_1,
                    consumer_address.governorate_id,
                    consumer_address.city_id,
                    consumer_address.area_id,
                    consumer_address.created_at
                   FROM public.consumer_address
                  WHERE ((consumer_address.type)::text = ANY (ARRAY['home'::text, 'work'::text, 'national_id'::text]))
                  ORDER BY consumer_address.consumer_id, consumer_address.type, consumer_address.created_at DESC) ca
             LEFT JOIN public.cities c ON ((c.id = ca.city_id)))
             LEFT JOIN public.governorates g ON ((g.id = c.governorate_id)))
             LEFT JOIN public.governorates g2 ON ((g2.id = ca.governorate_id)))
          GROUP BY ca.consumer_id
        ), consumer_kyc_calc AS (
         SELECT c.consumer_id AS id,
            cp.phone_number_e164 AS phone_number,
            csc2.last_state AS status,
            n.identity_id AS iam_id,
            cud.full_name,
            cud.first_name,
            cud.last_name,
                CASE
                    WHEN (c.national_id IS NULL) THEN cud.national_id
                    ELSE c.national_id
                END AS national_id,
            c.company_name AS company,
            COALESCE((ic.name_en)::text, (c.job_title)::text) AS job_name,
            COALESCE((ic.name_ar)::text, (c.job_title)::text) AS job_name_ar,
            COALESCE((ies.name_en)::text, c.job_category) AS job_category,
            COALESCE((sec.name_en)::text, c.job_sector) AS job_sector,
            COALESCE(ec.name_en, c.club) AS club,
            COALESCE(lt.status_name_en, c.marital_status) AS marital_status,
            COALESCE(ten.status_name_en, c.house_level) AS house_type,
            cau.gov_home_en AS governorate,
            c.primary_income AS salary,
            c.additional_income AS additional_salary,
            c.car_year,
            (csc2.last_active_since AT TIME ZONE 'Africa/Cairo'::text) AS activated_at,
            (csc2.first_active_since AT TIME ZONE 'Africa/Cairo'::text) AS first_activated_at,
            n.created_at,
            (csc2.last_active_since_overall AT TIME ZONE 'Africa/Cairo'::text) AS updated_at,
            c.single_payment_day,
            c.origination_channel,
            c.other_company_name AS additional_salary_source,
            cau.address_work AS company_address,
            cau.address_national_id AS national_id_address,
            csc2.activated_by AS activated_by_iam_id,
            csc2.first_activation_branch AS activation_branch,
            csc2.last_activation_branch AS activation_branch_new,
            c.updated_by,
            csc2.last_comment AS comment,
            c.scoring_channel
           FROM (((((((((((public.consumer_kyc c
             LEFT JOIN public.new_consumers n ON ((n.id = c.consumer_id)))
             LEFT JOIN lookup_tables.int_marital_status lt ON (((c.marital_status)::text = (lt.id)::text)))
             LEFT JOIN lookup_tables.eg_clubs ec ON (((c.club)::text = (ec.id)::text)))
             LEFT JOIN lookup_tables.int_occupation ic ON (((c.job_title)::text = (ic.code)::text)))
             LEFT JOIN lookup_tables.int_employment_status ies ON ((c.job_category = (ies.code)::text)))
             LEFT JOIN lookup_tables.int_employment_sector sec ON ((c.job_sector = (sec.id)::text)))
             LEFT JOIN lookup_tables.int_housing_tenures ten ON (((c.house_level)::text = (ten.id)::text)))
             LEFT JOIN cons_state_calc2 csc2 ON ((csc2.consumer_id = c.consumer_id)))
             LEFT JOIN public.consumer_phone cp ON (((cp.consumer_id = c.consumer_id) AND (cp.is_primary = true) AND (cp.is_active = true))))
             LEFT JOIN ( SELECT DISTINCT ON (consumer_user_details.consumer_id) consumer_user_details.consumer_id,
                    consumer_user_details.full_name,
                    consumer_user_details.first_name,
                    consumer_user_details.last_name,
                    consumer_user_details.national_id
                   FROM public.consumer_user_details
                  ORDER BY consumer_user_details.consumer_id, consumer_user_details.created_at DESC) cud ON ((cud.consumer_id = c.consumer_id)))
             LEFT JOIN cons_addr_unified cau ON ((cau.consumer_id = c.consumer_id)))
        ), clients AS (
         SELECT DISTINCT ON (dim_clients.ssn) dim_clients.clientid,
            dim_clients.registerdate,
            dim_clients.ssn,
            dim_clients.branchname,
            TRIM(BOTH FROM dim_clients.clientclass) AS clientclass
           FROM public.dim_clients
          ORDER BY dim_clients.ssn, dim_clients.registerdate DESC
        ), all_consumers AS (
         SELECT c.id AS consumer_id,
            cs.clientid,
            c.phone_number,
            c.status,
            c.full_name,
            c.first_name,
            c.last_name,
            c.national_id,
            public.parse_national_id_dob((c.national_id)::text) AS consumer_dob,
            c.job_name,
            c.job_name_ar,
            c.job_category,
            c.job_sector,
            c.company,
            c.club,
            c.house_type,
            c.governorate,
            ((c.salary)::numeric / (100)::numeric) AS salary_egp,
            COALESCE(c.additional_salary, 0) AS additional_salary,
            c.car_year,
            c.marital_status,
            c.activated_at,
            c.first_activated_at,
            c.created_at,
            c.updated_at,
            c.single_payment_day,
            c.origination_channel,
            c.additional_salary_source,
            c.company_address,
            c.national_id_address,
            c.scoring_channel,
                CASE
                    WHEN (((cs.registerdate >= c.created_at) AND (cs.registerdate < (c.created_at + '1 day'::interval))) OR ((c.origination_channel)::text = 'mylo'::text)) THEN 'MCN'::text
                    ELSE 'MCR'::text
                END AS new_returning_flag,
            c.updated_by,
            c.comment,
            c.activated_by_iam_id,
            c.activation_branch,
            c.activation_branch_new,
                CASE
                    WHEN ((c.activation_branch IS NULL) OR (c.activation_branch = ''::text)) THEN (cs.branchname)::text
                    WHEN ((c.created_at >= '2024-01-01 00:00:00'::timestamp without time zone) AND (c.created_at <= '2024-09-04 00:00:00'::timestamp without time zone)) THEN 'Asyut'::text
                    ELSE c.activation_branch
                END AS activation_branch_adjusted
           FROM (consumer_kyc_calc c
             LEFT JOIN clients cs ON ((TRIM(BOTH FROM c.national_id) = TRIM(BOTH FROM cs.ssn))))
        ), loc AS (
         SELECT DISTINCT ON (ca.consumer_id) ca.consumer_id,
            ca.governorate_id,
            ca.city_id,
            COALESCE(ci."governorate name_en", ci2."governorate name_en") AS governorate_loc,
            ci.regions
           FROM ((public.consumer_address ca
             LEFT JOIN public.cities_adjusted_full ci ON (((ca.governorate_id = ci."governorate id") AND (ca.city_id = ci.id))))
             LEFT JOIN public.cities_adjusted_full ci2 ON (((ca.governorate_id = ci2."governorate id") AND (ca.city_id IS NULL))))
          WHERE ((ca.city_id IS NOT NULL) AND ((ca.type)::text = 'home'::text) AND (ca.is_active = true))
          ORDER BY ca.consumer_id, ca.created_at DESC
        ), consumer_calc_1 AS (
         SELECT DISTINCT c.consumer_id,
            c.clientid,
            c.phone_number,
            c.status,
            c.full_name,
            c.first_name,
            c.last_name,
            c.national_id,
            c.consumer_dob,
            c.job_name,
            c.job_name_ar,
            c.job_category,
            c.job_sector,
            c.company,
            c.club,
            c.house_type,
            c.governorate,
            c.salary_egp,
            c.additional_salary,
            c.car_year,
            c.marital_status,
            c.activated_at,
            c.first_activated_at,
            c.created_at,
            c.updated_at,
            c.single_payment_day,
            c.origination_channel,
            c.additional_salary_source,
            c.company_address,
            c.national_id_address,
            c.scoring_channel,
            c.new_returning_flag,
            c.updated_by,
            c.comment,
            c.activated_by_iam_id,
            c.activation_branch,
            c.activation_branch_new,
            c.activation_branch_adjusted,
            COALESCE(b1.unified_city, b.unified_city) AS unified_city,
                CASE
                    WHEN (c.consumer_dob IS NULL) THEN 'NOT_VALID'::text
                    WHEN ((length((c.national_id)::text) = 14) AND ((SUBSTRING(c.national_id FROM 4 FOR 2))::integer <= 12) AND ((SUBSTRING(c.national_id FROM 6 FOR 2))::integer <= 31)) THEN 'VALID'::text
                    ELSE 'NOT_VALID'::text
                END AS national_id_validity,
                CASE
                    WHEN (c.consumer_dob IS NULL) THEN NULL::text
                    WHEN (((SUBSTRING(c.national_id FROM 13 FOR 1))::integer % 2) = 1) THEN 'MALE'::text
                    ELSE 'FEMALE'::text
                END AS consumer_gender,
            EXTRACT(year FROM age((c.consumer_dob)::timestamp with time zone)) AS consumer_age,
            loc.governorate_loc,
            loc.regions
           FROM (((all_consumers c
             LEFT JOIN loc ON ((c.consumer_id = loc.consumer_id)))
             LEFT JOIN public.branches b ON ((c.activation_branch = b.activation_branch_adjusted)))
             LEFT JOIN public.branches b1 ON ((c.activation_branch_new = b1.activation_branch_adjusted)))
        ), credit_limit AS (
         SELECT ccl.consumer_id,
            (COALESCE(ccl.max_credit_limit, 0) / 100) AS max_credit_limit_egp,
            (COALESCE(ccl.available_credit_limit, 0) / 100) AS available_credit_limit_egp,
            COALESCE(
                CASE
                    WHEN (ccl.max_credit_limit = 0) THEN NULL::numeric
                    WHEN (((((ccl.max_credit_limit - ccl.available_credit_limit))::numeric * 100.0) / (ccl.max_credit_limit)::numeric) < (1)::numeric) THEN ceil(((((ccl.max_credit_limit - ccl.available_credit_limit))::numeric * 100.0) / (ccl.max_credit_limit)::numeric))
                    ELSE round(((((ccl.max_credit_limit - ccl.available_credit_limit))::numeric * 100.0) / (ccl.max_credit_limit)::numeric))
                END, (0)::numeric) AS credit_utilization,
            ccl.active_since AS credit_limit_active_since
           FROM ( SELECT consumer_credit_limits.id,
                    consumer_credit_limits.consumer_id,
                    consumer_credit_limits.max_credit_limit,
                    consumer_credit_limits.available_credit_limit,
                    consumer_credit_limits.active_since,
                    consumer_credit_limits.created_at,
                    consumer_credit_limits.updated_at,
                    consumer_credit_limits.updated_by,
                    consumer_credit_limits.source,
                    row_number() OVER (PARTITION BY consumer_credit_limits.consumer_id ORDER BY consumer_credit_limits.updated_at DESC, consumer_credit_limits.created_at DESC) AS row_num
                   FROM public.consumer_credit_limits) ccl
          WHERE (ccl.row_num = 1)
        ), churn_status_btech AS (
         SELECT cbn.consumer_id,
                CASE
                    WHEN (sum(
                    CASE
                        WHEN (ls.total_paid_units = 0) THEN 1
                        ELSE 0
                    END) = 0) THEN 1
                    ELSE 0
                END AS finisher_btech,
                CASE
                    WHEN (sum(
                    CASE
                        WHEN (ls.total_paid_units = 0) THEN 1
                        ELSE 0
                    END) <= 2) THEN 1
                    ELSE 0
                END AS pre_finsher_btech,
                CASE
                    WHEN (sum(
                    CASE
                        WHEN (ls.total_paid_units = 0) THEN 1
                        ELSE 0
                    END) > 2) THEN 1
                    ELSE 0
                END AS running_btech
           FROM (loan_management.loan_account_ammortisation_line_item ls
             JOIN public.checkout_baskets cbn ON (((cbn.loan_id = (ls.loan_account_id)::uuid) AND (cbn.partner_id = '09bebad1-8352-4e77-938e-eed5b16fcdf3'::uuid))))
          WHERE (((cbn.status)::text = 'LOAN_ACTIVATED'::text) AND (ls.canceled = false))
          GROUP BY cbn.consumer_id
        ), churn_status_non_btech AS (
         SELECT cbn.consumer_id,
                CASE
                    WHEN (sum(
                    CASE
                        WHEN (ls.total_paid_units = 0) THEN 1
                        ELSE 0
                    END) = 0) THEN 1
                    ELSE 0
                END AS finisher_non_btech,
                CASE
                    WHEN (sum(
                    CASE
                        WHEN (ls.total_paid_units = 0) THEN 1
                        ELSE 0
                    END) <= 2) THEN 1
                    ELSE 0
                END AS pre_finsher_non_btech,
                CASE
                    WHEN (sum(
                    CASE
                        WHEN (ls.total_paid_units = 0) THEN 1
                        ELSE 0
                    END) > 2) THEN 1
                    ELSE 0
                END AS running_non_btech
           FROM (loan_management.loan_account_ammortisation_line_item ls
             JOIN public.checkout_baskets cbn ON (((cbn.loan_id = (ls.loan_account_id)::uuid) AND (cbn.partner_id <> '09bebad1-8352-4e77-938e-eed5b16fcdf3'::uuid))))
          WHERE (((cbn.status)::text = 'LOAN_ACTIVATED'::text) AND (ls.canceled = false))
          GROUP BY cbn.consumer_id
        ), i_score AS (
         SELECT t.national_id,
            t.i_score,
            t.last_created_at
           FROM ( SELECT c.nid AS national_id,
                    ((c.consumer_credit_data_instance ->> 'fico_score'::text))::integer AS i_score,
                    c.created_at AS last_created_at,
                    row_number() OVER (PARTITION BY c.nid ORDER BY c.created_at DESC) AS rn
                   FROM midas.new_consumer_credit_data c) t
          WHERE (t.rn = 1)
        ), application_reason AS (
         SELECT t.consumer_id,
                CASE
                    WHEN (t.reason = ANY (ARRAY['CONSUMER_IN_TERRORIST_LIST'::text, 'CONSUMER_IN_SACNTION_LIST'::text])) THEN true
                    ELSE false
                END AS terrorist_or_sanction_flag
           FROM ( SELECT ca.consumer_id,
                    cas.reason,
                    row_number() OVER (PARTITION BY ca.consumer_id ORDER BY cas.created_at DESC) AS rn
                   FROM (public.consumer_application ca
                     JOIN public.consumer_application_state cas ON ((ca.id = cas.consumer_application_id)))) t
          WHERE (t.rn = 1)
        ), latest_app_state AS (
         SELECT DISTINCT ON (ca.consumer_id) ca.consumer_id,
            ca.id AS application_id,
            (ca.data ->> 'step'::text) AS app_step,
            cas.state AS app_state
           FROM (public.consumer_application ca
             JOIN public.consumer_application_state cas ON ((cas.consumer_application_id = ca.id)))
          ORDER BY ca.consumer_id, cas.created_at DESC
        ), ob_segment AS (
         SELECT DISTINCT ON (segments.consumer_id) segments.consumer_id,
            segments.ob_segment
           FROM ( SELECT ck.consumer_id,
                    'S1_V1'::text AS ob_segment
                   FROM public.consumer_kyc ck
                  WHERE (((ck.education_level)::text = ANY (ARRAY[('7'::character varying)::text, ('8'::character varying)::text, ('9'::character varying)::text])) AND (ck.job_category = ANY (ARRAY['106'::text, '107'::text])) AND ((ck.job_title)::text ~ similar_to_escape('(1|2|3)%'::text)) AND (EXISTS ( SELECT 1
                           FROM midas.onboarding_monitoring obm
                          WHERE (((obm.consumer_nid)::text = (ck.national_id)::text) AND (obm.plausibility_passed_rules @> '[{"rule_name": "check_insurance_organization_v1"}]'::jsonb)))) AND (EXTRACT(year FROM age((public.parse_national_id_dob((ck.national_id)::text))::timestamp with time zone)) >= (18)::numeric) AND (EXTRACT(year FROM age((public.parse_national_id_dob((ck.national_id)::text))::timestamp with time zone)) <= (45)::numeric) AND ((ck.origination_channel)::text = 'mylo'::text))
                UNION ALL
                 SELECT ck.consumer_id,
                    'S2_V1'::text AS ob_segment
                   FROM (public.consumer_kyc ck
                     JOIN clients cs ON ((TRIM(BOTH FROM cs.ssn) = TRIM(BOTH FROM ck.national_id))))
                  WHERE (((ck.origination_channel)::text = 'minicash'::text) AND (cs.clientclass = 'A'::text))) segments
          ORDER BY segments.consumer_id
        ), consumer_calc_final AS (
         SELECT c.consumer_id,
            c.clientid,
            c.phone_number,
                CASE
                    WHEN ((c.status = 'AWAITING_ACTIVATION'::text) AND ((las.app_state)::text = 'PENDING_ACTIVATION_APPROVAL'::text)) THEN 'PENDING_APPROVAL'::text
                    ELSE c.status
                END AS status,
            c.full_name,
            c.first_name,
            c.last_name,
            c.national_id,
            c.consumer_dob,
            c.job_name,
            c.job_name_ar,
            c.job_category,
            c.job_sector,
            c.company,
            c.club,
            c.house_type,
            c.salary_egp,
            c.additional_salary,
            c.car_year,
            c.marital_status,
            c.activated_at,
            c.first_activated_at,
            c.created_at,
            c.updated_at,
            c.single_payment_day,
            c.origination_channel,
            c.additional_salary_source,
            c.scoring_channel,
            c.new_returning_flag,
            c.updated_by,
            c.comment,
            c.activated_by_iam_id,
            c.activation_branch,
            c.activation_branch_new,
            c.activation_branch_adjusted,
            c.unified_city,
            c.national_id_validity,
            c.consumer_gender,
            c.consumer_age,
                CASE
                    WHEN (c.consumer_age IS NULL) THEN NULL::text
                    WHEN (c.consumer_age < (18)::numeric) THEN '0-18 yrs'::text
                    WHEN ((c.consumer_age >= (18)::numeric) AND (c.consumer_age <= (24)::numeric)) THEN '18-24 yrs'::text
                    WHEN ((c.consumer_age >= (25)::numeric) AND (c.consumer_age <= (34)::numeric)) THEN '25-34 yrs'::text
                    WHEN ((c.consumer_age >= (35)::numeric) AND (c.consumer_age <= (44)::numeric)) THEN '35-44 yrs'::text
                    WHEN ((c.consumer_age >= (45)::numeric) AND (c.consumer_age <= (54)::numeric)) THEN '45-54 yrs'::text
                    WHEN ((c.consumer_age >= (55)::numeric) AND (c.consumer_age <= (64)::numeric)) THEN '55-64 yrs'::text
                    WHEN ((c.consumer_age >= (65)::numeric) AND (c.consumer_age <= (74)::numeric)) THEN '65-74 yrs'::text
                    WHEN ((c.consumer_age >= (75)::numeric) AND (c.consumer_age <= (84)::numeric)) THEN '75-84 yrs'::text
                    ELSE '85+ yrs'::text
                END AS consumer_age_range,
            c.regions AS region,
                CASE
                    WHEN ((c.salary_egp + (c.additional_salary)::numeric) = (0)::numeric) THEN '=0'::text
                    WHEN (((c.salary_egp + (c.additional_salary)::numeric) >= (1)::numeric) AND ((c.salary_egp + (c.additional_salary)::numeric) <= (10000)::numeric)) THEN '0-10K'::text
                    WHEN (((c.salary_egp + (c.additional_salary)::numeric) >= (10001)::numeric) AND ((c.salary_egp + (c.additional_salary)::numeric) <= (20000)::numeric)) THEN '10-20K'::text
                    WHEN (((c.salary_egp + (c.additional_salary)::numeric) >= (20001)::numeric) AND ((c.salary_egp + (c.additional_salary)::numeric) <= (30000)::numeric)) THEN '20-30K'::text
                    WHEN (((c.salary_egp + (c.additional_salary)::numeric) >= (30001)::numeric) AND ((c.salary_egp + (c.additional_salary)::numeric) <= (40000)::numeric)) THEN '30-40K'::text
                    WHEN (((c.salary_egp + (c.additional_salary)::numeric) >= (40001)::numeric) AND ((c.salary_egp + (c.additional_salary)::numeric) <= (50000)::numeric)) THEN '40-50K'::text
                    WHEN (((c.salary_egp + (c.additional_salary)::numeric) >= (50001)::numeric) AND ((c.salary_egp + (c.additional_salary)::numeric) <= (60000)::numeric)) THEN '50-60K'::text
                    WHEN (((c.salary_egp + (c.additional_salary)::numeric) >= (60001)::numeric) AND ((c.salary_egp + (c.additional_salary)::numeric) <= (70000)::numeric)) THEN '60-70K'::text
                    WHEN (((c.salary_egp + (c.additional_salary)::numeric) >= (70001)::numeric) AND ((c.salary_egp + (c.additional_salary)::numeric) <= (80000)::numeric)) THEN '70-80K'::text
                    WHEN (((c.salary_egp + (c.additional_salary)::numeric) >= (80001)::numeric) AND ((c.salary_egp + (c.additional_salary)::numeric) <= (90000)::numeric)) THEN '80-90K'::text
                    WHEN (((c.salary_egp + (c.additional_salary)::numeric) >= (90001)::numeric) AND ((c.salary_egp + (c.additional_salary)::numeric) <= (100000)::numeric)) THEN '90-100K'::text
                    WHEN ((c.salary_egp + (c.additional_salary)::numeric) > (100000)::numeric) THEN '>100K'::text
                    ELSE ((c.salary_egp + (c.additional_salary)::numeric))::text
                END AS income_bucket,
                CASE
                    WHEN (cl.max_credit_limit_egp <= 0) THEN '=0'::text
                    WHEN ((cl.max_credit_limit_egp >= 1) AND (cl.max_credit_limit_egp <= 20000)) THEN '0-20K'::text
                    WHEN ((cl.max_credit_limit_egp >= 20001) AND (cl.max_credit_limit_egp <= 40000)) THEN '20-40K'::text
                    WHEN ((cl.max_credit_limit_egp >= 40001) AND (cl.max_credit_limit_egp <= 60000)) THEN '40-60K'::text
                    WHEN ((cl.max_credit_limit_egp >= 60001) AND (cl.max_credit_limit_egp <= 80000)) THEN '60-80K'::text
                    WHEN ((cl.max_credit_limit_egp >= 80001) AND (cl.max_credit_limit_egp <= 100000)) THEN '80-100K'::text
                    WHEN ((cl.max_credit_limit_egp >= 100001) AND (cl.max_credit_limit_egp <= 200000)) THEN '100-200K'::text
                    WHEN ((cl.max_credit_limit_egp >= 200001) AND (cl.max_credit_limit_egp <= 300000)) THEN '200-300K'::text
                    WHEN (cl.max_credit_limit_egp > 300000) THEN '>300K'::text
                    ELSE '>=100K'::text
                END AS credit_limit_bucket,
            cl.max_credit_limit_egp,
            cl.available_credit_limit_egp,
            cl.credit_utilization,
                CASE
                    WHEN (cl.credit_utilization = (0)::numeric) THEN '=0%'::text
                    WHEN ((cl.credit_utilization >= (1)::numeric) AND (cl.credit_utilization <= (20)::numeric)) THEN '0%-20%'::text
                    WHEN ((cl.credit_utilization >= (21)::numeric) AND (cl.credit_utilization <= (40)::numeric)) THEN '20%-40%'::text
                    WHEN ((cl.credit_utilization >= (41)::numeric) AND (cl.credit_utilization <= (60)::numeric)) THEN '40%-60%'::text
                    WHEN ((cl.credit_utilization >= (61)::numeric) AND (cl.credit_utilization <= (80)::numeric)) THEN '60%-80%'::text
                    WHEN ((cl.credit_utilization >= (81)::numeric) AND (cl.credit_utilization <= (100)::numeric)) THEN '80%-100%'::text
                    ELSE '=0%'::text
                END AS utilization_bucket,
            cl.credit_limit_active_since,
                CASE
                    WHEN (csb.finisher_btech = 1) THEN 'Finisher'::text
                    WHEN (csb.pre_finsher_btech = 1) THEN 'Pre_Finisher'::text
                    WHEN (csb.running_btech = 1) THEN 'Running'::text
                    ELSE 'Non_Transacted'::text
                END AS churn_status_btech,
                CASE
                    WHEN (csn.finisher_non_btech = 1) THEN 'Finisher'::text
                    WHEN (csn.pre_finsher_non_btech = 1) THEN 'Pre_Finisher'::text
                    WHEN (csn.running_non_btech = 1) THEN 'Running'::text
                    ELSE 'Non_Transacted'::text
                END AS churn_status_non_btech,
            COALESCE(cau.gov_home_en, (c.governorate_loc)::text, 'Unknown Governorate'::text) AS governorate_home,
            cau.city_home_en AS city_home,
            cau.address_home,
            cau.gov_national_id_en AS governorate_national_id,
            cau.city_national_id_en AS city_national_id,
            cau.address_national_id,
            cau.gov_work_en AS governorate_work,
            cau.city_work_en AS city_work,
            cau.address_work,
            lc.classification,
                CASE
                    WHEN (c.activation_branch_new IS NULL) THEN c.activation_branch_adjusted
                    ELSE c.activation_branch_new
                END AS activation_branch_adjusted_out,
                CASE
                    WHEN ((c.activation_branch_new = 'digital-onboarding'::text) OR (c.activation_branch_adjusted = 'digital-onboarding'::text)) THEN 'digital-onboarding'::text
                    ELSE c.unified_city
                END AS activation_branch_city,
            ar.terrorist_or_sanction_flag,
            is_.i_score,
            obs.ob_segment,
            (dl.consumer_id IS NOT NULL) AS is_deleted_flag,
            dl.deletion_reason,
            now() AS mv_last_refreshed_time
           FROM ((((((((((consumer_calc_1 c
             LEFT JOIN cons_addr_unified cau ON ((c.consumer_id = cau.consumer_id)))
             LEFT JOIN credit_limit cl ON ((c.consumer_id = cl.consumer_id)))
             LEFT JOIN churn_status_btech csb ON ((c.consumer_id = csb.consumer_id)))
             LEFT JOIN churn_status_non_btech csn ON ((c.consumer_id = csn.consumer_id)))
             LEFT JOIN application_reason ar ON ((c.consumer_id = ar.consumer_id)))
             LEFT JOIN i_score is_ ON (((c.national_id)::text = (is_.national_id)::text)))
             LEFT JOIN collection_db.late_consumer lc ON ((c.consumer_id = lc.consumer_id)))
             LEFT JOIN latest_app_state las ON ((c.consumer_id = las.consumer_id)))
             LEFT JOIN ob_segment obs ON ((c.consumer_id = obs.consumer_id)))
             LEFT JOIN deletion_log dl ON ((c.consumer_id = dl.consumer_id)))
        ), arch_state_calc AS (
         SELECT s.consumer_id,
            max(
                CASE
                    WHEN ((s.rn_first_active = 1) AND ((s.state)::text = 'ACTIVE'::text)) THEN s.active_since
                    ELSE NULL::timestamp with time zone
                END) AS first_active_since,
            max(
                CASE
                    WHEN ((s.rn_last_active = 1) AND ((s.state)::text = 'ACTIVE'::text)) THEN s.active_since
                    ELSE NULL::timestamp with time zone
                END) AS last_active_since,
            max(
                CASE
                    WHEN ((s.rn_first_active = 1) AND ((s.state)::text = 'ACTIVE'::text)) THEN (s.branch)::text
                    ELSE NULL::text
                END) AS first_activation_branch,
            max(
                CASE
                    WHEN ((s.rn_last_active = 1) AND ((s.state)::text = 'ACTIVE'::text)) THEN (s.branch)::text
                    ELSE NULL::text
                END) AS last_activation_branch,
            max(
                CASE
                    WHEN (s.rn_last_overall = 1) THEN (s.state)::text
                    ELSE NULL::text
                END) AS last_state,
            max(
                CASE
                    WHEN (s.rn_last_overall = 1) THEN s.active_since
                    ELSE NULL::timestamp with time zone
                END) AS last_active_since_overall
           FROM ( SELECT consumer_state.consumer_id,
                    consumer_state.state,
                    consumer_state.active_since,
                    consumer_state.branch,
                    row_number() OVER (PARTITION BY consumer_state.consumer_id ORDER BY consumer_state.active_since DESC) AS rn_last_overall,
                    row_number() OVER (PARTITION BY consumer_state.consumer_id ORDER BY
                        CASE
                            WHEN ((consumer_state.state)::text = 'ACTIVE'::text) THEN consumer_state.active_since
                            ELSE NULL::timestamp with time zone
                        END) AS rn_first_active,
                    row_number() OVER (PARTITION BY consumer_state.consumer_id ORDER BY
                        CASE
                            WHEN ((consumer_state.state)::text = 'ACTIVE'::text) THEN consumer_state.active_since
                            ELSE NULL::timestamp with time zone
                        END DESC NULLS LAST) AS rn_last_active
                   FROM archive.consumer_state) s
          GROUP BY s.consumer_id
        ), arch_addr_unified AS (
         SELECT ca.consumer_id,
            max((
                CASE
                    WHEN ((ca.type)::text = 'home'::text) THEN COALESCE(g.name_en, g2.name_en)
                    ELSE NULL::character varying
                END)::text) AS gov_home_en,
            max((
                CASE
                    WHEN ((ca.type)::text = 'national_id'::text) THEN COALESCE(g.name_en, g2.name_en)
                    ELSE NULL::character varying
                END)::text) AS gov_national_id_en,
            max((
                CASE
                    WHEN ((ca.type)::text = 'work'::text) THEN COALESCE(g.name_en, g2.name_en)
                    ELSE NULL::character varying
                END)::text) AS gov_work_en,
            max((
                CASE
                    WHEN ((ca.type)::text = 'home'::text) THEN c.name_en
                    ELSE NULL::character varying
                END)::text) AS city_home_en,
            max((
                CASE
                    WHEN ((ca.type)::text = 'national_id'::text) THEN c.name_en
                    ELSE NULL::character varying
                END)::text) AS city_national_id_en,
            max((
                CASE
                    WHEN ((ca.type)::text = 'work'::text) THEN c.name_en
                    ELSE NULL::character varying
                END)::text) AS city_work_en,
            max((
                CASE
                    WHEN ((ca.type)::text = 'home'::text) THEN ca.address_line_1
                    ELSE NULL::character varying
                END)::text) AS address_home,
            max((
                CASE
                    WHEN ((ca.type)::text = 'national_id'::text) THEN ca.address_line_1
                    ELSE NULL::character varying
                END)::text) AS address_national_id,
            max((
                CASE
                    WHEN ((ca.type)::text = 'work'::text) THEN ca.address_line_1
                    ELSE NULL::character varying
                END)::text) AS address_work
           FROM (((( SELECT DISTINCT ON (consumer_address.consumer_id, consumer_address.type) consumer_address.consumer_id,
                    consumer_address.type,
                    consumer_address.address_line_1,
                    consumer_address.governorate_id,
                    consumer_address.city_id,
                    consumer_address.created_at
                   FROM archive.consumer_address
                  WHERE ((consumer_address.type)::text = ANY (ARRAY['home'::text, 'work'::text, 'national_id'::text]))
                  ORDER BY consumer_address.consumer_id, consumer_address.type, consumer_address.created_at DESC) ca
             LEFT JOIN public.cities c ON ((c.id = ca.city_id)))
             LEFT JOIN public.governorates g ON ((g.id = c.governorate_id)))
             LEFT JOIN public.governorates g2 ON ((g2.id = ca.governorate_id)))
          GROUP BY ca.consumer_id
        ), arch_loc AS (
         SELECT DISTINCT ON (ca.consumer_id) ca.consumer_id,
            COALESCE(ci."governorate name_en", ci2."governorate name_en") AS governorate_loc,
            ci.regions
           FROM ((archive.consumer_address ca
             LEFT JOIN public.cities_adjusted_full ci ON (((ca.governorate_id = ci."governorate id") AND (ca.city_id = ci.id))))
             LEFT JOIN public.cities_adjusted_full ci2 ON (((ca.governorate_id = ci2."governorate id") AND (ca.city_id IS NULL))))
          WHERE ((ca.city_id IS NOT NULL) AND ((ca.type)::text = 'home'::text) AND (ca.is_active = true))
          ORDER BY ca.consumer_id, ca.created_at DESC
        ), arch_phone AS (
         SELECT DISTINCT ON (consumer_phone.consumer_id) consumer_phone.consumer_id,
            consumer_phone.phone_number_e164
           FROM archive.consumer_phone
          WHERE ((consumer_phone.is_primary = true) AND (consumer_phone.is_active = true))
          ORDER BY consumer_phone.consumer_id, consumer_phone.created_at DESC
        ), arch_user AS (
         SELECT DISTINCT ON (consumer_user_details.consumer_id) consumer_user_details.consumer_id,
            consumer_user_details.full_name,
            consumer_user_details.first_name,
            consumer_user_details.last_name,
            consumer_user_details.national_id
           FROM archive.consumer_user_details
          ORDER BY consumer_user_details.consumer_id, consumer_user_details.created_at DESC
        ), arch_newcons AS (
         SELECT DISTINCT ON (new_consumers.id) new_consumers.id AS consumer_id,
            new_consumers.created_at
           FROM archive.new_consumers
          ORDER BY new_consumers.id, new_consumers.created_at DESC
        ), arch_credit AS (
         SELECT ccl.consumer_id,
            (COALESCE(ccl.max_credit_limit, 0) / 100) AS max_credit_limit_egp,
            (COALESCE(ccl.available_credit_limit, 0) / 100) AS available_credit_limit_egp,
            COALESCE(
                CASE
                    WHEN (ccl.max_credit_limit = 0) THEN NULL::numeric
                    WHEN (((((ccl.max_credit_limit - ccl.available_credit_limit))::numeric * 100.0) / (ccl.max_credit_limit)::numeric) < (1)::numeric) THEN ceil(((((ccl.max_credit_limit - ccl.available_credit_limit))::numeric * 100.0) / (ccl.max_credit_limit)::numeric))
                    ELSE round(((((ccl.max_credit_limit - ccl.available_credit_limit))::numeric * 100.0) / (ccl.max_credit_limit)::numeric))
                END, (0)::numeric) AS credit_utilization,
            ccl.active_since AS credit_limit_active_since
           FROM ( SELECT consumer_credit_limits.consumer_id,
                    consumer_credit_limits.max_credit_limit,
                    consumer_credit_limits.available_credit_limit,
                    consumer_credit_limits.active_since,
                    row_number() OVER (PARTITION BY consumer_credit_limits.consumer_id ORDER BY consumer_credit_limits.updated_at DESC, consumer_credit_limits.created_at DESC) AS row_num
                   FROM archive.consumer_credit_limits) ccl
          WHERE (ccl.row_num = 1)
        ), arch_kyc AS (
         SELECT DISTINCT ON (consumer_kyc.consumer_id) consumer_kyc.consumer_id,
            consumer_kyc.national_id,
            consumer_kyc.company_name,
            consumer_kyc.job_title,
            consumer_kyc.job_category,
            consumer_kyc.job_sector,
            consumer_kyc.club,
            consumer_kyc.marital_status,
            consumer_kyc.house_level,
            consumer_kyc.primary_income,
            consumer_kyc.additional_income,
            consumer_kyc.car_year,
            consumer_kyc.single_payment_day,
            consumer_kyc.origination_channel,
            consumer_kyc.scoring_channel,
            consumer_kyc.other_company_name
           FROM archive.consumer_kyc
          ORDER BY consumer_kyc.consumer_id, consumer_kyc.created_at DESC
        ), arch_base AS (
         SELECT ak.consumer_id,
            cs.clientid,
            aph.phone_number_e164 AS phone_number,
            asc1.last_state AS status,
            aud.full_name,
            aud.first_name,
            aud.last_name,
            COALESCE(ak.national_id, aud.national_id) AS national_id,
            public.parse_national_id_dob((COALESCE(ak.national_id, aud.national_id))::text) AS consumer_dob,
            COALESCE((ic.name_en)::text, (ak.job_title)::text) AS job_name,
            COALESCE((ic.name_ar)::text, (ak.job_title)::text) AS job_name_ar,
            COALESCE((ies.name_en)::text, ak.job_category) AS job_category,
            COALESCE((sec.name_en)::text, ak.job_sector) AS job_sector,
            ak.company_name AS company,
            COALESCE(ec.name_en, ak.club) AS club,
            COALESCE(ten.status_name_en, ak.house_level) AS house_type,
            ((ak.primary_income)::numeric / (100)::numeric) AS salary_egp,
            COALESCE(ak.additional_income, 0) AS additional_salary,
            ak.car_year,
            COALESCE(lt.status_name_en, ak.marital_status) AS marital_status,
            (asc1.last_active_since AT TIME ZONE 'Africa/Cairo'::text) AS activated_at,
            (asc1.first_active_since AT TIME ZONE 'Africa/Cairo'::text) AS first_activated_at,
            anc.created_at,
            (asc1.last_active_since_overall AT TIME ZONE 'Africa/Cairo'::text) AS updated_at,
            ak.single_payment_day,
            ak.origination_channel,
            ak.other_company_name AS additional_salary_source,
            ak.scoring_channel,
                CASE
                    WHEN (((cs.registerdate >= anc.created_at) AND (cs.registerdate < (anc.created_at + '1 day'::interval))) OR ((ak.origination_channel)::text = 'mylo'::text)) THEN 'MCN'::text
                    ELSE 'MCR'::text
                END AS new_returning_flag,
            asc1.first_activation_branch AS activation_branch,
            asc1.last_activation_branch AS activation_branch_new,
                CASE
                    WHEN ((asc1.first_activation_branch IS NULL) OR (asc1.first_activation_branch = ''::text)) THEN (cs.branchname)::text
                    WHEN ((anc.created_at >= '2024-01-01 00:00:00'::timestamp without time zone) AND (anc.created_at <= '2024-09-04 00:00:00'::timestamp without time zone)) THEN 'Asyut'::text
                    ELSE asc1.first_activation_branch
                END AS activation_branch_adjusted,
            COALESCE(b1.unified_city, b.unified_city) AS unified_city,
                CASE
                    WHEN (public.parse_national_id_dob((COALESCE(ak.national_id, aud.national_id))::text) IS NULL) THEN 'NOT_VALID'::text
                    WHEN ((length((COALESCE(ak.national_id, aud.national_id))::text) = 14) AND ((SUBSTRING(COALESCE(ak.national_id, aud.national_id) FROM 4 FOR 2))::integer <= 12) AND ((SUBSTRING(COALESCE(ak.national_id, aud.national_id) FROM 6 FOR 2))::integer <= 31)) THEN 'VALID'::text
                    ELSE 'NOT_VALID'::text
                END AS national_id_validity,
                CASE
                    WHEN (public.parse_national_id_dob((COALESCE(ak.national_id, aud.national_id))::text) IS NULL) THEN NULL::text
                    WHEN (((SUBSTRING(COALESCE(ak.national_id, aud.national_id) FROM 13 FOR 1))::integer % 2) = 1) THEN 'MALE'::text
                    ELSE 'FEMALE'::text
                END AS consumer_gender,
            EXTRACT(year FROM age((public.parse_national_id_dob((COALESCE(ak.national_id, aud.national_id))::text))::timestamp with time zone)) AS consumer_age,
            al.governorate_loc,
            al.regions,
            aau.gov_home_en,
            aau.city_home_en,
            aau.address_home,
            aau.gov_national_id_en,
            aau.city_national_id_en,
            aau.address_national_id,
            aau.gov_work_en,
            aau.city_work_en,
            aau.address_work
           FROM (((((((((((((((arch_kyc ak
             LEFT JOIN arch_state_calc asc1 ON ((asc1.consumer_id = ak.consumer_id)))
             LEFT JOIN arch_newcons anc ON ((anc.consumer_id = ak.consumer_id)))
             LEFT JOIN arch_phone aph ON ((aph.consumer_id = ak.consumer_id)))
             LEFT JOIN arch_user aud ON ((aud.consumer_id = ak.consumer_id)))
             LEFT JOIN arch_addr_unified aau ON ((aau.consumer_id = ak.consumer_id)))
             LEFT JOIN arch_loc al ON ((al.consumer_id = ak.consumer_id)))
             LEFT JOIN lookup_tables.int_marital_status lt ON (((ak.marital_status)::text = (lt.id)::text)))
             LEFT JOIN lookup_tables.eg_clubs ec ON (((ak.club)::text = (ec.id)::text)))
             LEFT JOIN lookup_tables.int_occupation ic ON (((ak.job_title)::text = (ic.code)::text)))
             LEFT JOIN lookup_tables.int_employment_status ies ON ((ak.job_category = (ies.code)::text)))
             LEFT JOIN lookup_tables.int_employment_sector sec ON ((ak.job_sector = (sec.id)::text)))
             LEFT JOIN lookup_tables.int_housing_tenures ten ON (((ak.house_level)::text = (ten.id)::text)))
             LEFT JOIN clients cs ON ((TRIM(BOTH FROM COALESCE(ak.national_id, aud.national_id)) = TRIM(BOTH FROM cs.ssn))))
             LEFT JOIN public.branches b ON ((asc1.first_activation_branch = b.activation_branch_adjusted)))
             LEFT JOIN public.branches b1 ON ((asc1.last_activation_branch = b1.activation_branch_adjusted)))
        )
