 SELECT nc.id AS consumer_id,
    NULL::integer AS clientid,
    (ca.data ->> 'phone_number'::text) AS phone_number,
    ((ca.data -> 'consumer_kyc'::text) ->> 'ssn'::text) AS national_id,
        CASE
            WHEN ((length(((ca.data -> 'consumer_kyc'::text) ->> 'ssn'::text)) = 14) AND ((SUBSTRING(((ca.data -> 'consumer_kyc'::text) ->> 'ssn'::text) FROM 4 FOR 2))::integer <= 12) AND ((SUBSTRING(((ca.data -> 'consumer_kyc'::text) ->> 'ssn'::text) FROM 6 FOR 2))::integer <= 31)) THEN 'VALID'::text
            ELSE 'NOT_VALID'::text
        END AS national_id_validity,
    'PENDING_APPROVAL_ONBOARDING'::text AS status,
    ((ca.data -> 'consumer_kyc'::text) ->> 'full_name'::text) AS full_name,
    ((ca.data -> 'consumer_kyc'::text) ->> 'first_name'::text) AS first_name,
    ((ca.data -> 'consumer_kyc'::text) ->> 'last_name'::text) AS last_name,
    NULL::date AS consumer_dob,
    NULL::text AS consumer_gender,
    NULL::text AS marital_status,
    NULL::numeric AS consumer_age,
    NULL::text AS consumer_age_range,
    NULL::text AS job_sector,
    NULL::text AS job_category,
    NULL::text AS job_name,
    NULL::text AS job_name_ar,
    ((ca.data -> 'consumer_kyc'::text) ->> 'company_name'::text) AS company,
    NULL::text AS club,
    NULL::integer AS car_year,
    NULL::text AS house_type,
    NULL::text AS region,
    g.name_en AS governorate_home,
    NULL::text AS city_home,
    NULL::text AS address_home,
    NULL::text AS governorate_national_id,
    NULL::text AS city_national_id,
    NULL::text AS address_national_id,
    NULL::text AS governorate_work,
    NULL::text AS city_work,
    NULL::text AS address_work,
    ((((ca.data -> 'consumer_kyc'::text) ->> 'net_income'::text))::numeric / (100)::numeric) AS salary_egp,
    COALESCE((((ca.data -> 'consumer_kyc'::text) ->> 'additional_income'::text))::numeric, (0)::numeric) AS additional_salary,
    NULL::text AS additional_salary_source,
    NULL::numeric AS max_credit_limit_egp,
    NULL::numeric AS available_credit_limit_egp,
    NULL::text AS income_bucket,
    NULL::text AS credit_limit_bucket,
    NULL::numeric AS credit_utilization,
    NULL::text AS utilization_bucket,
    NULL::timestamp with time zone AS credit_limit_active_since,
    'Non_Transacted'::text AS churn_status_btech,
    'Non_Transacted'::text AS churn_status_non_btech,
    NULL::timestamp without time zone AS first_activated_at,
    NULL::timestamp without time zone AS activated_at,
    nc.created_at,
    nc.created_at AS updated_at,
    (((ca.data -> 'consumer_kyc'::text) ->> 'single_payment_day'::text))::integer AS single_payment_day,
    ((ca.data -> 'consumer_kyc'::text) ->> 'origination_channel'::text) AS origination_channel,
    ((ca.data -> 'consumer_kyc'::text) ->> 'scoring_channel'::text) AS scoring_channel,
    NULL::text AS new_returning_flag,
    NULL::text AS comment,
    NULL::text AS classification,
    NULL::text AS activation_branch_adjusted,
    NULL::text AS activation_branch_city,
    false AS terrorist_or_sanction_flag,
    NULL::integer AS i_score,
    NULL::text AS ob_segment,
    false AS is_deleted_flag,
    NULL::text AS deletion_reason,
    now() AS mv_last_refreshed_time
   FROM (((public.new_consumers nc
     JOIN public.consumer_application ca ON ((ca.consumer_id = nc.id)))
     JOIN ( SELECT DISTINCT ON (consumer_application_state.consumer_application_id) consumer_application_state.consumer_application_id,
            consumer_application_state.state
           FROM public.consumer_application_state
          ORDER BY consumer_application_state.consumer_application_id, consumer_application_state.created_at DESC) las ON ((las.consumer_application_id = ca.id)))
     LEFT JOIN public.governorates g ON ((g.id = (((ca.data -> 'consumer_kyc'::text) ->> 'address_governorate_id'::text))::integer)))
  WHERE (((ca.data ->> 'step'::text) = 'RISK_ENGINE_VALIDATION'::text) AND ((las.state)::text = 'PENDING_ACTIVATION_APPROVAL'::text) AND (NOT (EXISTS ( SELECT 1
           FROM public.consumer_kyc ck
          WHERE (ck.consumer_id = nc.id)))))
UNION ALL
 SELECT ab.consumer_id,
    ab.clientid,
    ab.phone_number,
    ab.national_id,
    ab.national_id_validity,
    ab.status,
    ab.full_name,
    ab.first_name,
    ab.last_name,
    ab.consumer_dob,
    ab.consumer_gender,
    ab.marital_status,
    ab.consumer_age,
        CASE
            WHEN (ab.consumer_age IS NULL) THEN NULL::text
            WHEN (ab.consumer_age < (18)::numeric) THEN '0-18 yrs'::text
            WHEN ((ab.consumer_age >= (18)::numeric) AND (ab.consumer_age <= (24)::numeric)) THEN '18-24 yrs'::text
            WHEN ((ab.consumer_age >= (25)::numeric) AND (ab.consumer_age <= (34)::numeric)) THEN '25-34 yrs'::text
            WHEN ((ab.consumer_age >= (35)::numeric) AND (ab.consumer_age <= (44)::numeric)) THEN '35-44 yrs'::text
            WHEN ((ab.consumer_age >= (45)::numeric) AND (ab.consumer_age <= (54)::numeric)) THEN '45-54 yrs'::text
            WHEN ((ab.consumer_age >= (55)::numeric) AND (ab.consumer_age <= (64)::numeric)) THEN '55-64 yrs'::text
            WHEN ((ab.consumer_age >= (65)::numeric) AND (ab.consumer_age <= (74)::numeric)) THEN '65-74 yrs'::text
            WHEN ((ab.consumer_age >= (75)::numeric) AND (ab.consumer_age <= (84)::numeric)) THEN '75-84 yrs'::text
            ELSE '85+ yrs'::text
        END AS consumer_age_range,
    ab.job_sector,
    ab.job_category,
    ab.job_name,
    ab.job_name_ar,
    ab.company,
    ab.club,
    ab.car_year,
    ab.house_type,
    ab.regions AS region,
    COALESCE(ab.gov_home_en, (ab.governorate_loc)::text, 'Unknown Governorate'::text) AS governorate_home,
    ab.city_home_en AS city_home,
    ab.address_home,
    ab.gov_national_id_en AS governorate_national_id,
    ab.city_national_id_en AS city_national_id,
    ab.address_national_id,
    ab.gov_work_en AS governorate_work,
    ab.city_work_en AS city_work,
    ab.address_work,
    ab.salary_egp,
    ab.additional_salary,
    ab.additional_salary_source,
    acr.max_credit_limit_egp,
    acr.available_credit_limit_egp,
        CASE
            WHEN ((ab.salary_egp + (ab.additional_salary)::numeric) = (0)::numeric) THEN '=0'::text
            WHEN (((ab.salary_egp + (ab.additional_salary)::numeric) >= (1)::numeric) AND ((ab.salary_egp + (ab.additional_salary)::numeric) <= (10000)::numeric)) THEN '0-10K'::text
            WHEN (((ab.salary_egp + (ab.additional_salary)::numeric) >= (10001)::numeric) AND ((ab.salary_egp + (ab.additional_salary)::numeric) <= (20000)::numeric)) THEN '10-20K'::text
            WHEN (((ab.salary_egp + (ab.additional_salary)::numeric) >= (20001)::numeric) AND ((ab.salary_egp + (ab.additional_salary)::numeric) <= (30000)::numeric)) THEN '20-30K'::text
            WHEN (((ab.salary_egp + (ab.additional_salary)::numeric) >= (30001)::numeric) AND ((ab.salary_egp + (ab.additional_salary)::numeric) <= (40000)::numeric)) THEN '30-40K'::text
            WHEN (((ab.salary_egp + (ab.additional_salary)::numeric) >= (40001)::numeric) AND ((ab.salary_egp + (ab.additional_salary)::numeric) <= (50000)::numeric)) THEN '40-50K'::text
            WHEN (((ab.salary_egp + (ab.additional_salary)::numeric) >= (50001)::numeric) AND ((ab.salary_egp + (ab.additional_salary)::numeric) <= (60000)::numeric)) THEN '50-60K'::text
            WHEN (((ab.salary_egp + (ab.additional_salary)::numeric) >= (60001)::numeric) AND ((ab.salary_egp + (ab.additional_salary)::numeric) <= (70000)::numeric)) THEN '60-70K'::text
            WHEN (((ab.salary_egp + (ab.additional_salary)::numeric) >= (70001)::numeric) AND ((ab.salary_egp + (ab.additional_salary)::numeric) <= (80000)::numeric)) THEN '70-80K'::text
            WHEN (((ab.salary_egp + (ab.additional_salary)::numeric) >= (80001)::numeric) AND ((ab.salary_egp + (ab.additional_salary)::numeric) <= (90000)::numeric)) THEN '80-90K'::text
            WHEN (((ab.salary_egp + (ab.additional_salary)::numeric) >= (90001)::numeric) AND ((ab.salary_egp + (ab.additional_salary)::numeric) <= (100000)::numeric)) THEN '90-100K'::text
            WHEN ((ab.salary_egp + (ab.additional_salary)::numeric) > (100000)::numeric) THEN '>100K'::text
            ELSE ((ab.salary_egp + (ab.additional_salary)::numeric))::text
        END AS income_bucket,
        CASE
            WHEN (acr.max_credit_limit_egp <= 0) THEN '=0'::text
            WHEN ((acr.max_credit_limit_egp >= 1) AND (acr.max_credit_limit_egp <= 20000)) THEN '0-20K'::text
            WHEN ((acr.max_credit_limit_egp >= 20001) AND (acr.max_credit_limit_egp <= 40000)) THEN '20-40K'::text
            WHEN ((acr.max_credit_limit_egp >= 40001) AND (acr.max_credit_limit_egp <= 60000)) THEN '40-60K'::text
            WHEN ((acr.max_credit_limit_egp >= 60001) AND (acr.max_credit_limit_egp <= 80000)) THEN '60-80K'::text
            WHEN ((acr.max_credit_limit_egp >= 80001) AND (acr.max_credit_limit_egp <= 100000)) THEN '80-100K'::text
            WHEN ((acr.max_credit_limit_egp >= 100001) AND (acr.max_credit_limit_egp <= 200000)) THEN '100-200K'::text
            WHEN ((acr.max_credit_limit_egp >= 200001) AND (acr.max_credit_limit_egp <= 300000)) THEN '200-300K'::text
            WHEN (acr.max_credit_limit_egp > 300000) THEN '>300K'::text
            ELSE '>=100K'::text
        END AS credit_limit_bucket,
    acr.credit_utilization,
        CASE
            WHEN (acr.credit_utilization = (0)::numeric) THEN '=0%'::text
            WHEN ((acr.credit_utilization >= (1)::numeric) AND (acr.credit_utilization <= (20)::numeric)) THEN '0%-20%'::text
            WHEN ((acr.credit_utilization >= (21)::numeric) AND (acr.credit_utilization <= (40)::numeric)) THEN '20%-40%'::text
            WHEN ((acr.credit_utilization >= (41)::numeric) AND (acr.credit_utilization <= (60)::numeric)) THEN '40%-60%'::text
            WHEN ((acr.credit_utilization >= (61)::numeric) AND (acr.credit_utilization <= (80)::numeric)) THEN '60%-80%'::text
            WHEN ((acr.credit_utilization >= (81)::numeric) AND (acr.credit_utilization <= (100)::numeric)) THEN '80%-100%'::text
            ELSE '=0%'::text
        END AS utilization_bucket,
    acr.credit_limit_active_since,
        CASE
            WHEN (csb.finisher_btech = 1) THEN 'Finisher'::text
            WHEN (csb.pre_finsher_btech = 1) THEN 'Pre_Finisher'::text
            WHEN (csb.running_btech = 1) THEN 'Running'::text
            ELSE 'Non_Transacted'::text
        END AS churn_status_btech,
        CASE
            WHEN (csn.finisher_non_btech = 1) THEN 'Finisher'::text
            WHEN (csn.pre_finsher_non_btech = 1) THEN 'Pre_Finisher'::text
            WHEN (csn.running_non_btech = 1) THEN 'Running'::text
            ELSE 'Non_Transacted'::text
        END AS churn_status_non_btech,
    ab.first_activated_at,
    ab.activated_at,
    ab.created_at,
    ab.updated_at,
    ab.single_payment_day,
    ab.origination_channel,
    ab.scoring_channel,
    ab.new_returning_flag,
    NULL::text AS comment,
    lc.classification,
        CASE
            WHEN (ab.activation_branch_new IS NULL) THEN ab.activation_branch_adjusted
            ELSE ab.activation_branch_new
        END AS activation_branch_adjusted,
        CASE
            WHEN ((ab.activation_branch_new = 'digital-onboarding'::text) OR (ab.activation_branch_adjusted = 'digital-onboarding'::text)) THEN 'digital-onboarding'::text
            ELSE ab.unified_city
        END AS activation_branch_city,
    false AS terrorist_or_sanction_flag,
    isr.i_score,
    NULL::text AS ob_segment,
    true AS is_deleted_flag,
    dl.deletion_reason,
    now() AS mv_last_refreshed_time
   FROM ((((((arch_base ab
     LEFT JOIN arch_credit acr ON ((ab.consumer_id = acr.consumer_id)))
     LEFT JOIN churn_status_btech csb ON ((ab.consumer_id = csb.consumer_id)))
     LEFT JOIN churn_status_non_btech csn ON ((ab.consumer_id = csn.consumer_id)))
     LEFT JOIN i_score isr ON (((ab.national_id)::text = (isr.national_id)::text)))
     LEFT JOIN collection_db.late_consumer lc ON ((ab.consumer_id = lc.consumer_id)))
     LEFT JOIN deletion_log dl ON ((ab.consumer_id = dl.consumer_id)))
UNION ALL
 SELECT anc.id AS consumer_id,
    NULL::integer AS clientid,
    (aca.data ->> 'phone_number'::text) AS phone_number,
    ((aca.data -> 'consumer_kyc'::text) ->> 'ssn'::text) AS national_id,
