    ((((aca.data -> 'consumer_kyc'::text) ->> 'net_income'::text))::numeric / (100)::numeric) AS salary_egp,
    COALESCE((((aca.data -> 'consumer_kyc'::text) ->> 'additional_income'::text))::numeric, (0)::numeric) AS additional_salary,
