    NULL::timestamp without time zone AS first_activated_at,
    NULL::timestamp without time zone AS activated_at,
    anc.created_at,
    anc.created_at AS updated_at,
    (((aca.data -> 'consumer_kyc'::text) ->> 'single_payment_day'::text))::integer AS single_payment_day,
    ((aca.data -> 'consumer_kyc'::text) ->> 'origination_channel'::text) AS origination_channel,
    ((aca.data -> 'consumer_kyc'::text) ->> 'scoring_channel'::text) AS scoring_channel,
