   FROM (((archive.new_consumers anc
     JOIN archive.consumer_application aca ON ((aca.consumer_id = anc.id)))
     LEFT JOIN deletion_log dl ON ((dl.consumer_id = anc.id)))
     LEFT JOIN public.governorates g ON ((g.id = (((aca.data -> 'consumer_kyc'::text) ->> 'address_governorate_id'::text))::integer)))
  WHERE (NOT (EXISTS ( SELECT 1
           FROM archive.consumer_kyc ck
          WHERE (ck.consumer_id = anc.id))));


--
