    national_id character varying(8000) NOT NULL,
    social_insurance_data jsonb,
    created_at timestamp(6) with time zone
);


--
-- Name: v_credit_loans; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_credit_loans AS
 WITH params AS (
         SELECT CURRENT_DATE AS as_of_date
        ), social_insurance_latest AS (
         SELECT DISTINCT ON (si.national_id) si.national_id,
            NULLIF(btrim(((si.social_insurance_data -> 'data'::text) ->> 'organizationBuildingName'::text)), ''::text) AS organization_building_name,
            NULLIF(btrim(((si.social_insurance_data -> 'data'::text) ->> 'insuranceFlag_ar'::text)), ''::text) AS insurance_flag_ar
           FROM midas.consumer_social_insurance_data si
          WHERE (si.national_id IS NOT NULL)
          ORDER BY si.national_id, si.created_at DESC NULLS LAST, si.id DESC
        ), selected_loans AS (
         SELECT c_1.consumer_id AS selected_consumer_id,
            latest_loan.loan_id,
            latest_loan.transaction_id,
            latest_loan.consumer_id AS loan_consumer_id,
            latest_loan.merchant_id,
            latest_loan.merchant_name,
            latest_loan.retail_category,
            latest_loan.checkout_channel,
            latest_loan.merchant_created_at_utc,
            latest_loan.transacted_merchant_brand_id,
            latest_loan.transacted_merchant_branch_id,
            latest_loan.merchant_city_id,
            latest_loan.merchant_city,
            latest_loan.transacted_merchant_branch_governorate,
            latest_loan.merchant_city_adjusted,
            latest_loan.merchant_region,
            latest_loan.merchant_type,
            latest_loan.loan_booked_at,
            latest_loan.loan_booked_date,
            latest_loan.loan_current_status,
            latest_loan.is_postponed,
            latest_loan.is_rescheduled,
            latest_loan.loan_batch_status,
            latest_loan.loan_cancelled_at,
            latest_loan.loan_early_settled_at,
            latest_loan.parent_loan_account_id,
            latest_loan.next_due_date,
            latest_loan.last_paid_date,
            latest_loan.basket_value,
            latest_loan.total_principal_amount,
            latest_loan.loan_installment_amount,
            latest_loan.down_payment_amount,
            latest_loan.loan_admin_fee_amount,
            latest_loan.vat_amount,
            latest_loan.total_interest_amount,
            latest_loan.total_late_fee,
            latest_loan.total_paid_late_fee,
            latest_loan.total_due_amount,
            latest_loan.total_paid_amount,
            latest_loan.total_principal_paid_amount,
            latest_loan.total_interest_paid_amount,
            latest_loan.total_remaining_amount_with_interest,
            latest_loan.total_remaining_amount_without_interest,
            latest_loan.potential_interest_loss_if_early_settlement,
            latest_loan.num_of_paid_installments,
            latest_loan.num_of_remaining_installments,
            latest_loan.tenor,
            latest_loan.new_tenor,
            latest_loan.tenor_days,
            latest_loan.grace_period_in_days,
            latest_loan.borrower_repayment_day_of_month,
            latest_loan.financial_product_id,
            latest_loan.financial_product_id_cb,
            latest_loan.linked_fp_key,
            latest_loan.linked_fp_version,
            latest_loan.tenor_interest_percent,
            latest_loan.annual_interest_percent,
            latest_loan.is_profit_bearing,
            latest_loan.consumer_loan_sequence_number,
            latest_loan.merchant_loan_sequence_number,
            latest_loan.view_last_refreshed_time
           FROM (public.mv_consumers_info c_1
             LEFT JOIN LATERAL ( SELECT l.loan_id,
                    l.transaction_id,
                    l.consumer_id,
                    l.loan_booked_at,
                    l.loan_booked_date,
                    l.loan_current_status,
                    l.is_postponed,
                    l.is_rescheduled,
                    l.loan_batch_status,
                    l.loan_cancelled_at,
                    l.loan_early_settled_at,
                    l.parent_loan_account_id,
                    l.basket_value,
                    l.total_principal_amount,
                    l.loan_installment_amount,
                    l.down_payment_amount,
                    l.loan_admin_fee_amount,
                    l.vat_amount,
                    l.total_interest_amount,
                    l.total_late_fee,
                    l.total_paid_late_fee,
                    l.total_due_amount,
                    l.total_paid_amount,
                    l.total_principal_paid_amount,
                    l.total_interest_paid_amount,
                    l.num_of_paid_installments,
                    l.num_of_remaining_installments,
                    l.total_remaining_amount_with_interest,
                    l.total_remaining_amount_without_interest,
                    l.potential_interest_loss_if_early_settlement,
                    l.financial_product_id,
                    l.financial_product_id_cb,
                    l.linked_fp_key,
                    l.linked_fp_version,
                    l.tenor,
                    l.new_tenor,
                    l.tenor_interest_percent,
                    l.annual_interest_percent,
                    l.is_profit_bearing,
                    l.retail_category,
                    l.checkout_channel,
                    l.merchant_id,
                    l.merchant_name,
                    l.merchant_created_at_utc,
                    l.transacted_merchant_brand_id,
                    l.transacted_merchant_branch_id,
                    l.merchant_city_id,
                    l.merchant_city,
                    l.transacted_merchant_branch_governorate,
                    l.merchant_city_adjusted,
                    l.merchant_region,
                    l.merchant_type,
                    l.consumer_loan_sequence_number,
                    l.merchant_loan_sequence_number,
                    l.tenor_days,
                    l.grace_period_in_days,
                    l.borrower_repayment_day_of_month,
                    l.view_last_refreshed_time,
                    l.next_due_date,
                    l.last_paid_date
                   FROM public.mv_loans_info l
                  WHERE ((l.consumer_id)::text = (c_1.consumer_id)::text)
                  ORDER BY l.loan_booked_at DESC NULLS LAST, l.loan_id DESC
                 LIMIT 1) latest_loan ON (true))
        ), schedule_metrics AS (
         SELECT s.loan_id,
            sum(
                CASE
                    WHEN (s.due_date <= p.as_of_date) THEN ((COALESCE(s.due_principal, (0)::numeric) + COALESCE(s.due_interest, (0)::numeric)) -
                    CASE
                        WHEN (s.paid_date <= p.as_of_date) THEN (COALESCE(s.paid_principal, (0)::numeric) + COALESCE(s.paid_interest, (0)::numeric))
                        ELSE (0)::numeric
                    END)
                    ELSE (0)::numeric
                END) AS total_unpaid_installments,
            sum(
                CASE
                    WHEN ((s.due_date <= p.as_of_date) AND (date_trunc('month'::text, (s.due_date)::timestamp with time zone) = date_trunc('month'::text, (p.as_of_date)::timestamp with time zone))) THEN (COALESCE(s.due_principal, (0)::numeric) + COALESCE(s.due_interest, (0)::numeric))
                    ELSE (0)::numeric
                END) AS due_30_day,
            sum(
                CASE
                    WHEN ((s.due_date <= p.as_of_date) AND (date_trunc('month'::text, (s.due_date)::timestamp with time zone) = date_trunc('month'::text, (p.as_of_date)::timestamp with time zone)) AND (s.paid_date <= p.as_of_date)) THEN (COALESCE(s.paid_principal, (0)::numeric) + COALESCE(s.paid_interest, (0)::numeric))
                    ELSE (0)::numeric
                END) AS paid_30_day,
            sum(
                CASE
                    WHEN ((s.due_date <= p.as_of_date) AND (date_trunc('month'::text, (s.due_date)::timestamp with time zone) = (date_trunc('month'::text, (p.as_of_date)::timestamp with time zone) - '1 mon'::interval))) THEN (COALESCE(s.due_principal, (0)::numeric) + COALESCE(s.due_interest, (0)::numeric))
                    ELSE (0)::numeric
                END) AS due_60_day,
            sum(
                CASE
                    WHEN ((s.due_date <= p.as_of_date) AND (date_trunc('month'::text, (s.due_date)::timestamp with time zone) = (date_trunc('month'::text, (p.as_of_date)::timestamp with time zone) - '1 mon'::interval)) AND (s.paid_date <= p.as_of_date)) THEN (COALESCE(s.paid_principal, (0)::numeric) + COALESCE(s.paid_interest, (0)::numeric))
                    ELSE (0)::numeric
                END) AS paid_60_day,
            sum(
                CASE
                    WHEN ((s.due_date <= p.as_of_date) AND (date_trunc('month'::text, (s.due_date)::timestamp with time zone) = (date_trunc('month'::text, (p.as_of_date)::timestamp with time zone) - '2 mons'::interval))) THEN (COALESCE(s.due_principal, (0)::numeric) + COALESCE(s.due_interest, (0)::numeric))
                    ELSE (0)::numeric
                END) AS due_90_day,
            sum(
                CASE
                    WHEN ((s.due_date <= p.as_of_date) AND (date_trunc('month'::text, (s.due_date)::timestamp with time zone) = (date_trunc('month'::text, (p.as_of_date)::timestamp with time zone) - '2 mons'::interval)) AND (s.paid_date <= p.as_of_date)) THEN (COALESCE(s.paid_principal, (0)::numeric) + COALESCE(s.paid_interest, (0)::numeric))
                    ELSE (0)::numeric
                END) AS paid_90_day
           FROM ((selected_loans sl_1
             JOIN public.mv_loans_sch_info s ON (((s.loan_id)::text = (sl_1.loan_id)::text)))
             CROSS JOIN params p)
          WHERE (sl_1.loan_id IS NOT NULL)
          GROUP BY s.loan_id
        )
 SELECT c.consumer_id,
    sl.loan_id,
    c.clientid,
    c.national_id,
    c.phone_number,
    c.full_name,
    c.status AS consumer_status,
    c.job_category,
    c.income_bucket,
    c.i_score,
    sil.organization_building_name,
    sil.insurance_flag_ar,
    c.available_credit_limit_egp,
    c.max_credit_limit_egp AS credit_limit_egp,
    c.credit_limit_bucket,
    c.credit_utilization,
    c.utilization_bucket,
    c.scoring_channel,
    c.origination_channel,
    c.credit_limit_active_since,
    c.churn_status_btech,
    c.churn_status_non_btech,
    c.first_activated_at,
    c.activated_at,
    c.created_at AS consumer_created_at,
    c.updated_at AS consumer_updated_at,
    c.single_payment_day,
    c.new_returning_flag,
    c.classification,
    c.activation_branch_adjusted,
    c.activation_branch_city,
    c.terrorist_or_sanction_flag,
    c.ob_segment,
    c.is_deleted_flag,
    c.mv_last_refreshed_time AS consumer_last_refreshed_time,
    sl.transaction_id,
    sl.loan_consumer_id,
    sl.merchant_id,
    sl.merchant_name,
    sl.retail_category,
    sl.checkout_channel,
    sl.merchant_created_at_utc,
    sl.transacted_merchant_brand_id,
    sl.transacted_merchant_branch_id,
    sl.merchant_city_id,
    sl.merchant_city,
    sl.transacted_merchant_branch_governorate,
    sl.merchant_city_adjusted,
    sl.merchant_region,
    sl.merchant_type,
    sl.loan_booked_at,
    sl.loan_booked_date,
    sl.loan_current_status,
    sl.is_postponed,
    sl.is_rescheduled,
    sl.loan_batch_status,
    sl.loan_cancelled_at,
    sl.loan_early_settled_at,
    sl.parent_loan_account_id,
    sl.next_due_date,
    sl.last_paid_date,
    sl.basket_value,
    sl.total_principal_amount,
    sl.loan_installment_amount,
    sl.down_payment_amount,
    sl.loan_admin_fee_amount,
    sl.vat_amount,
    sl.total_interest_amount,
    sl.total_late_fee,
    sl.total_paid_late_fee,
    sl.total_due_amount,
    sl.total_paid_amount,
    sl.total_principal_paid_amount,
    sl.total_interest_paid_amount,
    sl.total_remaining_amount_with_interest,
    sl.total_remaining_amount_without_interest,
    sl.potential_interest_loss_if_early_settlement,
    sl.num_of_paid_installments,
    sl.num_of_remaining_installments,
    sl.tenor,
    sl.new_tenor,
    sl.tenor_days,
    sl.grace_period_in_days,
    sl.borrower_repayment_day_of_month,
    sl.financial_product_id,
    sl.financial_product_id_cb,
    sl.linked_fp_key,
    sl.linked_fp_version,
    sl.tenor_interest_percent,
    sl.annual_interest_percent,
    sl.is_profit_bearing,
    sl.consumer_loan_sequence_number,
    sl.merchant_loan_sequence_number,
    sl.view_last_refreshed_time AS loan_last_refreshed_time,
    COALESCE(sm.total_unpaid_installments, (0)::numeric) AS total_unpaid_installments,
    COALESCE(sm.due_30_day, (0)::numeric) AS due_30_day,
    COALESCE(sm.paid_30_day, (0)::numeric) AS paid_30_day,
        CASE
            WHEN (COALESCE(sm.due_30_day, (0)::numeric) > (0)::numeric) THEN round((sm.paid_30_day / NULLIF(sm.due_30_day, (0)::numeric)), 2)
            ELSE (0)::numeric
        END AS pct_30_day,
    COALESCE(sm.due_60_day, (0)::numeric) AS due_60_day,
    COALESCE(sm.paid_60_day, (0)::numeric) AS paid_60_day,
        CASE
            WHEN (COALESCE(sm.due_60_day, (0)::numeric) > (0)::numeric) THEN round((sm.paid_60_day / NULLIF(sm.due_60_day, (0)::numeric)), 2)
            ELSE (0)::numeric
        END AS pct_60_day,
    COALESCE(sm.due_90_day, (0)::numeric) AS due_90_day,
    COALESCE(sm.paid_90_day, (0)::numeric) AS paid_90_day,
        CASE
            WHEN (COALESCE(sm.due_90_day, (0)::numeric) > (0)::numeric) THEN round((sm.paid_90_day / NULLIF(sm.due_90_day, (0)::numeric)), 2)
            ELSE (0)::numeric
        END AS pct_90_day,
    (sl.loan_id IS NOT NULL) AS has_loan
   FROM (((public.mv_consumers_info c
     LEFT JOIN social_insurance_latest sil ON (((sil.national_id)::text = (c.national_id)::text)))
     LEFT JOIN selected_loans sl ON ((sl.selected_consumer_id = c.consumer_id)))
     LEFT JOIN schedule_metrics sm ON (((sm.loan_id)::text = (sl.loan_id)::text)));


