--
-- Name: v_credit_pending_approval; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_credit_pending_approval AS
 WITH consumer_base_info AS (
         SELECT c.consumer_id,
            c.job_name_ar AS job_name,
            c.scoring_channel,
            c.salary_egp AS salary,
            c.additional_salary,
            c.national_id,
            c.phone_number,
            c.status,
            c.full_name,
            c.company,
            c.club,
            c.max_credit_limit_egp AS credit_limit,
            c.i_score,
            c.governorate_home AS governorate,
            c.car_year,
            c.address_home AS address,
            c.created_at,
            c.updated_at,
            c.consumer_age AS age,
            c.first_activated_at,
            c.activation_branch_adjusted AS activation_branch,
            (COALESCE(c.salary_egp, (0)::numeric) + COALESCE(c.additional_salary, (0)::numeric)) AS total_salary
           FROM public.mv_consumers_info c
          WHERE ((c.scoring_channel)::text = 'mylo'::text)
        ), idback_job AS (
         SELECT ca.consumer_id,
            (((ca.data -> 'digital_onboarding_data'::text) -> 'idBackData'::text) ->> 'job'::text) AS id_back_job
           FROM (public.consumer_application ca
             JOIN consumer_base_info cb_1 ON (((cb_1.consumer_id)::text = (ca.consumer_id)::text)))
        ), application_flow AS (
         SELECT ca.consumer_id,
            cas.state AS current_state,
            cas.reason AS current_reason,
            cas.comment AS current_comment,
            cas.active_since AS current_active_since,
            lead(cas.state, 1) OVER (PARTITION BY ca.consumer_id ORDER BY cas.active_since) AS next_state,
            lead(cas.reason, 1) OVER (PARTITION BY ca.consumer_id ORDER BY cas.active_since) AS next_reason,
            lead(cas.comment, 1) OVER (PARTITION BY ca.consumer_id ORDER BY cas.active_since) AS next_comment,
            lead(cas.active_since, 1) OVER (PARTITION BY ca.consumer_id ORDER BY cas.active_since) AS next_active_since,
            lead(COALESCE(ll.value, l.value), 1) OVER (PARTITION BY ca.consumer_id ORDER BY cas.active_since) AS next_value_since,
            lead(cas.state, 2) OVER (PARTITION BY ca.consumer_id ORDER BY cas.active_since) AS next_next_state,
            lead(cas.reason, 2) OVER (PARTITION BY ca.consumer_id ORDER BY cas.active_since) AS next_next_reason,
            lead(cas.comment, 2) OVER (PARTITION BY ca.consumer_id ORDER BY cas.active_since) AS next_next_comment,
            COALESCE(ll.value, l.value) AS value
           FROM ((((public.consumer_application_state cas
             JOIN public.consumer_application ca ON (((cas.consumer_application_id)::text = (ca.id)::text)))
             JOIN consumer_base_info cb_1 ON (((cb_1.consumer_id)::text = (ca.consumer_id)::text)))
             LEFT JOIN public.identity_verifiable_addresses ll ON (((ll.identity_id)::text = (cas.created_by)::text)))
             LEFT JOIN kratos_internal.identity_verifiable_addresses l ON (((l.identity_id)::text = (cas.created_by)::text)))
        ), pending_flow AS (
         SELECT af.consumer_id,
            af.current_state,
            af.current_reason,
            af.current_comment,
            af.current_active_since,
            af.next_state,
            af.next_reason,
            af.next_comment,
            af.next_active_since,
            af.next_value_since,
            af.next_next_state,
            af.next_next_reason,
            af.next_next_comment,
            af.value
           FROM application_flow af
          WHERE ((af.current_state)::text = ANY (ARRAY[('PENDING_ACTIVATION_APPROVAL'::character varying)::text, ('PENDING_ONBOARDING_APPROVAL'::character varying)::text]))
        ), pending_consumers AS (
         SELECT DISTINCT pf_1.consumer_id
           FROM pending_flow pf_1
          WHERE (pf_1.consumer_id IS NOT NULL)
        ), pending_national_ids AS (
         SELECT DISTINCT cb_1.national_id
           FROM (pending_consumers pc
             JOIN consumer_base_info cb_1 ON (((cb_1.consumer_id)::text = (pc.consumer_id)::text)))
          WHERE (cb_1.national_id IS NOT NULL)
        ), loan_schedule_base AS (
         SELECT c.national_id,
            sch.loan_id,
            sch.due_date,
            (COALESCE(sch.due_principal, (0)::numeric) + COALESCE(sch.due_interest, (0)::numeric)) AS due_amount,
                CASE
                    WHEN (sch.paid_date <= CURRENT_DATE) THEN (COALESCE(sch.paid_principal, (0)::numeric) + COALESCE(sch.paid_interest, (0)::numeric))
                    ELSE (0)::numeric
                END AS paid_amount_as_of,
            ((((EXTRACT(year FROM CURRENT_DATE))::integer * 12) + (EXTRACT(month FROM CURRENT_DATE))::integer) - (((EXTRACT(year FROM sch.due_date))::integer * 12) + (EXTRACT(month FROM sch.due_date))::integer)) AS months_past_due
           FROM (((public.mv_loans_sch_info sch
             JOIN public.mv_loans_info li ON (((li.loan_id)::text = (sch.loan_id)::text)))
             JOIN public.mv_consumers_info c ON ((c.consumer_id = (li.consumer_id)::uuid)))
             JOIN pending_national_ids pn ON (((pn.national_id)::text = (c.national_id)::text)))
          WHERE ((li.loan_cancelled_at IS NULL) AND (sch.due_date <= CURRENT_DATE))
        ), consumer_repayment_amounts AS (
         SELECT loan_schedule_base.national_id,
            sum((loan_schedule_base.due_amount - loan_schedule_base.paid_amount_as_of)) AS total_unpaid_installments,
            COALESCE(sum(loan_schedule_base.due_amount) FILTER (WHERE (loan_schedule_base.months_past_due = 0)), (0)::numeric) AS due_30_day,
            COALESCE(sum(loan_schedule_base.paid_amount_as_of) FILTER (WHERE (loan_schedule_base.months_past_due = 0)), (0)::numeric) AS paid_30_day,
            COALESCE(sum(loan_schedule_base.due_amount) FILTER (WHERE (loan_schedule_base.months_past_due = 1)), (0)::numeric) AS due_60_day,
            COALESCE(sum(loan_schedule_base.paid_amount_as_of) FILTER (WHERE (loan_schedule_base.months_past_due = 1)), (0)::numeric) AS paid_60_day,
            COALESCE(sum(loan_schedule_base.due_amount) FILTER (WHERE (loan_schedule_base.months_past_due = 2)), (0)::numeric) AS due_90_day,
            COALESCE(sum(loan_schedule_base.paid_amount_as_of) FILTER (WHERE (loan_schedule_base.months_past_due = 2)), (0)::numeric) AS paid_90_day
           FROM loan_schedule_base
          GROUP BY loan_schedule_base.national_id
        ), consumer_repayment_metrics AS (
         SELECT consumer_repayment_amounts.national_id,
            consumer_repayment_amounts.total_unpaid_installments,
            consumer_repayment_amounts.due_30_day,
            consumer_repayment_amounts.paid_30_day,
                CASE
                    WHEN (consumer_repayment_amounts.due_30_day > (0)::numeric) THEN round((consumer_repayment_amounts.paid_30_day / NULLIF(consumer_repayment_amounts.due_30_day, (0)::numeric)), 2)
                    ELSE (0)::numeric
                END AS pct_30_day,
            consumer_repayment_amounts.due_60_day,
            consumer_repayment_amounts.paid_60_day,
                CASE
                    WHEN (consumer_repayment_amounts.due_60_day > (0)::numeric) THEN round((consumer_repayment_amounts.paid_60_day / NULLIF(consumer_repayment_amounts.due_60_day, (0)::numeric)), 2)
                    ELSE (0)::numeric
                END AS pct_60_day,
            consumer_repayment_amounts.due_90_day,
            consumer_repayment_amounts.paid_90_day,
                CASE
                    WHEN (consumer_repayment_amounts.due_90_day > (0)::numeric) THEN round((consumer_repayment_amounts.paid_90_day / NULLIF(consumer_repayment_amounts.due_90_day, (0)::numeric)), 2)
                    ELSE (0)::numeric
                END AS pct_90_day
           FROM consumer_repayment_amounts
        )
 SELECT cb.consumer_id,
    cb.national_id,
    cb.phone_number,
    cb.status,
    cb.full_name,
    cb.first_activated_at,
    cb.job_name,
    ij.id_back_job,
    cb.company,
    cb.club,
    cb.governorate,
    cb.salary,
    cb.additional_salary,
    cb.total_salary,
    cb.credit_limit,
    cb.car_year,
    cb.address,
    cb.created_at,
    cb.updated_at,
    cb.activation_branch,
    cb.scoring_channel,
    pf.value AS submitted_rejected_by_user,
    pf.current_state,
    pf.current_reason,
    pf.current_comment,
    (pf.current_active_since AT TIME ZONE 'Africa/Cairo'::text) AS current_active_since,
    pf.next_state,
    pf.next_reason,
    pf.next_comment,
    pf.next_value_since,
    (pf.next_active_since AT TIME ZONE 'Africa/Cairo'::text) AS next_active_since,
    pf.next_next_state,
    pf.next_next_reason,
    pf.next_next_comment,
        CASE
            WHEN ((cb.i_score <= 0) OR (cb.i_score IS NULL)) THEN 'Unbanked'::text
            ELSE 'banked'::text
        END AS banked_status,
    COALESCE(rm.total_unpaid_installments, (0)::numeric) AS total_unpaid_installments,
    COALESCE(rm.due_30_day, (0)::numeric) AS due_30_day,
    COALESCE(rm.paid_30_day, (0)::numeric) AS paid_30_day,
    COALESCE(rm.pct_30_day, (0)::numeric) AS pct_30_day,
    COALESCE(rm.due_60_day, (0)::numeric) AS due_60_day,
    COALESCE(rm.paid_60_day, (0)::numeric) AS paid_60_day,
    COALESCE(rm.pct_60_day, (0)::numeric) AS pct_60_day,
    COALESCE(rm.due_90_day, (0)::numeric) AS due_90_day,
    COALESCE(rm.paid_90_day, (0)::numeric) AS paid_90_day,
    COALESCE(rm.pct_90_day, (0)::numeric) AS pct_90_day
   FROM (((pending_flow pf
     JOIN consumer_base_info cb ON (((cb.consumer_id)::text = (pf.consumer_id)::text)))
     LEFT JOIN idback_job ij ON (((ij.consumer_id)::text = (cb.consumer_id)::text)))
     LEFT JOIN consumer_repayment_metrics rm ON (((rm.national_id)::text = (cb.national_id)::text)));


--
-- Name: branches_new; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.branches_new (
    "Activation Branch Adjusted" character varying(50),
    " Count " integer,
    "City" character varying(50)
);


--
-- Name: v_credit_portfolio; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_credit_portfolio AS
 WITH loans_base AS (
         SELECT l.loan_id,
            l.transaction_id,
            l.consumer_id,
            l.loan_booked_at,
            l.loan_booked_date,
            l.loan_current_status,
            l.is_postponed,
            l.is_rescheduled,
            l.loan_batch_status,
            l.loan_cancelled_at,
            l.loan_early_settled_at,
            l.parent_loan_account_id,
            l.basket_value,
            l.total_principal_amount,
            l.loan_installment_amount,
            l.down_payment_amount,
            l.loan_admin_fee_amount,
            l.vat_amount,
            l.total_interest_amount,
            l.total_late_fee,
            l.total_paid_late_fee,
            l.total_due_amount,
            l.total_paid_amount,
            l.total_principal_paid_amount,
            l.total_interest_paid_amount,
            l.num_of_paid_installments,
            l.num_of_remaining_installments,
            l.total_remaining_amount_with_interest,
            l.total_remaining_amount_without_interest,
            l.potential_interest_loss_if_early_settlement,
            l.financial_product_id,
            l.financial_product_id_cb,
            l.linked_fp_key,
            l.linked_fp_version,
            l.tenor,
            l.new_tenor,
            l.tenor_interest_percent,
            l.annual_interest_percent,
            l.is_profit_bearing,
            l.retail_category,
            l.checkout_channel,
            l.merchant_id,
            l.merchant_name,
            l.merchant_created_at_utc,
            l.transacted_merchant_brand_id,
            l.transacted_merchant_branch_id,
            l.merchant_city_id,
            l.merchant_city,
            l.transacted_merchant_branch_governorate,
            l.merchant_city_adjusted,
            l.merchant_region,
            l.merchant_type,
            l.consumer_loan_sequence_number,
            l.merchant_loan_sequence_number,
            l.tenor_days,
            l.grace_period_in_days,
            l.borrower_repayment_day_of_month,
            l.view_last_refreshed_time,
            l.next_due_date,
            l.last_paid_date,
            (l.consumer_id)::uuid AS consumer_id_key
           FROM public.mv_loans_info l
        ), consumers_base AS MATERIALIZED (
         SELECT c.consumer_id,
            c.clientid,
            c.phone_number,
            c.national_id,
            c.national_id_validity,
            c.status,
            c.full_name,
            c.first_name,
            c.last_name,
            c.consumer_dob,
            c.consumer_gender,
            c.marital_status,
            c.consumer_age,
            c.consumer_age_range,
            c.job_sector,
            c.job_category,
            c.job_name,
            c.job_name_ar,
            c.company,
            c.club,
            c.car_year,
            c.house_type,
            c.region,
            c.governorate_home,
            c.city_home,
            c.address_home,
            c.governorate_national_id,
            c.city_national_id,
            c.address_national_id,
            c.governorate_work,
            c.city_work,
            c.address_work,
            c.salary_egp,
            c.additional_salary,
            c.additional_salary_source,
            c.max_credit_limit_egp,
            c.available_credit_limit_egp,
            c.income_bucket,
            c.credit_limit_bucket,
            c.credit_utilization,
            c.utilization_bucket,
            c.credit_limit_active_since,
            c.churn_status_btech,
            c.churn_status_non_btech,
            c.first_activated_at,
            c.activated_at,
            c.created_at,
            c.updated_at,
            c.single_payment_day,
            c.origination_channel,
            c.scoring_channel,
            c.new_returning_flag,
            c.comment,
            c.classification,
            c.activation_branch_adjusted,
            c.activation_branch_city,
            c.terrorist_or_sanction_flag,
            c.i_score,
            c.ob_segment,
            c.is_deleted_flag,
            c.mv_last_refreshed_time,
            c.consumer_id AS consumer_id_key
           FROM public.mv_consumers_info c
        ), schedule_base AS MATERIALIZED (
         SELECT s.loan_schedule_id,
            s.loan_id,
            s.loan_current_status,
            s.consumer_id,
            s.due_date,
            s.grace_period_ends_on,
            s.total_financed_amount,
            s.due_principal,
            s.due_interest,
            s.cumulative_principal,
            s.cumulative_interest,
            s.remaining_balance,
            s.reducing_apr,
            s.paid_at,
            s.paid_date,
            s.paid_principal,
            s.paid_interest,
            s.total_installment,
            s.paid_vat,
            s.paid_admin_fee,
            s.paid_penalty,
            s.paid_total,
            s.late_fee,
            s.paid_late_payment_fee,
            s.view_last_refreshed_time,
            (s.consumer_id)::uuid AS consumer_id_key
           FROM public.mv_loans_sch_info s
        ), branch_mapping AS (
         SELECT DISTINCT TRIM(BOTH FROM branches_new."Activation Branch Adjusted") AS activation_branch_adjusted,
            branches_new."City" AS city
           FROM public.branches_new
        ), last_paid_installment AS (
         SELECT ranked.loan_id,
            ranked.consumer_id_key,
            ranked.due_date,
            ranked.paid_date
           FROM ( SELECT s.loan_id,
                    s.consumer_id_key,
                    s.due_date,
                    s.paid_date,
                    row_number() OVER (PARTITION BY s.loan_id ORDER BY s.due_date DESC) AS rn
                   FROM schedule_base s
                  WHERE (s.paid_date IS NOT NULL)) ranked
          WHERE (ranked.rn = 1)
        ), id_back_data AS (
         SELECT ca.consumer_id AS consumer_id_key,
            (((ca.data -> 'digital_onboarding_data'::text) -> 'idBackData'::text) ->> 'job'::text) AS id_back_job
           FROM public.consumer_application ca
        ), application_flow AS (
         SELECT ca.consumer_id,
            cas.state AS current_state,
            cas.reason AS current_reason,
            cas.active_since AS current_active_since,
            lead(COALESCE(ll.value, l.value), 1) OVER (PARTITION BY ca.consumer_id ORDER BY cas.active_since) AS next_value_since,
            COALESCE(ll.value, l.value) AS submitted_rejected_by_user
           FROM ((((public.consumer_application_state cas
             JOIN public.consumer_application ca ON (((cas.consumer_application_id)::text = (ca.id)::text)))
             JOIN consumers_base cb ON (((cb.consumer_id)::text = (ca.consumer_id)::text)))
             LEFT JOIN public.identity_verifiable_addresses ll ON (((ll.identity_id)::text = (cas.created_by)::text)))
             LEFT JOIN kratos_internal.identity_verifiable_addresses l ON (((l.identity_id)::text = (cas.created_by)::text)))
          WHERE ((cb.scoring_channel)::text = 'mylo'::text)
        ), pending_flow AS (
         SELECT af.consumer_id,
            af.current_reason,
            af.current_active_since,
            af.submitted_rejected_by_user,
            af.next_value_since
           FROM application_flow af
          WHERE ((af.current_state)::text = ANY (ARRAY[('PENDING_ACTIVATION_APPROVAL'::character varying)::text, ('PENDING_ONBOARDING_APPROVAL'::character varying)::text]))
        ), pending_flow_latest AS (
         SELECT x.consumer_id,
            x.submitted_rejected_by_user,
            x.next_value_since,
            x.current_reason
           FROM ( SELECT pf.consumer_id,
                    pf.current_reason,
                    pf.current_active_since,
                    pf.submitted_rejected_by_user,
                    pf.next_value_since,
                    row_number() OVER (PARTITION BY pf.consumer_id ORDER BY pf.current_active_since DESC) AS rn
                   FROM pending_flow pf) x
          WHERE (x.rn = 1)
        ), schedule_status AS (
         SELECT s.loan_id,
            s.consumer_id_key,
            min(
                CASE
                    WHEN ((s.due_date <= CURRENT_DATE) AND ((s.paid_date IS NULL) OR (s.paid_date > CURRENT_DATE))) THEN s.due_date
                    ELSE NULL::date
                END) AS first_unpaid_due_date
           FROM schedule_base s
          GROUP BY s.loan_id, s.consumer_id_key
        )
 SELECT t1.loan_id,
    (t1.consumer_id_key)::text AS consumer_id,
    t2.phone_number,
    (t2.national_id)::bigint AS national_id,
    t2.status,
    t2.full_name,
    t2.consumer_age,
    t2.consumer_age_range,
    t2.region,
    t2.governorate_home,
    t2.city_home,
    t2.address_home,
    t2.job_sector,
    t2.job_name,
    t2.job_name_ar,
    t2.company,
    t2.salary_egp,
    t2.max_credit_limit_egp,
    t2.available_credit_limit_egp,
    (t2.max_credit_limit_egp - t2.available_credit_limit_egp) AS used_credit_limit_egp,
    COALESCE((round((((t2.max_credit_limit_egp - t2.available_credit_limit_egp) * 100.0) / NULLIF(t2.max_credit_limit_egp, (0)::numeric)), 2) || '%'::text), '0%'::text) AS used_credit_limit_pct,
    (t2.first_activated_at)::date AS first_activated_at,
    (t2.activated_at)::date AS activated_at,
    t2.scoring_channel,
    t2.activation_branch_adjusted,
    bn.city AS activation_branch_city,
        CASE
            WHEN (lower(TRIM(BOTH FROM t2.activation_branch_adjusted)) = 'digital-onboarding'::text) THEN 'Other'::text
            WHEN (NULLIF(TRIM(BOTH FROM bn.city), ''::text) IS NULL) THEN ''::text
            WHEN ((bn.city)::text = 'Alexandria'::text) THEN 'Alex'::text
            WHEN ((bn.city)::text = 'Cairo'::text) THEN 'Cairo'::text
            WHEN ((bn.city)::text = ANY (ARRAY[('Aswan'::character varying)::text, ('Asyut'::character varying)::text, ('Beni Suef'::character varying)::text, ('Faiyum'::character varying)::text, ('Hurghada'::character varying)::text, ('Ras Ghareb'::character varying)::text, ('Luxor'::character varying)::text, ('Mallawi'::character varying)::text, ('Minya'::character varying)::text, ('Nagaa Hammadi'::character varying)::text, ('Qena'::character varying)::text, ('Sohag'::character varying)::text])) THEN 'Upper'::text
            WHEN ((bn.city)::text = ANY (ARRAY[('Benha'::character varying)::text, ('Damanhur'::character varying)::text, ('Dekernes'::character varying)::text, ('Kafr el-Dawwar'::character varying)::text, ('Kafr El-Sheikh'::character varying)::text, ('Mahalla'::character varying)::text, ('Mansoura'::character varying)::text, ('Tanta'::character varying)::text, ('Zagazig'::character varying)::text, ('Shebin El Koum'::character varying)::text, ('Kafr El Zayat'::character varying)::text])) THEN 'Delta'::text
            WHEN ((bn.city)::text = ANY (ARRAY[('Ismailia'::character varying)::text, ('Port Said'::character varying)::text, ('Suez'::character varying)::text])) THEN 'Canal'::text
            ELSE 'Other'::text
        END AS activation_branch_region,
    t2.i_score,
    ib.id_back_job,
    pfl.submitted_rejected_by_user,
    pfl.next_value_since,
    pfl.current_reason,
    t1.loan_booked_date,
    t3.due_date AS first_installment_due_date,
    t3.paid_date AS first_installment_paid_date,
    t1.next_due_date,
    t1.last_paid_date,
    ss.first_unpaid_due_date,
        CASE
            WHEN (t1.loan_current_status = 'RUNNING'::text) THEN
            CASE
                WHEN (t1.next_due_date > CURRENT_DATE) THEN 'TRUE'::text
                ELSE 'FALSE'::text
            END
            ELSE t1.loan_current_status
        END AS not_due_yet,
        CASE
            WHEN (t1.loan_current_status = 'RUNNING'::text) THEN
            CASE
                WHEN (((t3.paid_date IS NULL) AND (CURRENT_DATE > (t3.due_date + '30 days'::interval))) OR ((t3.paid_date IS NOT NULL) AND (t3.paid_date > (t3.due_date + '30 days'::interval)))) THEN 'TRUE'::text
                ELSE 'FALSE'::text
            END
            ELSE t1.loan_current_status
        END AS fpd,
        CASE
            WHEN (t1.loan_current_status = 'RUNNING'::text) THEN
            CASE
                WHEN ((li.paid_date IS NOT NULL) AND (li.paid_date <= li.due_date)) THEN 'TRUE'::text
                ELSE 'FALSE'::text
            END
            ELSE t1.loan_current_status
        END AS current,
        CASE
            WHEN (t1.loan_current_status = 'RUNNING'::text) THEN
            CASE
                WHEN ((t3.paid_date IS NULL) AND (CURRENT_DATE > (t3.due_date + '90 days'::interval))) THEN 'TRUE'::text
                ELSE 'FALSE'::text
            END
            ELSE t1.loan_current_status
        END AS non_starter,
        CASE
            WHEN (t1.loan_current_status = 'RUNNING'::text) THEN
            CASE
                WHEN ((ss.first_unpaid_due_date IS NOT NULL) AND ((CURRENT_DATE - ss.first_unpaid_due_date) > 30)) THEN 'TRUE'::text
                ELSE 'FALSE'::text
            END
            ELSE t1.loan_current_status
        END AS par_30_plus,
        CASE
            WHEN (t1.loan_current_status = 'RUNNING'::text) THEN
            CASE
                WHEN ((ss.first_unpaid_due_date IS NOT NULL) AND ((CURRENT_DATE - ss.first_unpaid_due_date) > 60)) THEN 'TRUE'::text
                ELSE 'FALSE'::text
            END
            ELSE t1.loan_current_status
        END AS par_60_plus,
        CASE
            WHEN (t1.loan_current_status = 'RUNNING'::text) THEN
            CASE
                WHEN ((ss.first_unpaid_due_date IS NOT NULL) AND ((CURRENT_DATE - ss.first_unpaid_due_date) > 90)) THEN 'TRUE'::text
                ELSE 'FALSE'::text
            END
            ELSE t1.loan_current_status
        END AS npl,
        CASE
            WHEN (t1.loan_current_status = 'RUNNING'::text) THEN
            CASE
                WHEN (ss.first_unpaid_due_date IS NOT NULL) THEN ((CURRENT_DATE - ss.first_unpaid_due_date))::text
                ELSE '0'::text
            END
            ELSE t1.loan_current_status
        END AS dpd,
    t1.loan_current_status,
    t1.loan_early_settled_at,
    t1.basket_value,
    t1.total_principal_amount,
    t1.loan_installment_amount,
    t1.down_payment_amount,
    t1.total_interest_amount,
    t1.total_due_amount,
    t1.total_paid_amount,
    t1.total_principal_paid_amount,
    t1.total_interest_paid_amount,
    t1.num_of_paid_installments,
    t1.num_of_remaining_installments,
    t1.total_remaining_amount_with_interest,
    t1.total_remaining_amount_without_interest,
    t1.potential_interest_loss_if_early_settlement,
    t1.tenor,
    t1.new_tenor,
    t1.retail_category,
    t1.checkout_channel,
    t1.merchant_name,
    t1.merchant_created_at_utc,
    t1.merchant_region,
    t1.merchant_city,
    t2.comment
   FROM (((((((loans_base t1
     LEFT JOIN consumers_base t2 ON ((t2.consumer_id_key = t1.consumer_id_key)))
     LEFT JOIN schedule_base t3 ON ((((t3.loan_id)::text = (t1.loan_id)::text) AND (t3.consumer_id_key = t1.consumer_id_key) AND (t3.loan_schedule_id = 1))))
     LEFT JOIN last_paid_installment li ON ((((li.loan_id)::text = (t1.loan_id)::text) AND (li.consumer_id_key = t1.consumer_id_key))))
     LEFT JOIN id_back_data ib ON ((ib.consumer_id_key = t1.consumer_id_key)))
     LEFT JOIN schedule_status ss ON ((((ss.loan_id)::text = (t1.loan_id)::text) AND (ss.consumer_id_key = t1.consumer_id_key))))
     LEFT JOIN pending_flow_latest pfl ON (((pfl.consumer_id)::text = (t2.consumer_id)::text)))
     LEFT JOIN branch_mapping bn ON ((TRIM(BOTH FROM t2.activation_branch_adjusted) = bn.activation_branch_adjusted)))
  WHERE (1 = 1);


--
-- Name: journal; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.journal (
    id integer NOT NULL,
    correlation_id character varying(8000) NOT NULL,
    account character varying(8000) NOT NULL,
    direction character varying(255) NOT NULL,
    amount bigint NOT NULL,
    booked_at timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    created_by character varying(50) NOT NULL,
    transaction_id integer NOT NULL,
    loan_id character varying(50) NOT NULL,
    type character varying(8000) NOT NULL
)
WITH (parallel_workers='8');


--
-- Name: journal_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.journal_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: journal_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.journal_id_seq OWNED BY public.journal.id;


--
-- Name: journal; Type: TABLE; Schema: loan_management; Owner: -
--

CREATE TABLE loan_management.journal (
    id bigint DEFAULT nextval('public.journal_id_seq'::regclass) NOT NULL,
    linked_entity_id character varying NOT NULL,
    linked_entity_type character varying NOT NULL,
    lender_source character varying NOT NULL,
    event_id character varying NOT NULL,
    event_type character varying NOT NULL,
    transaction_group integer NOT NULL,
    cost_center character varying NOT NULL,
    account character varying NOT NULL,
    sub_account character varying NOT NULL,
    direction public.journal_direction NOT NULL,
    amount bigint NOT NULL,
    booked_at timestamp with time zone NOT NULL
);


--
-- Name: loan_account; Type: TABLE; Schema: loan_management; Owner: -
--

CREATE TABLE loan_management.loan_account (
    id character varying NOT NULL,
    version integer NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    created_by character varying NOT NULL,
    updated_by character varying NOT NULL,
    updated_by_event_id character varying NOT NULL,
    state character varying NOT NULL,
    sub_state character varying NOT NULL,
    borrower_id character varying NOT NULL,
    borrower_repayment_day_of_month integer NOT NULL,
    commercial_offer_id character varying NOT NULL,
    financial_product_id character varying NOT NULL,
    financial_product_tenor_key character varying NOT NULL,
    tenor_days integer NOT NULL,
    grace_period_in_days integer NOT NULL,
    booked_at timestamp with time zone NOT NULL,
    loan_start_date timestamp with time zone,
    loan_maturity_date timestamp with time zone,
    merchant_id character varying NOT NULL,
    lender_source character varying NOT NULL,
    origination_channel character varying NOT NULL,
    applied_currency character varying(3) NOT NULL,
    fr_basis_points integer NOT NULL,
    monthly_effective_rate double precision NOT NULL,
    total_effective_rate double precision NOT NULL,
    annual_percent_rate double precision NOT NULL,
    vat_basis_points integer NOT NULL,
    admin_fee_basis_points integer NOT NULL,
    es_fee_basis_points integer NOT NULL,
    bd_allowance_basis_points integer NOT NULL,
    rounding_up_est_gain_units integer NOT NULL,
    financial_product_version integer DEFAULT 3 NOT NULL,
    parent_loan_account_id character varying,
    daily_effective_rate double precision,
    daily_rate_principal_reference bigint,
    daily_rate_reference_date timestamp with time zone,
    daily_installment double precision,
    compounding_frequency character varying
);


--
-- Name: loan_account_payment; Type: TABLE; Schema: loan_management; Owner: -
--

CREATE TABLE loan_management.loan_account_payment (
    loan_account_id character varying NOT NULL,
    payment_reference_id character varying NOT NULL,
    ammortisation_line_item_sequence integer NOT NULL,
    booked_at timestamp with time zone NOT NULL,
    applied_currency character varying(3) NOT NULL,
    paid_units bigint NOT NULL,
    updated_by_event_id character varying NOT NULL
);


--
-- Name: partner; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.partner (
    status character varying(255) NOT NULL,
    tax_registration_number character varying(9) NOT NULL,
    commercial_registration_number character varying(80),
    id uuid NOT NULL,
    created_at timestamp(6) without time zone NOT NULL,
    updated_at timestamp(6) without time zone NOT NULL,
    legal_name character varying(255) NOT NULL
);


--
-- Name: partner_brand; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.partner_brand (
    id uuid NOT NULL,
    category character varying(255),
    partner_id uuid,
    created_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone,
    name_en character varying(255) NOT NULL,
    name_ar character varying(255) NOT NULL,
    status character varying(255) NOT NULL,
    logo_url character varying,
    key_account_order integer
);


--
-- Name: v_journal_report; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_journal_report AS
 WITH journal_payments_channel AS (
         SELECT journal.linked_entity_id,
            journal.account AS payment_channel,
            journal.sub_account AS sub_payment_channel,
            journal.event_id,
            journal.event_type
           FROM loan_management.journal
          WHERE (((journal.lender_source)::text = 'payments'::text) AND ((journal.cost_center)::text = 'world'::text))
          GROUP BY journal.linked_entity_id, journal.account, journal.sub_account, journal.event_id, journal.event_type
        ), journal_payments_consumer AS (
         SELECT journal.linked_entity_id,
            journal.account AS consumer_id
           FROM loan_management.journal
          WHERE (((journal.lender_source)::text = 'payments'::text) AND ((journal.cost_center)::text = 'consumer'::text))
          GROUP BY journal.linked_entity_id, journal.account
        ), journal_payments AS (
         SELECT jpc.linked_entity_id,
            jpc.payment_channel,
            jpc.sub_payment_channel,
            jpc.event_id,
            jpc.event_type,
            jpco.consumer_id
           FROM (journal_payments_channel jpc
             JOIN journal_payments_consumer jpco ON (((jpc.linked_entity_id)::text = (jpco.linked_entity_id)::text)))
        ), journal_payments_all AS (
         SELECT jp.consumer_id,
            jp.payment_channel,
            jp.sub_payment_channel,
            j.id,
            j.linked_entity_id,
            j.linked_entity_type,
            j.lender_source,
            j.event_id,
            j.event_type,
            j.transaction_group,
            j.cost_center,
            j.account,
            j.sub_account,
            j.direction,
            j.amount,
            j.booked_at
           FROM (journal_payments jp
             JOIN loan_management.journal j ON ((((jp.linked_entity_id)::text = (j.linked_entity_id)::text) AND ((jp.event_id)::text = (j.event_id)::text))))
        ), journal_payments_det AS (
         SELECT lap.loan_account_id AS loan_id,
            jpa.consumer_id,
            jpa.payment_channel,
            jpa.sub_payment_channel,
            jpa.id,
            jpa.linked_entity_id,
            jpa.linked_entity_type,
            jpa.lender_source,
            jpa.event_id,
            jpa.event_type,
            jpa.transaction_group,
            jpa.cost_center,
            jpa.account,
            jpa.sub_account,
            jpa.direction,
            jpa.amount,
            jpa.booked_at,
            pb.partner_id,
            pb.name_en AS merchant_name,
                CASE
                    WHEN (pb.partner_id = '09bebad1-8352-4e77-938e-eed5b16fcdf3'::uuid) THEN 'B.TECH'::text
                    WHEN (pb.partner_id IS NULL) THEN NULL::text
                    ELSE 'Other Merchant'::text
                END AS flag
           FROM (((journal_payments_all jpa
             LEFT JOIN loan_management.loan_account_payment lap ON (((lap.payment_reference_id)::text = (jpa.linked_entity_id)::text)))
             LEFT JOIN public.checkout_baskets cb ON ((cb.loan_id = (lap.loan_account_id)::uuid)))
             LEFT JOIN public.partner_brand pb ON ((cb.brand_id = pb.id)))
        ), journal_loans AS (
         SELECT journal.linked_entity_id,
            journal.account AS loan_id
           FROM loan_management.journal
          WHERE ((journal.cost_center)::text = 'loan'::text)
          GROUP BY journal.linked_entity_id, journal.account
        ), journal_all AS (
         SELECT jl.loan_id,
            NULL::text AS payment_channel,
            NULL::text AS sub_payment_channel,
            j.id,
            j.linked_entity_id,
            j.linked_entity_type,
            j.lender_source,
            j.event_id,
            j.event_type,
            j.transaction_group,
            j.cost_center,
            j.account,
            j.sub_account,
            j.direction,
            j.amount,
            j.booked_at
           FROM (journal_loans jl
             JOIN loan_management.journal j ON (((jl.linked_entity_id)::text = (j.linked_entity_id)::text)))
          WHERE ((j.linked_entity_type)::text = 'loan_account'::text)
        ), journal_loan_det AS (
         SELECT la_1.borrower_id AS consumer_id,
            ja.loan_id,
            ja.payment_channel,
            ja.sub_payment_channel,
            ja.id,
            ja.linked_entity_id,
            ja.linked_entity_type,
            ja.lender_source,
            ja.event_id,
            ja.event_type,
            ja.transaction_group,
            ja.cost_center,
            ja.account,
            ja.sub_account,
            ja.direction,
            ja.amount,
            ja.booked_at,
            pb.partner_id,
            pb.name_en AS merchant_name,
                CASE
                    WHEN (pb.partner_id = '09bebad1-8352-4e77-938e-eed5b16fcdf3'::uuid) THEN 'B.TECH'::text
                    WHEN (pb.partner_id IS NULL) THEN NULL::text
                    ELSE 'Other Merchant'::text
                END AS flag
           FROM (((journal_all ja
             LEFT JOIN loan_management.loan_account la_1 ON (((la_1.id)::text = (ja.loan_id)::text)))
             LEFT JOIN public.checkout_baskets cb ON ((cb.loan_id = (la_1.id)::uuid)))
             LEFT JOIN public.partner_brand pb ON ((cb.brand_id = pb.id)))
        ), final_union AS (
         SELECT journal_loan_det.consumer_id,
            journal_loan_det.loan_id,
            journal_loan_det.payment_channel,
            journal_loan_det.sub_payment_channel,
            journal_loan_det.id,
            journal_loan_det.linked_entity_id,
            journal_loan_det.linked_entity_type,
            journal_loan_det.lender_source,
            journal_loan_det.event_id,
            journal_loan_det.event_type,
            journal_loan_det.transaction_group,
            journal_loan_det.cost_center,
            journal_loan_det.account,
            journal_loan_det.sub_account,
            journal_loan_det.direction,
            journal_loan_det.amount,
            journal_loan_det.booked_at,
            journal_loan_det.merchant_name,
            journal_loan_det.partner_id,
            journal_loan_det.flag
           FROM journal_loan_det
        UNION ALL
         SELECT journal_payments_det.consumer_id,
            journal_payments_det.loan_id,
            journal_payments_det.payment_channel,
            journal_payments_det.sub_payment_channel,
            journal_payments_det.id,
            journal_payments_det.linked_entity_id,
            journal_payments_det.linked_entity_type,
            journal_payments_det.lender_source,
            journal_payments_det.event_id,
            journal_payments_det.event_type,
            journal_payments_det.transaction_group,
            journal_payments_det.cost_center,
            journal_payments_det.account,
            journal_payments_det.sub_account,
            journal_payments_det.direction,
            journal_payments_det.amount,
            journal_payments_det.booked_at,
            journal_payments_det.merchant_name,
            journal_payments_det.partner_id,
            journal_payments_det.flag
           FROM journal_payments_det
        ), final_result AS (
         SELECT (NULLIF(TRIM(BOTH FROM (final_union.consumer_id)::text), ''::text))::uuid AS consumer_id,
            (final_union.loan_id)::uuid AS loan_id,
            final_union.payment_channel,
            final_union.sub_payment_channel,
            final_union.id,
            (final_union.linked_entity_id)::text AS ref_number,
            (final_union.linked_entity_type)::text AS linked_entity_type,
            (final_union.lender_source)::text AS lender_source,
            (final_union.event_id)::text AS event_id,
            (final_union.event_type)::text AS event_type,
            final_union.transaction_group,
            (final_union.cost_center)::text AS cost_center,
                CASE
                    WHEN (((final_union.cost_center)::text = 'consumer'::text) AND ((final_union.sub_account)::text = 'wallet'::text)) THEN 'CustomerCollections'::character varying
                    WHEN (((final_union.cost_center)::text = 'world'::text) AND ((final_union.account)::text = ANY (ARRAY[('BTECH_STORE_CASH'::character varying)::text, ('BTECH_STORE_POS'::character varying)::text]))) THEN 'BtechCollections'::character varying
                    WHEN ((final_union.cost_center)::text = ANY (ARRAY[('loan'::character varying)::text, ('mylo'::character varying)::text, ('merchant'::character varying)::text])) THEN final_union.sub_account
                    ELSE final_union.account
                END AS account_name,
            (final_union.account)::text AS account,
            (final_union.sub_account)::text AS sub_account,
            (final_union.direction)::text AS direction,
            ((final_union.amount)::numeric / 100.0) AS amount,
                CASE
                    WHEN ((final_union.direction = 'CREDIT'::public.journal_direction) AND (((final_union.amount)::numeric / 100.0) <> 0.00)) THEN (((final_union.amount)::numeric / (100)::numeric) * ('-1'::integer)::numeric)
                    WHEN ((final_union.direction = 'CREDIT'::public.journal_direction) AND (((final_union.amount)::numeric / (100)::numeric) = 0.00)) THEN (0)::numeric
                    ELSE (0)::numeric
                END AS credit,
                CASE
                    WHEN ((final_union.direction = 'DEBIT'::public.journal_direction) AND (((final_union.amount)::numeric / (100)::numeric) <> 0.00)) THEN ((final_union.amount)::numeric / (100)::numeric)
                    WHEN ((final_union.direction = 'CREDIT'::public.journal_direction) AND (((final_union.amount)::numeric / (100)::numeric) = 0.00)) THEN (0)::numeric
                    ELSE (0)::numeric
                END AS debit,
            final_union.booked_at,
            ((final_union.booked_at AT TIME ZONE 'Africa/Cairo'::text))::date AS booked_date,
            final_union.partner_id,
            (final_union.merchant_name)::text AS merchant_name,
            final_union.flag,
            now() AS view_last_refreshed_time
           FROM final_union
        )
 SELECT fr.consumer_id,
    fr.loan_id,
    fr.payment_channel,
    fr.sub_payment_channel,
    fr.id,
    fr.ref_number,
    fr.linked_entity_type,
    fr.lender_source,
    fr.event_id,
    fr.event_type,
    fr.transaction_group,
    fr.cost_center,
    fr.account_name,
    fr.account,
    fr.sub_account,
    fr.direction,
    fr.amount,
    fr.credit,
    fr.debit,
    fr.booked_at,
    fr.booked_date,
    COALESCE(fr.partner_id, p.id) AS partner_id,
    fr.merchant_name,
    p.legal_name AS merchant_legal_name,
    COALESCE(fr.flag,
        CASE
            WHEN (p.id = '09bebad1-8352-4e77-938e-eed5b16fcdf3'::uuid) THEN 'B.TECH'::text
            WHEN (p.id IS NULL) THEN NULL::text
            ELSE 'Other Merchant'::text
        END) AS flag,
    fr.view_last_refreshed_time
   FROM ((final_result fr
     LEFT JOIN loan_management.loan_account la ON (((fr.loan_id)::text = (la.id)::text)))
     LEFT JOIN public.partner p ON (((p.id)::text = (la.merchant_id)::text)));


