--
-- Name: v_journal_short_report; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_journal_short_report AS
 SELECT id,
    consumer_id,
    loan_id,
    payment_channel,
    sub_payment_channel,
    ref_number,
    event_type,
    transaction_group,
    (account_name)::text AS account_name,
    direction,
    amount,
    credit,
    debit,
    booked_date,
    partner_id,
    merchant_name,
    merchant_legal_name,
    flag,
    now() AS view_last_refreshed_time
   FROM ( SELECT mv_journal_report.id,
            mv_journal_report.consumer_id,
            string_agg((mv_journal_report.loan_id)::text, ', '::text) AS loan_id,
            mv_journal_report.payment_channel,
            mv_journal_report.sub_payment_channel,
            mv_journal_report.ref_number,
            mv_journal_report.event_type,
            mv_journal_report.transaction_group,
            mv_journal_report.account_name,
            mv_journal_report.direction,
            mv_journal_report.amount,
            mv_journal_report.credit,
            mv_journal_report.debit,
            mv_journal_report.booked_date,
            string_agg((mv_journal_report.partner_id)::text, ', '::text) AS partner_id,
            string_agg(mv_journal_report.merchant_name, ', '::text) AS merchant_name,
            string_agg((mv_journal_report.merchant_legal_name)::text, ', '::text) AS merchant_legal_name,
            string_agg(mv_journal_report.flag, ', '::text) AS flag
           FROM public.mv_journal_report
          GROUP BY mv_journal_report.id, mv_journal_report.consumer_id, mv_journal_report.payment_channel, mv_journal_report.sub_payment_channel, mv_journal_report.ref_number, mv_journal_report.event_type, mv_journal_report.transaction_group, mv_journal_report.account_name, mv_journal_report.direction, mv_journal_report.amount, mv_journal_report.credit, mv_journal_report.debit, mv_journal_report.booked_date) unnamed_subquery;


