--
-- Name: v_late_consumer; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_late_consumer AS
 WITH overdues AS (
         SELECT la.loan_account_id,
            min(la.installment_due_date) AS earliest_due_date,
            max((la.principal_due_units + la.interest_due_units)) AS max_monthly_installment,
            sum((la.principal_due_units + la.interest_due_units)) AS total_overdue_amount,
            count(la.line_item_sequence) AS overdue_installments_count
           FROM loan_management.loan_account_ammortisation_line_item la
          WHERE ((la.installment_due_date < CURRENT_DATE) AND (la.total_paid_units = 0) AND (NOT la.canceled))
          GROUP BY la.loan_account_id
        ), lms_data AS (
         SELECT t.consumer_id,
            t.late_since,
            t.monthly_installment,
            t.total_overdue_amount,
            t.overdue_days,
            t.overdue_installments_count,
                CASE
                    WHEN ((t.overdue_days >= 0) AND (t.overdue_days <= 30)) THEN '0-30'::text
                    WHEN ((t.overdue_days >= 31) AND (t.overdue_days <= 60)) THEN '31-60'::text
                    WHEN ((t.overdue_days >= 61) AND (t.overdue_days <= 90)) THEN '61-90'::text
                    WHEN ((t.overdue_days >= 91) AND (t.overdue_days <= 120)) THEN '91-120'::text
                    WHEN (t.overdue_days > 120) THEN '120+'::text
                    ELSE 'UNKNOWN'::text
                END AS overdue_bucket
           FROM ( SELECT l.borrower_id AS consumer_id,
                    min(date_trunc('day'::text, om.earliest_due_date)) AS late_since,
                    sum(om.max_monthly_installment) AS monthly_installment,
                    sum(om.total_overdue_amount) AS total_overdue_amount,
                    max((CURRENT_DATE - (om.earliest_due_date)::date)) AS overdue_days,
                    sum(om.overdue_installments_count) AS overdue_installments_count
                   FROM (loan_management.loan_account l
                     JOIN overdues om ON (((l.id)::text = (om.loan_account_id)::text)))
                  WHERE ((l.state)::text = 'ACTIVE'::text)
                  GROUP BY l.borrower_id) t
        ), consumer_activation_data AS (
         SELECT DISTINCT ON (consumer_state.consumer_id) consumer_state.consumer_id,
            consumer_state.state,
            consumer_state.branch,
            consumer_state.active_since AS activation_date
           FROM public.consumer_state
          WHERE ((consumer_state.state)::text = 'ACTIVE'::text)
          ORDER BY consumer_state.consumer_id, consumer_state.active_since
        ), consumer_latest_state AS (
         SELECT DISTINCT ON (consumer_state.consumer_id) consumer_state.consumer_id,
            consumer_state.state
           FROM public.consumer_state
          ORDER BY consumer_state.consumer_id, consumer_state.active_since DESC
        ), consumer_address AS (
         SELECT ca.consumer_id,
            r.name_en,
            r.name_ar,
            r.id AS region_id,
            c.name_en AS city_name_en,
            c.name_ar AS city_name_ar,
            c.id AS city_id,
            g.name_en AS governorate_name_en,
            g.name_ar AS governorate_name_ar,
            g.id AS governorate_id
           FROM (((public.consumer_address ca
             JOIN public.governorates g ON ((ca.governorate_id = g.id)))
             JOIN public.regions r ON ((r.id = g.region_id)))
             JOIN public.cities c ON ((c.id = ca.city_id)))
          WHERE ((ca.is_primary = true) AND (ca.is_active = true) AND ((ca.type)::text = 'home'::text))
        ), latest_visit AS (
         SELECT DISTINCT ON (visit.consumer_id) visit.consumer_id,
            visit.visit_output,
            visit.visit_state
           FROM collection_db.visit
          WHERE ((visit.visit_state)::text = 'COMPLETED'::text)
          ORDER BY visit.consumer_id, visit.created_at DESC
        ), assigned_agent AS (
         SELECT a.consumer_id,
            u.name
           FROM (collection_db.assignations a
             JOIN collection_db.users u ON ((u.iam_id = a.agent_id)))
        ), last_payment AS (
         SELECT p.consumer_id,
            max(p.created_at) AS last_payment
           FROM repayments.payments p
          WHERE (p.status = 'COMPLETED'::text)
          GROUP BY p.consumer_id
        ), consumer_data AS (
         SELECT DISTINCT ON (ccl.consumer_id) ccl.consumer_id,
            cud.full_name,
            ca.national_id,
            ca.phone_number_e164 AS phone_number,
            concat_ws(' '::text, cud.first_name, cud.middle_name, cud.last_name) AS concatenated_full_name,
            ccl.max_credit_limit AS credit_limit,
            ccl.available_credit_limit,
            (ccl.max_credit_limit - ccl.available_credit_limit) AS utilized_credit_limit,
            cad.branch,
            cad.activation_date,
            cls.state,
            ck.origination_channel,
            mc.class,
            ld.late_since,
            ld.monthly_installment,
            ld.total_overdue_amount,
            ld.overdue_days,
            ld.overdue_installments_count,
            ld.overdue_bucket,
            cadr.name_en AS region,
            cadr.region_id,
            cadr.city_name_en AS city,
            cadr.city_id,
            cadr.governorate_name_en AS governorate,
            cadr.governorate_id,
            lv.visit_output,
            ag.name AS agent_name,
            lp.last_payment
           FROM (((((((((((public.consumer_user_details cud
             JOIN public.consumer_application ca ON ((cud.consumer_id = ca.consumer_id)))
             JOIN public.consumer_kyc ck ON ((ck.consumer_id = ca.consumer_id)))
             LEFT JOIN public.minicash_consumers mc ON (((mc.national_id)::text = (ca.national_id)::text)))
             JOIN public.consumer_credit_limits ccl ON ((ccl.consumer_id = ca.consumer_id)))
             JOIN consumer_activation_data cad ON ((cad.consumer_id = ca.consumer_id)))
             JOIN consumer_latest_state cls ON ((cls.consumer_id = ca.consumer_id)))
             JOIN lms_data ld ON (((ld.consumer_id)::text = (ca.consumer_id)::text)))
             LEFT JOIN consumer_address cadr ON ((cadr.consumer_id = ca.consumer_id)))
             LEFT JOIN latest_visit lv ON ((lv.consumer_id = ca.consumer_id)))
             LEFT JOIN assigned_agent ag ON ((ag.consumer_id = ca.consumer_id)))
             LEFT JOIN last_payment lp ON ((lp.consumer_id = ca.consumer_id)))
          ORDER BY ccl.consumer_id, ccl.active_since DESC
        )
 SELECT consumer_id,
    full_name,
    national_id,
    phone_number,
    concatenated_full_name,
    credit_limit,
    available_credit_limit,
    utilized_credit_limit,
    branch,
    activation_date,
    state,
    origination_channel,
    class,
    late_since,
    monthly_installment,
    total_overdue_amount,
    overdue_days,
    overdue_installments_count,
    overdue_bucket,
    region,
    region_id,
    city,
    city_id,
    governorate,
    governorate_id,
    visit_output,
    agent_name,
    last_payment
   FROM consumer_data;


