    rescheduled_at timestamp(6) with time zone NOT NULL,
    old_monthly_installment bigint NOT NULL,
    new_monthly_installment bigint NOT NULL,
    old_interest_amount bigint NOT NULL,
    new_interest_amount bigint NOT NULL,
    event_id character varying(8000) NOT NULL,
    old_tenor integer NOT NULL,
    new_tenor integer NOT NULL,
    id uuid NOT NULL
);


--
-- Name: offloading_loans; Type: TABLE; Schema: offloading; Owner: -
--

CREATE TABLE offloading.offloading_loans (
    id integer NOT NULL,
    loan_id character(36) NOT NULL,
    consumer_id character(36) NOT NULL,
    state character varying(255),
    source character varying(255),
    external_loan_id character varying(255),
    request_id character varying(255),
    created_at timestamp(6) without time zone NOT NULL,
    updated_at timestamp(6) without time zone NOT NULL,
    correlation_id character varying(8000),
    batch_id integer
);


--
-- Name: securitizations; Type: TABLE; Schema: offloading; Owner: -
--

CREATE TABLE offloading.securitizations (
    securitization_id integer NOT NULL,
    loan_id uuid NOT NULL,
    batch_id character varying(8000) NOT NULL,
    state character varying(8000) NOT NULL,
    created_at timestamp(6) without time zone NOT NULL,
    updated_at timestamp(6) without time zone NOT NULL
);


--
-- Name: brand_branch; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.brand_branch (
    partner_id uuid NOT NULL,
    street character varying(80) NOT NULL,
    location_latitude character varying(80) NOT NULL,
    location_longitude character varying(80) NOT NULL,
    id uuid NOT NULL,
    created_at timestamp(6) without time zone NOT NULL,
    updated_at timestamp(6) without time zone NOT NULL,
    google_maps_link text,
    name character varying(255) NOT NULL,
    governorate_id integer,
    city_id integer,
    area_id integer,
    brand_id uuid NOT NULL,
    branch_type character varying(255),
    client_id text,
    status character varying(255) NOT NULL,
    website_url text
);


--
-- Name: checkout_basket_loan_action; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.checkout_basket_loan_action (
    id uuid NOT NULL,
    checkout_basket_id uuid,
    loan_id uuid,
    action character varying(255),
    metadata jsonb,
    loan_amount integer,
    partner_user_id uuid,
    created_at timestamp(6) with time zone NOT NULL
);


--
-- Name: ref_securitizations_offloading_batches; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.ref_securitizations_offloading_batches AS
 SELECT (ol.loan_id)::uuid AS loan_id,
    (ol.consumer_id)::uuid AS consumer_id,
        CASE
            WHEN (((ol.state)::text = 'OFFLOADED'::text) AND (ol.external_loan_id IS NULL)) THEN 'IN_PROGRESS'::character varying
            ELSE ol.state
        END AS state,
    ('OFF_'::text || ol.batch_id) AS batch_status
   FROM offloading.offloading_loans ol
  WHERE (ol.loan_id = 'c2c4b114-1a25-11f1-a652-0610ff9dc743'::bpchar)
UNION ALL
 SELECT s.loan_id,
    (la.borrower_id)::uuid AS consumer_id,
    s.state,
    replace((s.batch_id)::text, 'SEC '::text, 'SEC_'::text) AS batch_status
   FROM (offloading.securitizations s
     JOIN loan_management.loan_account la ON (((la.id)::text = (s.loan_id)::text)))
  WITH NO DATA;


--
-- Name: v_loans_info; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_loans_info AS
 WITH new_tenor AS (
         SELECT l.loan_account_id AS loan_id,
                CASE
                    WHEN ((la.sub_state)::text = 'EARLY_SETTLEMENT_REQUESTED'::text) THEN ((la.tenor_days / 30))::bigint
                    WHEN ((la.sub_state)::text = 'EARLY_SETTLED'::text) THEN ((la.tenor_days / 30))::bigint
                    ELSE count(*) FILTER (WHERE (l.canceled = false))
                END AS new_tenor
           FROM (loan_management.loan_account_ammortisation_line_item l
             JOIN loan_management.loan_account la ON (((l.loan_account_id)::text = (la.id)::text)))
          GROUP BY l.loan_account_id, la.sub_state, la.tenor_days
        ), active AS (
         SELECT t1_1.loan_account_id,
            t1_1.line_item_sequence,
            t1_1.loan_balance_units,
            t1_1.total_due_units,
            t1_1.principal_paid_units,
            t1_1.interest_paid_units,
            t1_1.total_paid_units,
            t1_1.cumulative_interest_units,
            t1_1.penalty_due_units,
            t1_1.penalty_paid_units,
            t1_1.principal_due_units,
            t1_1.interest_due_units,
            ((t1_1.principal_due_units)::numeric + (t1_1.interest_due_units)::numeric) AS loan_installment_amount,
            row_number() OVER (PARTITION BY t1_1.loan_account_id ORDER BY t1_1.line_item_sequence) AS rn_asc,
            t1_1.installment_due_date,
            t1_1.canceled_reason,
            t1_1.canceled,
            'ACTIVE'::text AS loan_status
           FROM (loan_management.loan_account_ammortisation_line_item t1_1
             JOIN loan_management.loan_account t2_1 ON ((((t1_1.loan_account_id)::text = (t2_1.id)::text) AND ((t2_1.state)::text = 'ACTIVE'::text))))
          WHERE ((t1_1.canceled IS FALSE) OR ((t1_1.canceled IS TRUE) AND ((t1_1.canceled_reason)::text = 'EARLY_SETTLEMENT_REQUESTED'::text)))
        ), closed AS (
         SELECT t1_1.loan_account_id,
            t1_1.line_item_sequence,
            t1_1.loan_balance_units,
            t1_1.total_due_units,
            t1_1.principal_paid_units,
            t1_1.interest_paid_units,
            t1_1.total_paid_units,
            t1_1.cumulative_interest_units,
            t1_1.penalty_due_units,
            t1_1.penalty_paid_units,
            t1_1.principal_due_units,
            t1_1.interest_due_units,
            ((t1_1.principal_due_units)::numeric + (t1_1.interest_due_units)::numeric) AS loan_installment_amount,
            row_number() OVER (PARTITION BY t1_1.loan_account_id ORDER BY t1_1.line_item_sequence) AS rn_asc,
            t1_1.installment_due_date,
            t1_1.canceled_reason,
            t1_1.canceled,
            'CANCELED'::text AS loan_status
           FROM (loan_management.loan_account_ammortisation_line_item t1_1
             JOIN loan_management.loan_account t2_1 ON ((((t1_1.loan_account_id)::text = (t2_1.id)::text) AND ((t2_1.state)::text = 'CLOSED'::text))))
        ), early_settlement_dates AS (
         SELECT loan_account_payment.loan_account_id,
            (max(loan_account_payment.booked_at) AT TIME ZONE 'Africa/Cairo'::text) AS early_settled_at
           FROM loan_management.loan_account_payment
          GROUP BY loan_account_payment.loan_account_id
        ), reschedule_dates AS (
         SELECT loan_account_reschedule_logs.loan_account_id,
            (max(loan_account_reschedule_logs.rescheduled_at) AT TIME ZONE 'Africa/Cairo'::text) AS loan_rescheduled_at
           FROM loan_management.loan_account_reschedule_logs
          GROUP BY loan_account_reschedule_logs.loan_account_id
        ), all_loans_t1 AS (
         SELECT DISTINCT la.id AS loan_id,
            la.borrower_id AS consumer_id,
            (la.booked_at AT TIME ZONE 'Africa/Cairo'::text) AS loan_booked_at,
            ((la.booked_at AT TIME ZONE 'Africa/Cairo'::text))::date AS loan_booked_date,
                CASE
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'NOT_AVAILABLE'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'RESCHEDULED'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'EARLY_SETTLEMENT_REQUESTED'::text)) THEN 'EARLY_SETTLED'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'RESCHEDULED_POSTPONED'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'POSTPONED'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'PARTIAL_REFUND_REQUESTED'::text)) THEN 'PARTIAL_REFUND'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'WITHDRAWN'::text)) THEN 'CANCELLED'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'EARLY_SETTLED'::text)) THEN 'EARLY_SETTLED'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'SETTLED'::text)) THEN 'CLOSED'::text
                    ELSE 'UNKNOWN'::text
                END AS loan_current_status,
                CASE
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = ANY (ARRAY[('POSTPONED'::character varying)::text, ('RESCHEDULED_POSTPONED'::character varying)::text]))) THEN true
                    ELSE false
                END AS is_postponed,
                CASE
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = ANY (ARRAY[('RESCHEDULED'::character varying)::text, ('RESCHEDULED_POSTPONED'::character varying)::text]))) THEN true
                    ELSE false
                END AS is_rescheduled,
            ref_batches.batch_status AS loan_batch_status,
                CASE
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'WITHDRAWN'::text)) THEN (la.updated_at AT TIME ZONE 'Africa/Cairo'::text)
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'PARTIAL_REFUND_REQUESTED'::text)) THEN (la.updated_at AT TIME ZONE 'Africa/Cairo'::text)
                    ELSE NULL::timestamp without time zone
                END AS loan_cancelled_at,
                CASE
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'EARLY_SETTLEMENT_REQUESTED'::text)) THEN esd.early_settled_at
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'EARLY_SETTLED'::text)) THEN esd.early_settled_at
                    ELSE NULL::timestamp without time zone
                END AS loan_early_settled_at,
            rd.loan_rescheduled_at,
            la.parent_loan_account_id,
            ((max(
                CASE
                    WHEN ((active.loan_status = 'ACTIVE'::text) AND (active.rn_asc = 1)) THEN active.loan_balance_units
                    WHEN ((closed.loan_status = 'CANCELED'::text) AND (closed.rn_asc = 1)) THEN closed.loan_balance_units
                    ELSE NULL::bigint
                END))::numeric / 100.0) AS total_principal_amount,
            ((max(
                CASE
                    WHEN (active.loan_status = 'ACTIVE'::text) THEN active.cumulative_interest_units
                    WHEN (closed.loan_status = 'CANCELED'::text) THEN closed.cumulative_interest_units
                    ELSE NULL::bigint
                END))::numeric / 100.0) AS total_interest_amount,
            (sum(
                CASE
                    WHEN ((active.loan_status = 'ACTIVE'::text) AND (active.canceled IS FALSE)) THEN active.total_due_units
                    WHEN ((closed.loan_status = 'CANCELED'::text) AND ((closed.canceled_reason)::text IS DISTINCT FROM 'EARLY_SETTLEMENT_REQUESTED'::text)) THEN closed.total_due_units
                    ELSE NULL::bigint
                END) / 100.0) AS total_due_amount,
            (sum(
                CASE
                    WHEN (active.loan_status = 'ACTIVE'::text) THEN active.principal_paid_units
                    WHEN (closed.loan_status = 'CANCELED'::text) THEN closed.principal_paid_units
                    ELSE NULL::bigint
                END) / 100.0) AS total_principal_paid_amount,
            (sum(
                CASE
                    WHEN (active.loan_status = 'ACTIVE'::text) THEN active.interest_paid_units
                    WHEN (closed.loan_status = 'CANCELED'::text) THEN closed.interest_paid_units
                    ELSE NULL::bigint
                END) / 100.0) AS total_interest_paid_amount,
            (sum(
                CASE
                    WHEN (active.loan_status = 'ACTIVE'::text) THEN active.total_paid_units
                    WHEN (closed.loan_status = 'CANCELED'::text) THEN closed.total_paid_units
                    ELSE NULL::bigint
                END) / 100.0) AS total_paid_amount,
            (sum(
                CASE
                    WHEN (active.loan_status = 'ACTIVE'::text) THEN active.penalty_due_units
                    WHEN (closed.loan_status = 'CANCELED'::text) THEN closed.penalty_due_units
                    ELSE NULL::bigint
                END) / 100.0) AS total_late_fee,
            (sum(
                CASE
                    WHEN (active.loan_status = 'ACTIVE'::text) THEN active.penalty_paid_units
                    WHEN (closed.loan_status = 'CLOSED'::text) THEN closed.penalty_paid_units
                    ELSE NULL::bigint
                END) / 100.0) AS total_paid_late_fee,
            (COALESCE(mode() WITHIN GROUP (ORDER BY
                CASE
                    WHEN (active.loan_status = 'ACTIVE'::text) THEN active.loan_installment_amount
                    WHEN (closed.loan_status = 'CANCELED'::text) THEN closed.loan_installment_amount
                    ELSE NULL::numeric
                END) FILTER (WHERE ((COALESCE(active.installment_due_date, closed.installment_due_date))::date >= COALESCE((rd.loan_rescheduled_at)::date, '-infinity'::date))), mode() WITHIN GROUP (ORDER BY
                CASE
                    WHEN (active.loan_status = 'ACTIVE'::text) THEN active.loan_installment_amount
                    WHEN (closed.loan_status = 'CANCELED'::text) THEN closed.loan_installment_amount
                    ELSE NULL::numeric
                END)) / 100.0) AS loan_installment_amount,
            lamli.down_payment_amount,
            lamli.loan_admin_fee_amount,
            lamli.vat_amount,
                CASE
                    WHEN ((la.sub_state)::text = ANY (ARRAY[('EARLY_SETTLEMENT_REQUESTED'::character varying)::text, ('EARLY_SETTLED'::character varying)::text])) THEN (la.tenor_days / 30)
                    ELSE (count(*) FILTER (WHERE (COALESCE(active.total_paid_units, closed.total_paid_units) <> 0)))::integer
                END AS num_of_paid_installments,
            count(active.total_paid_units) FILTER (WHERE ((active.total_paid_units = 0) AND (active.canceled IS FALSE))) AS num_of_remaining_installments,
            sum(((active.total_due_units)::numeric / 100.0)) FILTER (WHERE ((active.total_paid_units = 0) AND (active.canceled IS FALSE))) AS total_remaining_amount_with_interest,
            sum(((active.principal_due_units)::numeric / 100.0)) FILTER (WHERE ((active.total_paid_units = 0) AND (active.canceled IS FALSE))) AS total_remaining_amount_without_interest,
            (sum(
                CASE
                    WHEN ((active.loan_status = 'ACTIVE'::text) AND (active.total_paid_units = 0)) THEN (active.interest_due_units)::numeric
                    WHEN ((closed.loan_status = 'CANCELED'::text) AND (closed.canceled IS TRUE) AND ((closed.canceled_reason)::text = 'EARLY_SETTLEMENT_REQUESTED'::text) AND (closed.total_paid_units = 0)) THEN (closed.interest_due_units)::numeric
                    ELSE (0)::numeric
                END) / 100.0) AS potential_interest_loss_if_early_settlement,
            la.financial_product_id,
            "left"((la.financial_product_id)::text, ((length((la.financial_product_id)::text) - length(split_part((la.financial_product_id)::text, '-'::text, '-1'::integer))) - 1)) AS linked_fp_key,
            reverse(split_part(reverse((la.financial_product_id)::text), '-'::text, 1)) AS linked_fp_version,
            (la.tenor_days / 30) AS tenor,
            ((la.fr_basis_points)::numeric / (100)::numeric) AS tenor_interest_percent,
            round(((((la.fr_basis_points)::numeric / (100)::numeric) / ((la.tenor_days / 30))::numeric) * (12)::numeric), 2) AS annual_interest_percent,
                CASE
                    WHEN (round(((((la.fr_basis_points)::numeric / (100)::numeric) / ((la.tenor_days / 30))::numeric) * (12)::numeric), 2) = 0.00) THEN false
                    ELSE true
                END AS is_profit_bearing,
            row_number() OVER (PARTITION BY la.borrower_id ORDER BY la.booked_at) AS consumer_loan_sequence_number,
            row_number() OVER (PARTITION BY la.merchant_id ORDER BY la.booked_at) AS merchant_loan_sequence_number,
            la.tenor_days,
            la.grace_period_in_days,
            la.borrower_repayment_day_of_month,
                CASE
                    WHEN (count(active.total_paid_units) FILTER (WHERE ((active.total_paid_units = 0) AND (active.canceled IS FALSE))) = 0) THEN NULL::date
                    ELSE min((active.installment_due_date)::date) FILTER (WHERE ((active.total_paid_units = 0) AND (active.canceled IS FALSE)))
                END AS next_due_date,
            max(((lap.booked_at AT TIME ZONE 'Africa/Cairo'::text))::date) AS last_paid_date
           FROM (((((((loan_management.loan_account la
             LEFT JOIN active ON (((la.id)::text = (active.loan_account_id)::text)))
             LEFT JOIN closed ON (((la.id)::text = (closed.loan_account_id)::text)))
             LEFT JOIN ( SELECT ref_securitizations_offloading_batches.loan_id,
                    string_agg(ref_securitizations_offloading_batches.batch_status, ', '::text ORDER BY ref_securitizations_offloading_batches.batch_status) AS batch_status
                   FROM public.ref_securitizations_offloading_batches
                  GROUP BY ref_securitizations_offloading_batches.loan_id) ref_batches ON (((la.id)::uuid = ref_batches.loan_id)))
             LEFT JOIN ( SELECT loan_account_monetary_line_item.loan_account_id,
                    (sum(loan_account_monetary_line_item.amount_units) FILTER (WHERE ((loan_account_monetary_line_item.type)::text = 'DOWN_PAYMENT'::text)) / 100.0) AS down_payment_amount,
                    (sum(loan_account_monetary_line_item.amount_units) FILTER (WHERE ((loan_account_monetary_line_item.type)::text = 'ADMIN_FEE'::text)) / 100.0) AS loan_admin_fee_amount,
                    (sum(loan_account_monetary_line_item.amount_units) FILTER (WHERE ((loan_account_monetary_line_item.type)::text = 'VAT'::text)) / 100.0) AS vat_amount
                   FROM loan_management.loan_account_monetary_line_item
                  GROUP BY loan_account_monetary_line_item.loan_account_id) lamli ON (((la.id)::text = (lamli.loan_account_id)::text)))
             LEFT JOIN loan_management.loan_account_payment lap ON ((((lap.loan_account_id)::text = (la.id)::text) AND (lap.ammortisation_line_item_sequence = active.line_item_sequence))))
             LEFT JOIN early_settlement_dates esd ON (((la.id)::text = (esd.loan_account_id)::text)))
             LEFT JOIN reschedule_dates rd ON (((la.id)::text = (rd.loan_account_id)::text)))
          GROUP BY la.id, la.borrower_id, la.booked_at, la.state, la.sub_state, ref_batches.batch_status, la.updated_at, la.parent_loan_account_id, lamli.down_payment_amount, lamli.loan_admin_fee_amount, lamli.vat_amount, la.grace_period_in_days, la.borrower_repayment_day_of_month, la.merchant_id, la.financial_product_id, la.tenor_days, la.fr_basis_points, esd.early_settled_at, rd.loan_rescheduled_at
        ), all_loans_t2 AS (
         SELECT la.id AS loan_id,
            cb.transaction_id,
                CASE
                    WHEN ((cbla2.action)::text = 'LOAN_ACTIVATED'::text) THEN ((cb.gross_basket_value)::numeric / (100)::numeric)
                    ELSE ((cbla2.loan_amount)::numeric / (100)::numeric)
                END AS basket_value,
            COALESCE(cbla.checkout_basket_id, cbla2.checkout_basket_id) AS checkout_basket_id,
            cb.financial_product_id AS financial_product_id_cb,
            cb.category AS retail_category,
                CASE
                    WHEN (((cb.origination_channel)::text = 'web'::text) OR (cb.origination_channel IS NULL) OR ((cb.origination_channel)::text = ''::text)) THEN 'physical'::character varying
                    ELSE cb.origination_channel
                END AS checkout_channel,
            la.merchant_id,
            p.name_en AS merchant_name,
            (p.created_at AT TIME ZONE 'Africa/Cairo'::text) AS merchant_created_at_utc,
            p.id AS transacted_merchant_brand_id,
            pb.id AS transacted_merchant_branch_id,
            ca.id AS merchant_city_id,
            COALESCE(NULLIF((ca."city name_en")::text, ''::text), 'Asyut'::text) AS merchant_city,
            COALESCE(NULLIF((ca."governorate name_en")::text, ''::text), 'Asyut'::text) AS transacted_merchant_branch_governorate,
            COALESCE(NULLIF((ca."cities adjusted")::text, ''::text), 'Asyut'::text) AS merchant_city_adjusted,
            COALESCE(NULLIF((ca.regions)::text, ''::text), 'Upper Egypt'::text) AS merchant_region,
                CASE
                    WHEN ((la.merchant_id)::text = '09bebad1-8352-4e77-938e-eed5b16fcdf3'::text) THEN 'BTECH'::text
                    ELSE 'NON_BTECH'::text
                END AS merchant_type
           FROM ((((((loan_management.loan_account la
             LEFT JOIN public.checkout_basket_loan_action cbla ON ((((cbla.loan_id)::text = (la.parent_loan_account_id)::text) AND ((cbla.action)::text <> 'REFUND'::text))))
             JOIN ( SELECT DISTINCT ON (checkout_basket_loan_action.loan_id) checkout_basket_loan_action.loan_id,
                    checkout_basket_loan_action.checkout_basket_id,
                    checkout_basket_loan_action.action,
                    checkout_basket_loan_action.loan_amount
                   FROM public.checkout_basket_loan_action
                  WHERE ((checkout_basket_loan_action.action)::text <> 'REFUND'::text)
                  ORDER BY checkout_basket_loan_action.loan_id, checkout_basket_loan_action.action) cbla2 ON (((cbla2.loan_id)::text = (la.id)::text)))
             JOIN public.checkout_baskets cb ON (((cb.id = cbla.checkout_basket_id) OR (cb.id = cbla2.checkout_basket_id))))
             LEFT JOIN public.partner_brand p ON (((cb.partner_id = p.partner_id) AND (cb.brand_id = p.id))))
             LEFT JOIN public.brand_branch pb ON ((cb.branch_id = pb.id)))
             LEFT JOIN public.cities_adjusted_full ca ON ((ca.id = pb.city_id)))
        )
 SELECT t1.loan_id,
    t2.transaction_id,
    t1.consumer_id,
    t1.loan_booked_at,
    t1.loan_booked_date,
    t1.loan_current_status,
    t1.is_postponed,
    t1.is_rescheduled,
    t1.loan_batch_status,
    t1.loan_cancelled_at,
    t1.loan_early_settled_at,
    t1.loan_rescheduled_at,
    t1.parent_loan_account_id,
    t2.basket_value,
    t1.total_principal_amount,
    t1.loan_installment_amount,
    t1.down_payment_amount,
    t1.loan_admin_fee_amount,
    t1.vat_amount,
    t1.total_interest_amount,
    t1.total_late_fee,
    t1.total_paid_late_fee,
    t1.total_due_amount,
    t1.total_paid_amount,
    t1.total_principal_paid_amount,
    t1.total_interest_paid_amount,
    t1.num_of_paid_installments,
    t1.num_of_remaining_installments,
    t1.total_remaining_amount_with_interest,
    t1.total_remaining_amount_without_interest,
    t1.potential_interest_loss_if_early_settlement,
    t1.financial_product_id,
    t2.financial_product_id_cb,
    t1.linked_fp_key,
    t1.linked_fp_version,
    t1.tenor,
    t3.new_tenor,
    t1.tenor_interest_percent,
    t1.annual_interest_percent,
    t1.is_profit_bearing,
    t2.retail_category,
    t2.checkout_channel,
    t2.merchant_id,
    t2.merchant_name,
    t2.merchant_created_at_utc,
    t2.transacted_merchant_brand_id,
    t2.transacted_merchant_branch_id,
    t2.merchant_city_id,
    t2.merchant_city,
    t2.transacted_merchant_branch_governorate,
    t2.merchant_city_adjusted,
    t2.merchant_region,
    t2.merchant_type,
    t1.consumer_loan_sequence_number,
    t1.merchant_loan_sequence_number,
    t1.tenor_days,
    t1.grace_period_in_days,
    t1.borrower_repayment_day_of_month,
    (now() AT TIME ZONE 'Africa/Cairo'::text) AS view_last_refreshed_time,
    t1.next_due_date,
    t1.last_paid_date
   FROM ((all_loans_t1 t1
     JOIN all_loans_t2 t2 ON (((t1.loan_id)::text = (t2.loan_id)::text)))
     JOIN new_tenor t3 ON (((t1.loan_id)::text = (t3.loan_id)::text)));


--
-- Name: v_loans_sch_info; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_loans_sch_info AS
 WITH loan_det AS (
         SELECT laa.loan_account_id,
            laa.total_paid_units,
            laa.canceled,
            la.state,
            la.sub_state
           FROM (loan_management.loan_account_ammortisation_line_item laa
             JOIN loan_management.loan_account la ON (((laa.loan_account_id)::text = (la.id)::text)))
        ), loan_agg AS (
         SELECT loan_det.loan_account_id,
            loan_det.state,
            loan_det.sub_state,
            count(*) FILTER (WHERE ((loan_det.total_paid_units = 0) AND (loan_det.canceled = false))) AS num_of_remaining_installments
           FROM loan_det
          GROUP BY loan_det.loan_account_id, loan_det.state, loan_det.sub_state
        ), postponed_loans AS (
         SELECT DISTINCT financial_requests.entity_id AS loan_id
           FROM public.financial_requests
          WHERE (((financial_requests.entity_type)::text = 'LOAN_ACCOUNT'::text) AND ((financial_requests.type)::text = 'UNADVISED_POSTPONEMENT'::text) AND ((financial_requests.status)::text = 'COMPLETED'::text))
        ), loan_sch AS (
         SELECT laali.line_item_sequence AS loan_schedule_id,
            laali.loan_account_id AS loan_id,
                CASE
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'NOT_AVAILABLE'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'RESCHEDULED'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'EARLY_SETTLEMENT_REQUESTED'::text)) THEN 'EARLY_SETTLED'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'RESCHEDULED_POSTPONED'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'POSTPONED'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'PARTIAL_REFUND_REQUESTED'::text)) THEN 'PARTIAL_REFUND'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'WITHDRAWN'::text)) THEN 'CANCELLED'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'EARLY_SETTLED'::text)) THEN 'EARLY_SETTLED'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'SETTLED'::text)) THEN 'CLOSED'::text
                    ELSE 'UNKNOWN'::text
                END AS loan_current_status,
            la.borrower_id AS consumer_id,
                CASE
                    WHEN ((pl.loan_id IS NOT NULL) AND (laali.parent_schedule_number IS NOT NULL)) THEN ((parent_laali.installment_due_date AT TIME ZONE 'Africa/Cairo'::text))::date
                    ELSE ((laali.installment_due_date AT TIME ZONE 'Africa/Cairo'::text))::date
                END AS due_date,
            ((laali.installment_due_date AT TIME ZONE 'Africa/Cairo'::text))::date AS fin_due_date,
            ((laali.grace_period_ends_at AT TIME ZONE 'Africa/Cairo'::text))::date AS grace_period_ends_on,
            sum(((laali.principal_due_units)::numeric / 100.0)) OVER (PARTITION BY laali.loan_account_id) AS total_financed_amount,
            ((laali.principal_due_units)::numeric / 100.0) AS due_principal,
            ((laali.interest_due_units)::numeric / 100.0) AS due_interest,
            sum(((laali.principal_due_units)::numeric / 100.0)) OVER (PARTITION BY laali.loan_account_id ORDER BY (((laali.installment_due_date AT TIME ZONE 'Africa/Cairo'::text))::date)) AS cumulative_principal,
            ((laali.cumulative_interest_units)::numeric / 100.0) AS cumulative_interest,
            ((laali.loan_balance_units)::numeric / 100.0) AS remaining_balance,
            (((((laali.interest_due_units)::numeric / 100.0) / NULLIF((laali.loan_balance_units)::numeric, (0)::numeric)))::double precision * (12)::double precision) AS reducing_apr,
            (lap.booked_at AT TIME ZONE 'Africa/Cairo'::text) AS paid_at,
            ((lap.booked_at AT TIME ZONE 'Africa/Cairo'::text))::date AS paid_date,
            ((laali.principal_paid_units)::numeric / 100.0) AS paid_principal,
            ((laali.interest_paid_units)::numeric / 100.0) AS paid_interest,
            ((laali.vat_paid_units)::numeric / 100.0) AS paid_vat,
            ((laali.admin_fee_paid_units)::numeric / 100.0) AS paid_admin_fee,
            ((laali.penalty_paid_units)::numeric / 100.0) AS paid_penalty,
            ((laali.total_paid_units)::numeric / 100.0) AS paid_total,
            ((laali.penalty_due_units)::numeric / (100)::numeric) AS late_fee,
            ((laali.penalty_paid_units)::numeric / (100)::numeric) AS paid_late_payment_fee,
            now() AS view_last_refreshed_time
           FROM (((((loan_management.loan_account_ammortisation_line_item laali
             JOIN loan_management.loan_account la ON (((laali.loan_account_id)::text = (la.id)::text)))
             LEFT JOIN loan_management.loan_account_payment lap ON ((((laali.loan_account_id)::text = (lap.loan_account_id)::text) AND (lap.ammortisation_line_item_sequence = laali.line_item_sequence))))
             LEFT JOIN loan_agg lg ON (((lg.loan_account_id)::text = (la.id)::text)))
             LEFT JOIN loan_management.loan_account_ammortisation_line_item parent_laali ON ((((parent_laali.loan_account_id)::text = (laali.loan_account_id)::text) AND (parent_laali.line_item_sequence = laali.parent_schedule_number))))
             LEFT JOIN postponed_loans pl ON (((pl.loan_id)::text = (la.id)::text)))
          WHERE (laali.canceled IS FALSE)
        )
 SELECT loan_schedule_id,
    loan_id,
    loan_current_status,
    consumer_id,
    due_date,
    fin_due_date,
    grace_period_ends_on,
    total_financed_amount,
    due_principal,
    due_interest,
    cumulative_principal,
    cumulative_interest,
    remaining_balance,
    reducing_apr,
    paid_at,
    paid_date,
    paid_principal,
    paid_interest,
    (paid_principal + paid_interest) AS total_installment,
    paid_vat,
    paid_admin_fee,
    paid_penalty,
    paid_total,
    late_fee,
    paid_late_payment_fee,
    view_last_refreshed_time
   FROM loan_sch;


--
-- Name: areas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.areas (
    id integer NOT NULL,
    mc_id integer,
    name_ar character varying(255) NOT NULL,
    name_en character varying(255) NOT NULL,
    city_id integer NOT NULL,
    governorate_id integer NOT NULL,
    created_at timestamp(6) without time zone NOT NULL,
    updated_at timestamp(6) without time zone NOT NULL,
    blocked boolean
);


--
-- Name: v_merchant_branch; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_merchant_branch AS
 WITH loan_data AS (
         SELECT la.id AS loan_id,
            la.merchant_id AS partner_id,
            cb.brand_id AS partner_brand_id,
            cb.branch_id AS partner_branch_id,
            la.borrower_id AS consumer_id,
            (la.booked_at)::date AS loan_booked_date,
            (la.tenor_days / 30) AS tenor,
                CASE
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'NOT_AVAILABLE'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'RESCHEDULED'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'EARLY_SETTLEMENT_REQUESTED'::text)) THEN 'EARLY_SETTLED'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'RESCHEDULED_POSTPONED'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'POSTPONED'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'PARTIAL_REFUND_REQUESTED'::text)) THEN 'PARTIAL_REFUND'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'WITHDRAWN'::text)) THEN 'CANCELLED'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'EARLY_SETTLED'::text)) THEN 'EARLY_SETTLED'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'SETTLED'::text)) THEN 'CLOSED'::text
                    ELSE 'UNKNOWN'::text
                END AS loan_current_status
           FROM ((loan_management.loan_account la
             LEFT JOIN public.checkout_basket_loan_action cbla ON ((cbla.loan_id = (la.id)::uuid)))
             LEFT JOIN public.checkout_baskets cb ON ((cb.id = cbla.checkout_basket_id)))
        ), monetary_amounts AS (
         SELECT lamli.loan_account_id AS loan_id,
            (sum(
                CASE
                    WHEN ((lamli.type)::text = 'DOWN_PAYMENT'::text) THEN lamli.amount_units
                    ELSE (0)::bigint
                END) / 100.0) AS down_payment_amount,
            (sum(
                CASE
                    WHEN ((lamli.type)::text = 'ADMIN_FEE'::text) THEN lamli.amount_units
                    ELSE (0)::bigint
                END) / 100.0) AS admin_fee_amount,
            (sum(
                CASE
                    WHEN ((lamli.type)::text = 'VAT'::text) THEN lamli.amount_units
                    ELSE (0)::bigint
                END) / 100.0) AS vat_amount
           FROM loan_management.loan_account_monetary_line_item lamli
          GROUP BY lamli.loan_account_id
        ), amortization_agg AS (
         SELECT ali.loan_account_id AS loan_id,
            (sum(
                CASE
                    WHEN (ali.canceled_at IS NULL) THEN ali.principal_due_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_principal_due_amount,
            (sum(
                CASE
                    WHEN (((ali.installment_due_date)::date <= CURRENT_DATE) AND (ali.canceled_at IS NULL)) THEN ali.principal_due_units
                    ELSE (0)::bigint
                END) / 100.0) AS principal_due_to_date,
            (sum(
                CASE
                    WHEN (ali.canceled_at IS NULL) THEN ali.principal_paid_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_principal_paid_amount,
            (sum(
                CASE
                    WHEN (ali.canceled_at IS NULL) THEN ali.total_due_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_due_amount,
            (sum(
                CASE
                    WHEN (((ali.installment_due_date)::date <= CURRENT_DATE) AND (ali.canceled_at IS NULL)) THEN ali.total_due_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_due_to_date,
            (sum(
                CASE
                    WHEN (ali.canceled_at IS NULL) THEN ali.total_paid_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_paid_amount,
            (sum(
                CASE
                    WHEN (((ali.installment_due_date)::date <= CURRENT_DATE) AND (ali.canceled_at IS NULL)) THEN ali.total_paid_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_collected_to_date,
            (sum(
                CASE
                    WHEN (((ali.installment_due_date)::date <= CURRENT_DATE) AND (ali.canceled_at IS NULL)) THEN ali.principal_paid_units
                    ELSE (0)::bigint
                END) / 100.0) AS principal_collected_to_date,
            (sum(
                CASE
                    WHEN (ali.canceled_at IS NULL) THEN ali.interest_due_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_interest_due_amount,
            (sum(
                CASE
                    WHEN (ali.canceled_at IS NULL) THEN ali.interest_paid_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_interest_paid_amount,
            (sum(
                CASE
                    WHEN (((ali.installment_due_date)::date <= CURRENT_DATE) AND (ali.canceled_at IS NULL)) THEN ali.interest_due_units
                    ELSE (0)::bigint
                END) / 100.0) AS interest_due_to_date,
            (sum(
                CASE
                    WHEN (((ali.installment_due_date)::date <= CURRENT_DATE) AND (ali.canceled_at IS NULL)) THEN ali.interest_paid_units
                    ELSE (0)::bigint
                END) / 100.0) AS interest_collected_to_date,
            count(
                CASE
                    WHEN ((ali.canceled_at IS NULL) AND (ali.total_paid_units > 0)) THEN 1
                    ELSE NULL::integer
                END) AS paid_installments,
            count(
                CASE
                    WHEN ((ali.total_paid_units = 0) AND (ali.canceled_at IS NULL)) THEN 1
                    ELSE NULL::integer
                END) AS remaining_installments,
            count(
                CASE
                    WHEN ((ali.total_paid_units = 0) AND (ali.canceled_at IS NULL) AND (((ali.installment_due_date)::date >= (CURRENT_DATE - '30 days'::interval)) AND ((ali.installment_due_date)::date <= CURRENT_DATE))) THEN 1
                    ELSE NULL::integer
                END) AS unpaid_last_30_days,
            count(
                CASE
                    WHEN ((ali.total_paid_units = 0) AND (ali.canceled_at IS NULL) AND (((ali.installment_due_date)::date >= (CURRENT_DATE - '60 days'::interval)) AND ((ali.installment_due_date)::date <= (CURRENT_DATE - '31 days'::interval)))) THEN 1
                    ELSE NULL::integer
                END) AS unpaid_31_60_days,
            count(
                CASE
                    WHEN ((ali.total_paid_units = 0) AND (ali.canceled_at IS NULL) AND (((ali.installment_due_date)::date >= (CURRENT_DATE - '90 days'::interval)) AND ((ali.installment_due_date)::date <= (CURRENT_DATE - '61 days'::interval)))) THEN 1
                    ELSE NULL::integer
                END) AS unpaid_61_90_days,
            count(
                CASE
                    WHEN ((ali.total_paid_units = 0) AND (ali.canceled_at IS NULL) AND ((ali.installment_due_date)::date < (CURRENT_DATE - '90 days'::interval))) THEN 1
                    ELSE NULL::integer
                END) AS unpaid_90_plus_days
           FROM loan_management.loan_account_ammortisation_line_item ali
          GROUP BY ali.loan_account_id
        ), consumers_data AS (
         SELECT loan_data.partner_id,
            loan_data.partner_brand_id,
            loan_data.partner_branch_id,
            loan_data.consumer_id,
            count(DISTINCT loan_data.loan_id) AS loans_per_consumer
           FROM loan_data
          GROUP BY loan_data.partner_id, loan_data.partner_brand_id, loan_data.partner_branch_id, loan_data.consumer_id
        ), repeat_consumers AS (
         SELECT consumers_data.partner_id,
            consumers_data.partner_brand_id,
            consumers_data.partner_branch_id,
            count(DISTINCT consumers_data.consumer_id) AS repeated_consumers
           FROM consumers_data
          WHERE (consumers_data.loans_per_consumer > 1)
          GROUP BY consumers_data.partner_id, consumers_data.partner_brand_id, consumers_data.partner_branch_id
        ), all_checkouts AS (
         SELECT checkout_baskets.partner_id,
            checkout_baskets.brand_id AS partner_brand_id,
            checkout_baskets.branch_id AS partner_branch_id,
            count(DISTINCT checkout_baskets.id) AS total_checkouts,
            count(DISTINCT
                CASE
                    WHEN ((checkout_baskets.status)::text = 'LOAN_ACTIVATED'::text) THEN checkout_baskets.id
                    ELSE NULL::uuid
                END) AS successful_checkouts
           FROM public.checkout_baskets
          GROUP BY checkout_baskets.partner_id, checkout_baskets.brand_id, checkout_baskets.branch_id
        ), merchant_disbursement AS (
         SELECT pb.partner_id,
            pb.brand_id AS partner_brand_id,
            pb.id AS partner_branch_id,
            count(DISTINCT lb.loan_id) AS total_loans,
            count(DISTINCT lb.consumer_id) AS total_consumers,
            max(ac.total_checkouts) AS total_checkouts,
            max(ac.successful_checkouts) AS successful_checkouts,
            round(sum(am.total_due_amount), 2) AS total_due_amount,
            round(sum(am.total_paid_amount), 2) AS total_due_paid_amount,
            round(sum(am.total_due_to_date), 2) AS total_due_to_date,
            round(sum(am.total_collected_to_date), 2) AS total_due_paid_to_date,
            round(sum(am.total_principal_due_amount), 2) AS total_principal_amount,
            round(sum(am.total_principal_paid_amount), 2) AS total_principal_paid_amount,
            round(sum(am.principal_due_to_date), 2) AS total_principal_to_date,
            round(sum(am.principal_collected_to_date), 2) AS total_principal_paid_to_date,
            round(sum(am.total_interest_due_amount), 2) AS total_interest_amount,
            round(sum(am.total_interest_paid_amount), 2) AS total_interest_paid_amount,
            round(sum(am.interest_due_to_date), 2) AS total_interest_to_date,
            round(sum(am.interest_collected_to_date), 2) AS total_interest_paid_to_date,
            round(sum(ma.down_payment_amount), 2) AS total_down_payment_amount,
            round(sum(ma.admin_fee_amount), 2) AS total_admin_fee_amount,
            round(avg(am.total_principal_due_amount), 2) AS avg_financed_amount,
            round(max(am.total_principal_due_amount), 2) AS max_financed_amount,
            round(avg(lb.tenor), 2) AS avg_tenor,
            sum(am.paid_installments) AS total_paid_installments,
            sum(am.remaining_installments) AS total_remaining_installments,
            count(DISTINCT
                CASE
                    WHEN (lb.loan_current_status = 'CLOSED'::text) THEN lb.loan_id
                    ELSE NULL::character varying
                END) AS closed_loans,
            count(DISTINCT
                CASE
                    WHEN (lb.loan_current_status = 'RUNNING'::text) THEN lb.loan_id
                    ELSE NULL::character varying
                END) AS running_loans,
            count(DISTINCT
                CASE
                    WHEN (lb.loan_current_status = 'EARLY_SETTLED'::text) THEN lb.loan_id
                    ELSE NULL::character varying
                END) AS early_settled_loans,
            count(DISTINCT
                CASE
                    WHEN (lb.loan_current_status = 'CANCELLED'::text) THEN lb.loan_id
                    ELSE NULL::character varying
                END) AS cancelled_loans,
            count(DISTINCT
                CASE
                    WHEN (lb.loan_current_status = 'PARTIAL_REFUND'::text) THEN lb.loan_id
                    ELSE NULL::character varying
                END) AS partial_refund_loans,
            min(lb.loan_booked_date) AS first_loan_date,
            max(lb.loan_booked_date) AS last_loan_date,
            sum(am.unpaid_last_30_days) AS unpaid_installments_last_30_days,
            sum(am.unpaid_31_60_days) AS unpaid_installments_31_60_days,
            sum(am.unpaid_61_90_days) AS unpaid_installments_61_90_days,
            sum(am.unpaid_90_plus_days) AS unpaid_installments_90_plus_days
           FROM ((((public.brand_branch pb
             LEFT JOIN loan_data lb ON (((pb.partner_id = (lb.partner_id)::uuid) AND (pb.brand_id = lb.partner_brand_id) AND (pb.id = lb.partner_branch_id))))
             LEFT JOIN monetary_amounts ma ON (((lb.loan_id)::text = (ma.loan_id)::text)))
             LEFT JOIN amortization_agg am ON (((lb.loan_id)::text = (am.loan_id)::text)))
             LEFT JOIN all_checkouts ac ON (((pb.partner_id = ac.partner_id) AND (pb.brand_id = ac.partner_brand_id) AND (pb.id = ac.partner_branch_id))))
          GROUP BY pb.partner_id, pb.brand_id, pb.id
        ), merchant_base AS (
         SELECT bb.brand_id AS partner_brand_id,
            bb.partner_id,
            bb.id AS partner_branch_id,
            bb.name AS branch_name,
            c."governorate name_en" AS governorate,
            c."city name_en" AS city,
            a.name_en AS area,
            bb.street AS street_name,
            p_1.name_en AS brand_name,
            (bb.created_at AT TIME ZONE 'Africa/Cairo'::text) AS created_at,
            (bb.updated_at AT TIME ZONE 'Africa/Cairo'::text) AS updated_at,
            bb.status,
            bb.branch_type AS channel,
            TRIM(BOTH FROM lower((p_1.category)::text)) AS category
           FROM (((public.partner_brand p_1
             LEFT JOIN public.brand_branch bb ON (((p_1.partner_id = bb.partner_id) AND (p_1.id = bb.brand_id))))
             LEFT JOIN public.cities_adjusted_full c ON ((bb.city_id = c.id)))
             LEFT JOIN public.areas a ON ((bb.area_id = a.id)))
        )
 SELECT md.partner_id,
    md.partner_brand_id,
    md.partner_branch_id,
    p.created_at,
    p.updated_at,
    p.status,
    p.governorate,
    p.city,
    p.area,
    p.brand_name,
    p.branch_name,
    p.category,
    p.channel,
    md.first_loan_date,
    md.last_loan_date,
    md.total_loans,
    md.running_loans,
    md.closed_loans,
    md.early_settled_loans,
    md.cancelled_loans,
    md.partial_refund_loans,
    md.total_consumers,
    COALESCE(rb.repeated_consumers, (0)::bigint) AS repeat_consumers,
    round((COALESCE((rb.repeated_consumers)::numeric, (0)::numeric) / NULLIF((md.total_consumers)::numeric, (0)::numeric)), 2) AS repeat_consumer_rate_percent,
    md.total_paid_installments,
    md.total_remaining_installments,
    md.total_due_amount,
    md.total_due_paid_amount,
    round((md.total_due_paid_amount / NULLIF(md.total_due_amount, (0)::numeric)), 2) AS overall_collection_rate,
    md.total_due_to_date,
    md.total_due_paid_to_date,
    round((md.total_due_paid_to_date / NULLIF(md.total_due_to_date, (0)::numeric)), 2) AS collection_rate_to_date,
    md.total_principal_amount,
    md.total_principal_paid_amount,
    md.total_principal_to_date,
    md.total_principal_paid_to_date,
    md.total_interest_amount,
    md.total_interest_paid_amount,
    md.total_interest_to_date,
    md.total_interest_paid_to_date,
    round((md.total_interest_amount / NULLIF(md.total_principal_amount, (0)::numeric)), 2) AS interest_to_principal_ratio_percent,
    md.total_admin_fee_amount,
    md.avg_financed_amount,
    md.max_financed_amount,
    md.avg_tenor,
        CASE
            WHEN (md.last_loan_date >= (CURRENT_DATE - '30 days'::interval)) THEN true
            ELSE false
        END AS has_new_loan_in_last_30_days,
    round(((md.successful_checkouts)::numeric / NULLIF((md.total_checkouts)::numeric, (0)::numeric)), 2) AS checkout_success_rate,
    md.unpaid_installments_last_30_days,
    md.unpaid_installments_31_60_days,
    md.unpaid_installments_61_90_days,
    md.unpaid_installments_90_plus_days,
    (now() AT TIME ZONE 'Africa/Cairo'::text) AS last_refreshed_at
   FROM ((merchant_disbursement md
     LEFT JOIN repeat_consumers rb ON (((md.partner_id = (rb.partner_id)::uuid) AND (md.partner_brand_id = rb.partner_brand_id) AND (md.partner_branch_id = rb.partner_branch_id))))
     LEFT JOIN merchant_base p ON (((md.partner_id = p.partner_id) AND (md.partner_brand_id = p.partner_brand_id) AND (md.partner_branch_id = p.partner_branch_id))));


--
-- Name: v_merchant_branch_info; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_merchant_branch_info AS
 WITH li_agg AS (
         SELECT mv_loans_sch_info.loan_id,
            sum(COALESCE(mv_loans_sch_info.due_principal, (0)::numeric)) AS due_principal,
            sum(COALESCE(mv_loans_sch_info.paid_principal, (0)::numeric)) AS paid_principal_only,
            sum(COALESCE(mv_loans_sch_info.due_interest, (0)::numeric)) AS due_interest,
            sum(COALESCE(mv_loans_sch_info.paid_interest, (0)::numeric)) AS paid_interest,
            sum(COALESCE(mv_loans_sch_info.late_fee, (0)::numeric)) AS late_fee,
            sum(COALESCE(mv_loans_sch_info.paid_total, (0)::numeric)) AS total_due_paid,
            sum((COALESCE(mv_loans_sch_info.due_principal, (0)::numeric) + COALESCE(mv_loans_sch_info.due_interest, (0)::numeric))) AS total_due_amount,
            sum(
                CASE
                    WHEN (mv_loans_sch_info.due_date <= CURRENT_DATE) THEN COALESCE(mv_loans_sch_info.due_principal, (0)::numeric)
                    ELSE (0)::numeric
                END) AS due_principal_to_date,
            sum(
                CASE
                    WHEN (mv_loans_sch_info.due_date <= CURRENT_DATE) THEN COALESCE(mv_loans_sch_info.paid_principal, (0)::numeric)
                    ELSE (0)::numeric
                END) AS paid_principal_to_date,
            sum(
                CASE
                    WHEN (mv_loans_sch_info.due_date <= CURRENT_DATE) THEN (COALESCE(mv_loans_sch_info.due_principal, (0)::numeric) + COALESCE(mv_loans_sch_info.due_interest, (0)::numeric))
                    ELSE (0)::numeric
                END) AS due_amount_to_date,
            sum(
                CASE
                    WHEN (mv_loans_sch_info.due_date <= CURRENT_DATE) THEN mv_loans_sch_info.paid_total
                    ELSE (0)::numeric
                END) AS due_paid_to_date,
            sum(
                CASE
                    WHEN (mv_loans_sch_info.due_date <= CURRENT_DATE) THEN COALESCE(mv_loans_sch_info.due_interest, (0)::numeric)
                    ELSE (0)::numeric
                END) AS interest_due_to_date,
            sum(
                CASE
                    WHEN (mv_loans_sch_info.due_date <= CURRENT_DATE) THEN COALESCE(mv_loans_sch_info.paid_interest, (0)::numeric)
                    ELSE (0)::numeric
                END) AS interest_paid_to_date,
            sum(
                CASE
                    WHEN ((COALESCE(mv_loans_sch_info.paid_total, (0)::numeric) = (0)::numeric) AND (mv_loans_sch_info.due_date >= (CURRENT_DATE - '30 days'::interval)) AND (mv_loans_sch_info.due_date <= CURRENT_DATE)) THEN 1
                    ELSE 0
                END) AS unpaid_last_30_days,
            sum(
                CASE
                    WHEN ((COALESCE(mv_loans_sch_info.paid_total, (0)::numeric) = (0)::numeric) AND (mv_loans_sch_info.due_date >= (CURRENT_DATE - '60 days'::interval)) AND (mv_loans_sch_info.due_date <= (CURRENT_DATE - '31 days'::interval))) THEN 1
                    ELSE 0
                END) AS unpaid_31_60_days,
            sum(
                CASE
                    WHEN ((COALESCE(mv_loans_sch_info.paid_total, (0)::numeric) = (0)::numeric) AND (mv_loans_sch_info.due_date >= (CURRENT_DATE - '90 days'::interval)) AND (mv_loans_sch_info.due_date <= (CURRENT_DATE - '61 days'::interval))) THEN 1
                    ELSE 0
                END) AS unpaid_61_90_days,
            sum(
                CASE
                    WHEN ((COALESCE(mv_loans_sch_info.paid_total, (0)::numeric) = (0)::numeric) AND (mv_loans_sch_info.due_date < (CURRENT_DATE - '90 days'::interval))) THEN 1
                    ELSE 0
                END) AS unpaid_90_plus_days
           FROM public.mv_loans_sch_info
          GROUP BY mv_loans_sch_info.loan_id
        ), loans_with_repeat_flag AS (
         SELECT mv_loans_info.loan_id,
            mv_loans_info.transaction_id,
            mv_loans_info.consumer_id,
            mv_loans_info.loan_booked_at,
            mv_loans_info.loan_booked_date,
            mv_loans_info.loan_current_status,
            mv_loans_info.is_postponed,
            mv_loans_info.is_rescheduled,
            mv_loans_info.loan_batch_status,
            mv_loans_info.loan_cancelled_at,
            mv_loans_info.loan_early_settled_at,
            mv_loans_info.parent_loan_account_id,
            mv_loans_info.basket_value,
            mv_loans_info.total_principal_amount,
            mv_loans_info.loan_installment_amount,
            mv_loans_info.down_payment_amount,
            mv_loans_info.loan_admin_fee_amount,
            mv_loans_info.vat_amount,
            mv_loans_info.total_interest_amount,
            mv_loans_info.total_late_fee,
            mv_loans_info.total_paid_late_fee,
            mv_loans_info.total_due_amount,
            mv_loans_info.total_paid_amount,
            mv_loans_info.total_principal_paid_amount,
            mv_loans_info.total_interest_paid_amount,
            mv_loans_info.num_of_paid_installments,
            mv_loans_info.num_of_remaining_installments,
            mv_loans_info.total_remaining_amount_with_interest,
            mv_loans_info.total_remaining_amount_without_interest,
            mv_loans_info.potential_interest_loss_if_early_settlement,
            mv_loans_info.financial_product_id,
            mv_loans_info.financial_product_id_cb,
            mv_loans_info.linked_fp_key,
            mv_loans_info.linked_fp_version,
            mv_loans_info.tenor,
            mv_loans_info.new_tenor,
            mv_loans_info.tenor_interest_percent,
            mv_loans_info.annual_interest_percent,
            mv_loans_info.is_profit_bearing,
            mv_loans_info.retail_category,
            mv_loans_info.checkout_channel,
            mv_loans_info.merchant_id,
            mv_loans_info.merchant_name,
            mv_loans_info.merchant_created_at_utc,
            mv_loans_info.transacted_merchant_brand_id,
            mv_loans_info.transacted_merchant_branch_id,
            mv_loans_info.merchant_city_id,
            mv_loans_info.merchant_city,
            mv_loans_info.transacted_merchant_branch_governorate,
            mv_loans_info.merchant_city_adjusted,
            mv_loans_info.merchant_region,
            mv_loans_info.merchant_type,
            mv_loans_info.consumer_loan_sequence_number,
            mv_loans_info.merchant_loan_sequence_number,
            mv_loans_info.tenor_days,
            mv_loans_info.grace_period_in_days,
            mv_loans_info.borrower_repayment_day_of_month,
            mv_loans_info.view_last_refreshed_time,
            mv_loans_info.next_due_date,
            mv_loans_info.last_paid_date,
            count(mv_loans_info.loan_id) OVER (PARTITION BY mv_loans_info.merchant_id, mv_loans_info.transacted_merchant_brand_id, mv_loans_info.transacted_merchant_branch_id, mv_loans_info.consumer_id) AS consumer_loan_count
           FROM public.mv_loans_info
        ), all_checkouts AS (
         SELECT checkout_baskets.partner_id,
            checkout_baskets.brand_id AS partner_brand_id,
            checkout_baskets.branch_id AS partner_branch_id,
            count(DISTINCT checkout_baskets.id) AS total_checkouts,
            count(DISTINCT
                CASE
                    WHEN ((checkout_baskets.status)::text = 'LOAN_ACTIVATED'::text) THEN checkout_baskets.id
                    ELSE NULL::uuid
                END) AS successful_checkouts
           FROM public.checkout_baskets
          GROUP BY checkout_baskets.partner_id, checkout_baskets.brand_id, checkout_baskets.branch_id
        ), merchant_base AS (
         SELECT bb.brand_id AS partner_brand_id,
            bb.partner_id,
            bb.id AS partner_branch_id,
            bb.name AS branch_name,
            a.name_en AS area,
            bb.street AS street_name,
            (bb.updated_at AT TIME ZONE 'Africa/Cairo'::text) AS updated_at,
            bb.status,
            bb.branch_type AS channel,
            TRIM(BOTH FROM lower((p.category)::text)) AS category
           FROM (((public.partner_brand p
             LEFT JOIN public.brand_branch bb ON (((p.partner_id = bb.partner_id) AND (p.id = bb.brand_id))))
             LEFT JOIN public.cities_adjusted_full c ON ((bb.city_id = c.id)))
             LEFT JOIN public.areas a ON ((bb.area_id = a.id)))
        ), merchant_data AS (
         SELECT l.merchant_id AS partner_id,
            l.transacted_merchant_brand_id AS partner_brand_id,
            l.transacted_merchant_branch_id AS partner_branch_id,
            l.merchant_name AS partner_name,
            mb.branch_name,
            mb.status,
            l.transacted_merchant_branch_governorate AS governorate,
            l.merchant_city_adjusted AS city,
            l.merchant_region,
            mb.area,
            mb.street_name,
            l.merchant_type AS partner_type,
            mb.channel,
            mb.category,
            min(l.merchant_created_at_utc) AS first_created_at,
            min(l.loan_booked_at) AS first_loan_date,
            max(l.loan_booked_at) AS last_loan_date,
                CASE
                    WHEN ((max(l.loan_booked_at) >= (CURRENT_DATE - '30 days'::interval)) AND ((mb.status)::text = 'ACTIVE'::text)) THEN true
                    ELSE false
                END AS is_active_in_last_30_days,
            count(DISTINCT l.loan_id) AS total_loans,
            count(DISTINCT
                CASE
                    WHEN (l.loan_current_status = 'RUNNING'::text) THEN l.loan_id
                    ELSE NULL::character varying
                END) AS running_loans,
            count(DISTINCT
                CASE
                    WHEN (l.loan_current_status = 'CLOSED'::text) THEN l.loan_id
                    ELSE NULL::character varying
                END) AS closed_loans,
            count(DISTINCT
                CASE
                    WHEN (l.loan_current_status = 'EARLY_SETTLED'::text) THEN l.loan_id
                    ELSE NULL::character varying
                END) AS early_settled_loans,
            count(DISTINCT
                CASE
                    WHEN (l.loan_current_status = 'PARTIAL_REFUND'::text) THEN l.loan_id
                    ELSE NULL::character varying
                END) AS partial_refund_loans,
            count(DISTINCT
                CASE
                    WHEN (l.loan_current_status = 'CANCELLED'::text) THEN l.loan_id
                    ELSE NULL::character varying
                END) AS cancelled_loans,
            count(DISTINCT l.consumer_id) AS total_consumers,
            count(DISTINCT
                CASE
                    WHEN (l.consumer_loan_count > 1) THEN l.consumer_id
                    ELSE NULL::character varying
                END) AS repeated_consumers,
            round(((count(DISTINCT
                CASE
                    WHEN (l.consumer_loan_count > 1) THEN l.consumer_id
                    ELSE NULL::character varying
                END))::numeric / (NULLIF(count(DISTINCT l.consumer_id), 0))::numeric), 2) AS repeat_consumer_rate,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN l.num_of_paid_installments
                    ELSE 0
                END) AS num_of_paid_installments,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN l.num_of_remaining_installments
                    ELSE (0)::bigint
                END) AS num_of_remaining_installments,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_amount
                    ELSE (0)::numeric
                END) AS total_due_amount,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_paid
                    ELSE (0)::numeric
                END) AS total_due_paid,
            round((sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_paid
                    ELSE (0)::numeric
                END) / NULLIF(sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_amount
                    ELSE (0)::numeric
                END), (0)::numeric)), 2) AS overall_collection_rate,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.due_amount_to_date
                    ELSE (0)::numeric
                END) AS total_due_amount_to_date,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.due_paid_to_date
                    ELSE (0)::numeric
                END) AS total_due_paid_to_date,
            round((sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_paid
                    ELSE (0)::numeric
                END) / NULLIF(sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.due_amount_to_date
                    ELSE (0)::numeric
                END), (0)::numeric)), 2) AS collection_rate_to_date,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.due_principal, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_principal_amount,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.paid_principal_only, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_paid_principal,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.due_principal_to_date
                    ELSE (0)::numeric
                END) AS total_principal_to_date,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.paid_principal_to_date
                    ELSE (0)::numeric
                END) AS total_paid_principal_to_date,
            round((sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN l.total_principal_amount
                    ELSE (0)::numeric
                END) / (NULLIF(count(DISTINCT
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN l.loan_id
                    ELSE NULL::character varying
                END), 0))::numeric), 2) AS avg_financed_amount,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.due_interest, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_interest_due,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.paid_interest, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_interest_paid,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.interest_due_to_date
                    ELSE (0)::numeric
                END) AS total_interest_due_to_date,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.interest_paid_to_date
                    ELSE (0)::numeric
                END) AS total_interest_paid_to_date,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN l.loan_admin_fee_amount
                    ELSE (0)::numeric
                END) AS loan_admin_fee_amount,
            max(l.total_principal_amount) AS max_financed_amount,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.unpaid_last_30_days
                    ELSE (0)::bigint
                END) AS unpaid_last_30_days,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.unpaid_31_60_days
                    ELSE (0)::bigint
                END) AS unpaid_31_60_days,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.unpaid_61_90_days
                    ELSE (0)::bigint
                END) AS unpaid_61_90_days,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.unpaid_90_plus_days
                    ELSE (0)::bigint
                END) AS unpaid_90_plus_days,
            max(ac.successful_checkouts) AS successful_checkouts,
            max(ac.total_checkouts) AS total_checkouts,
            round(((max(ac.successful_checkouts))::numeric / NULLIF((max(ac.total_checkouts))::numeric, (0)::numeric)), 2) AS checkout_success_rate
           FROM (((loans_with_repeat_flag l
             LEFT JOIN li_agg li ON (((l.loan_id)::text = (li.loan_id)::text)))
             LEFT JOIN merchant_base mb ON ((((l.merchant_id)::uuid = mb.partner_id) AND (l.transacted_merchant_brand_id = mb.partner_brand_id) AND (l.transacted_merchant_branch_id = mb.partner_branch_id))))
             LEFT JOIN all_checkouts ac ON ((((l.merchant_id)::uuid = ac.partner_id) AND (l.transacted_merchant_brand_id = ac.partner_brand_id) AND (l.transacted_merchant_branch_id = ac.partner_branch_id))))
          GROUP BY l.merchant_id, l.transacted_merchant_brand_id, l.transacted_merchant_branch_id, l.merchant_name, mb.branch_name, mb.status, l.transacted_merchant_branch_governorate, l.merchant_city_adjusted, l.merchant_region, mb.area, mb.street_name, l.merchant_type, mb.channel, mb.category
        )
 SELECT partner_id,
    partner_brand_id,
    partner_branch_id,
    partner_name,
    branch_name,
    status,
    governorate,
    city,
    merchant_region,
    area,
    street_name,
    partner_type,
    channel,
    category,
    first_created_at,
    first_loan_date,
    last_loan_date,
    is_active_in_last_30_days,
    total_loans,
    running_loans,
    closed_loans,
    early_settled_loans,
    partial_refund_loans,
    cancelled_loans,
    total_consumers,
    repeated_consumers,
    repeat_consumer_rate,
    num_of_paid_installments,
    num_of_remaining_installments,
    total_due_amount,
    total_due_paid,
    overall_collection_rate,
    total_due_amount_to_date,
    total_due_paid_to_date,
    collection_rate_to_date,
    total_principal_amount,
    total_paid_principal,
    total_principal_to_date,
    total_paid_principal_to_date,
    avg_financed_amount,
    total_interest_due,
    total_interest_paid,
    total_interest_due_to_date,
    total_interest_paid_to_date,
    loan_admin_fee_amount,
    max_financed_amount,
    unpaid_last_30_days,
    unpaid_31_60_days,
    unpaid_61_90_days,
    unpaid_90_plus_days,
    successful_checkouts,
    total_checkouts,
    checkout_success_rate,
    (now() AT TIME ZONE 'Africa/Cairo'::text) AS last_refreshed_at
   FROM merchant_data;


--
-- Name: v_merchant_branch_monthly; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_merchant_branch_monthly AS
 WITH li_agg AS (
         SELECT mv_loans_sch_info.loan_id,
            mv_loans_sch_info.consumer_id,
            date_trunc('month'::text, (mv_loans_sch_info.due_date)::timestamp with time zone) AS due_month,
            sum(COALESCE(mv_loans_sch_info.due_principal, (0)::numeric)) AS due_principal,
            sum(COALESCE(mv_loans_sch_info.paid_principal, (0)::numeric)) AS paid_principal_only,
            sum(COALESCE(mv_loans_sch_info.due_interest, (0)::numeric)) AS due_interest,
            sum(COALESCE(mv_loans_sch_info.paid_interest, (0)::numeric)) AS paid_interest,
            sum(COALESCE(mv_loans_sch_info.late_fee, (0)::numeric)) AS late_fee,
            sum(COALESCE(mv_loans_sch_info.paid_total, (0)::numeric)) AS total_due_paid,
            sum((COALESCE(mv_loans_sch_info.due_principal, (0)::numeric) + COALESCE(mv_loans_sch_info.due_interest, (0)::numeric))) AS total_due_amount
           FROM public.mv_loans_sch_info
          WHERE (mv_loans_sch_info.due_date <= CURRENT_DATE)
          GROUP BY mv_loans_sch_info.loan_id, mv_loans_sch_info.consumer_id, (date_trunc('month'::text, (mv_loans_sch_info.due_date)::timestamp with time zone))
        ), all_checkouts AS (
         SELECT checkout_baskets.partner_id,
            checkout_baskets.brand_id AS partner_brand_id,
            checkout_baskets.branch_id AS partner_branch_id,
            date_trunc('month'::text, checkout_baskets.created_at) AS checkout_month,
            count(DISTINCT checkout_baskets.id) AS total_checkouts,
            count(DISTINCT
                CASE
                    WHEN ((checkout_baskets.status)::text = 'LOAN_ACTIVATED'::text) THEN checkout_baskets.id
                    ELSE NULL::uuid
                END) AS successful_checkouts
           FROM public.checkout_baskets
          WHERE (checkout_baskets.created_at <= CURRENT_DATE)
          GROUP BY checkout_baskets.partner_id, checkout_baskets.brand_id, checkout_baskets.branch_id, (date_trunc('month'::text, checkout_baskets.created_at))
        ), merchant_data AS (
         SELECT l.merchant_id AS partner_id,
            l.transacted_merchant_brand_id AS partner_brand_id,
            l.transacted_merchant_branch_id AS partner_branch_id,
            li.due_month,
            l.merchant_name AS partner_name,
            l.transacted_merchant_branch_governorate AS governorate,
            l.merchant_city_adjusted AS city,
            l.merchant_region,
            l.merchant_type AS partner_type,
            count(DISTINCT li.loan_id) AS total_loans,
            count(DISTINCT li.consumer_id) AS total_consumers,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_amount
                    ELSE (0)::numeric
                END) AS total_due_amount,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_paid
                    ELSE (0)::numeric
                END) AS total_due_paid,
            round((sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_paid
                    ELSE (0)::numeric
                END) / NULLIF(sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_amount
                    ELSE (0)::numeric
                END), (0)::numeric)), 2) AS collection_rate,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.due_principal, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_principal_amount,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.paid_principal_only, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_paid_principal,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.due_interest, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_interest_due,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.paid_interest, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_interest_paid,
            max(ac.total_checkouts) AS total_checkouts,
            max(ac.successful_checkouts) AS successful_checkouts,
            round(((max(ac.successful_checkouts))::numeric / NULLIF((max(ac.total_checkouts))::numeric, (0)::numeric)), 2) AS checkout_success_rate,
            (now() AT TIME ZONE 'Africa/Cairo'::text) AS last_refreshed_at
           FROM ((public.mv_loans_info l
             JOIN li_agg li ON (((l.loan_id)::text = (li.loan_id)::text)))
             LEFT JOIN all_checkouts ac ON ((((l.merchant_id)::uuid = ac.partner_id) AND (l.transacted_merchant_brand_id = ac.partner_brand_id) AND (l.transacted_merchant_branch_id = ac.partner_branch_id) AND (li.due_month = ac.checkout_month))))
          GROUP BY l.merchant_id, l.transacted_merchant_brand_id, l.transacted_merchant_branch_id, li.due_month, l.merchant_name, l.transacted_merchant_branch_governorate, l.merchant_city_adjusted, l.merchant_region, l.merchant_type
        )
 SELECT partner_id,
    partner_brand_id,
    partner_branch_id,
    due_month,
    partner_name,
    governorate,
    city,
    merchant_region,
    partner_type,
    total_loans,
    total_consumers,
    total_due_amount,
    total_due_paid,
    collection_rate,
    total_principal_amount,
    total_paid_principal,
    total_interest_due,
    total_interest_paid,
    total_checkouts,
    successful_checkouts,
    checkout_success_rate,
    last_refreshed_at
   FROM merchant_data;


--
-- Name: v_merchant_brand_info; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_merchant_brand_info AS
 WITH li_agg AS (
         SELECT mv_loans_sch_info.loan_id,
            sum(COALESCE(mv_loans_sch_info.due_principal, (0)::numeric)) AS due_principal,
            sum(COALESCE(mv_loans_sch_info.paid_principal, (0)::numeric)) AS paid_principal_only,
            sum(COALESCE(mv_loans_sch_info.due_interest, (0)::numeric)) AS due_interest,
            sum(COALESCE(mv_loans_sch_info.paid_interest, (0)::numeric)) AS paid_interest,
            sum(COALESCE(mv_loans_sch_info.late_fee, (0)::numeric)) AS late_fee,
            sum(COALESCE(mv_loans_sch_info.paid_total, (0)::numeric)) AS total_due_paid,
            sum((COALESCE(mv_loans_sch_info.due_principal, (0)::numeric) + COALESCE(mv_loans_sch_info.due_interest, (0)::numeric))) AS total_due_amount,
            sum(
                CASE
                    WHEN (mv_loans_sch_info.due_date <= CURRENT_DATE) THEN COALESCE(mv_loans_sch_info.due_principal, (0)::numeric)
                    ELSE (0)::numeric
                END) AS due_principal_to_date,
            sum(
                CASE
                    WHEN (mv_loans_sch_info.due_date <= CURRENT_DATE) THEN COALESCE(mv_loans_sch_info.paid_principal, (0)::numeric)
                    ELSE (0)::numeric
                END) AS paid_principal_to_date,
            sum(
                CASE
                    WHEN (mv_loans_sch_info.due_date <= CURRENT_DATE) THEN (COALESCE(mv_loans_sch_info.due_principal, (0)::numeric) + COALESCE(mv_loans_sch_info.due_interest, (0)::numeric))
                    ELSE (0)::numeric
                END) AS due_amount_to_date,
            sum(
                CASE
                    WHEN (mv_loans_sch_info.due_date <= CURRENT_DATE) THEN mv_loans_sch_info.paid_total
                    ELSE (0)::numeric
                END) AS due_paid_to_date,
            sum(
                CASE
                    WHEN (mv_loans_sch_info.due_date <= CURRENT_DATE) THEN COALESCE(mv_loans_sch_info.due_interest, (0)::numeric)
                    ELSE (0)::numeric
                END) AS interest_due_to_date,
            sum(
                CASE
                    WHEN (mv_loans_sch_info.due_date <= CURRENT_DATE) THEN COALESCE(mv_loans_sch_info.paid_interest, (0)::numeric)
                    ELSE (0)::numeric
                END) AS interest_paid_to_date,
            sum(
                CASE
                    WHEN ((COALESCE(mv_loans_sch_info.paid_total, (0)::numeric) = (0)::numeric) AND (mv_loans_sch_info.due_date >= (CURRENT_DATE - '30 days'::interval)) AND (mv_loans_sch_info.due_date <= CURRENT_DATE)) THEN 1
                    ELSE 0
                END) AS unpaid_last_30_days,
            sum(
                CASE
                    WHEN ((COALESCE(mv_loans_sch_info.paid_total, (0)::numeric) = (0)::numeric) AND (mv_loans_sch_info.due_date >= (CURRENT_DATE - '60 days'::interval)) AND (mv_loans_sch_info.due_date <= (CURRENT_DATE - '31 days'::interval))) THEN 1
                    ELSE 0
                END) AS unpaid_31_60_days,
            sum(
                CASE
                    WHEN ((COALESCE(mv_loans_sch_info.paid_total, (0)::numeric) = (0)::numeric) AND (mv_loans_sch_info.due_date >= (CURRENT_DATE - '90 days'::interval)) AND (mv_loans_sch_info.due_date <= (CURRENT_DATE - '61 days'::interval))) THEN 1
                    ELSE 0
                END) AS unpaid_61_90_days,
            sum(
                CASE
                    WHEN ((COALESCE(mv_loans_sch_info.paid_total, (0)::numeric) = (0)::numeric) AND (mv_loans_sch_info.due_date < (CURRENT_DATE - '90 days'::interval))) THEN 1
                    ELSE 0
                END) AS unpaid_90_plus_days
           FROM public.mv_loans_sch_info
          GROUP BY mv_loans_sch_info.loan_id
        ), loans_with_repeat_flag AS (
         SELECT mv_loans_info.loan_id,
            mv_loans_info.transaction_id,
            mv_loans_info.consumer_id,
            mv_loans_info.loan_booked_at,
            mv_loans_info.loan_booked_date,
            mv_loans_info.loan_current_status,
            mv_loans_info.is_postponed,
            mv_loans_info.is_rescheduled,
            mv_loans_info.loan_batch_status,
            mv_loans_info.loan_cancelled_at,
            mv_loans_info.loan_early_settled_at,
            mv_loans_info.parent_loan_account_id,
            mv_loans_info.basket_value,
            mv_loans_info.total_principal_amount,
            mv_loans_info.loan_installment_amount,
            mv_loans_info.down_payment_amount,
            mv_loans_info.loan_admin_fee_amount,
            mv_loans_info.vat_amount,
            mv_loans_info.total_interest_amount,
            mv_loans_info.total_late_fee,
            mv_loans_info.total_paid_late_fee,
            mv_loans_info.total_due_amount,
            mv_loans_info.total_paid_amount,
            mv_loans_info.total_principal_paid_amount,
            mv_loans_info.total_interest_paid_amount,
            mv_loans_info.num_of_paid_installments,
            mv_loans_info.num_of_remaining_installments,
            mv_loans_info.total_remaining_amount_with_interest,
            mv_loans_info.total_remaining_amount_without_interest,
            mv_loans_info.potential_interest_loss_if_early_settlement,
            mv_loans_info.financial_product_id,
            mv_loans_info.linked_fp_key,
            mv_loans_info.linked_fp_version,
            mv_loans_info.tenor,
            mv_loans_info.new_tenor,
            mv_loans_info.tenor_interest_percent,
            mv_loans_info.annual_interest_percent,
            mv_loans_info.is_profit_bearing,
            mv_loans_info.retail_category,
            mv_loans_info.checkout_channel,
            mv_loans_info.merchant_id,
            mv_loans_info.merchant_name,
            mv_loans_info.merchant_created_at_utc,
            mv_loans_info.transacted_merchant_brand_id,
            mv_loans_info.transacted_merchant_branch_id,
            mv_loans_info.merchant_city_id,
            mv_loans_info.merchant_city,
            mv_loans_info.transacted_merchant_branch_governorate,
            mv_loans_info.merchant_city_adjusted,
            mv_loans_info.merchant_region,
            mv_loans_info.merchant_type,
            mv_loans_info.consumer_loan_sequence_number,
            mv_loans_info.merchant_loan_sequence_number,
            mv_loans_info.tenor_days,
            mv_loans_info.grace_period_in_days,
            mv_loans_info.borrower_repayment_day_of_month,
            mv_loans_info.view_last_refreshed_time,
            mv_loans_info.next_due_date,
            mv_loans_info.last_paid_date,
            count(mv_loans_info.loan_id) OVER (PARTITION BY mv_loans_info.merchant_id, mv_loans_info.transacted_merchant_brand_id, mv_loans_info.consumer_id) AS consumer_loan_count
           FROM public.mv_loans_info
        ), all_checkouts AS (
         SELECT checkout_baskets.partner_id,
            checkout_baskets.brand_id AS partner_brand_id,
            count(DISTINCT checkout_baskets.id) AS total_checkouts,
            count(DISTINCT
                CASE
                    WHEN ((checkout_baskets.status)::text = 'LOAN_ACTIVATED'::text) THEN checkout_baskets.id
                    ELSE NULL::uuid
                END) AS successful_checkouts
           FROM public.checkout_baskets
          GROUP BY checkout_baskets.partner_id, checkout_baskets.brand_id
        ), merchant_base AS (
         SELECT partner_brand.id AS partner_brand_id,
            partner_brand.partner_id,
            (partner_brand.created_at AT TIME ZONE 'Africa/Cairo'::text) AS created_at,
            (partner_brand.updated_at AT TIME ZONE 'Africa/Cairo'::text) AS updated_at,
            partner_brand.status,
            partner_brand.name_en AS brand_name,
            TRIM(BOTH FROM lower((partner_brand.category)::text)) AS category
           FROM public.partner_brand
        ), brand_details AS (
         SELECT brand_branch.partner_id,
            brand_branch.brand_id,
            count(DISTINCT brand_branch.id) AS total_branches,
            count(DISTINCT brand_branch.governorate_id) AS total_governorates,
            count(DISTINCT brand_branch.city_id) AS total_cities,
            count(DISTINCT brand_branch.area_id) AS total_areas,
            count(DISTINCT
                CASE
                    WHEN ((brand_branch.status)::text = 'ACTIVE'::text) THEN brand_branch.id
                    ELSE NULL::uuid
                END) AS active_branches
           FROM public.brand_branch
          GROUP BY brand_branch.partner_id, brand_branch.brand_id
        ), merchant_data AS (
         SELECT l.merchant_id AS partner_id,
            l.transacted_merchant_brand_id AS partner_brand_id,
            mb.status,
            mb.brand_name,
            l.merchant_type AS partner_type,
            mb.category,
                CASE
                    WHEN ((max(l.loan_booked_at) >= (CURRENT_DATE - '30 days'::interval)) AND ((mb.status)::text = 'ACTIVE'::text)) THEN true
                    ELSE false
                END AS is_active_in_last_30_days,
            COALESCE(max(b.total_branches), (0)::bigint) AS total_branches,
            COALESCE(max(b.active_branches), (0)::bigint) AS active_branches,
            COALESCE(max(b.total_governorates), (0)::bigint) AS total_governorates,
            COALESCE(max(b.total_cities), (0)::bigint) AS total_cities,
            COALESCE(max(b.total_areas), (0)::bigint) AS total_areas,
            min(l.merchant_created_at_utc) AS first_created_at,
            max(mb.updated_at) AS last_updated_at,
            min(l.loan_booked_at) AS first_loan_date,
            max(l.loan_booked_at) AS last_loan_date,
            count(DISTINCT l.loan_id) AS total_loans,
            count(DISTINCT
                CASE
                    WHEN (l.loan_current_status = 'RUNNING'::text) THEN l.loan_id
                    ELSE NULL::character varying
                END) AS running_loans,
            count(DISTINCT
                CASE
                    WHEN (l.loan_current_status = 'CLOSED'::text) THEN l.loan_id
                    ELSE NULL::character varying
                END) AS closed_loans,
            count(DISTINCT
                CASE
                    WHEN (l.loan_current_status = 'EARLY_SETTLED'::text) THEN l.loan_id
                    ELSE NULL::character varying
                END) AS early_settled_loans,
            count(DISTINCT
                CASE
                    WHEN (l.loan_current_status = 'PARTIAL_REFUND'::text) THEN l.loan_id
                    ELSE NULL::character varying
                END) AS partial_refund_loans,
            count(DISTINCT
                CASE
                    WHEN (l.loan_current_status = 'CANCELLED'::text) THEN l.loan_id
                    ELSE NULL::character varying
                END) AS cancelled_loans,
            count(DISTINCT l.consumer_id) AS total_consumers,
            count(DISTINCT
                CASE
                    WHEN (l.consumer_loan_count > 1) THEN l.consumer_id
                    ELSE NULL::character varying
                END) AS repeated_consumers,
            round(((count(DISTINCT
                CASE
                    WHEN (l.consumer_loan_count > 1) THEN l.consumer_id
                    ELSE NULL::character varying
                END))::numeric / (NULLIF(count(DISTINCT l.consumer_id), 0))::numeric), 2) AS repeat_consumer_rate,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN (l.num_of_paid_installments)::bigint
                    ELSE (0)::bigint
                END) AS num_of_paid_installments,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN l.num_of_remaining_installments
                    ELSE (0)::bigint
                END) AS num_of_remaining_installments,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_amount
                    ELSE (0)::numeric
                END) AS total_due_amount,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_paid
                    ELSE (0)::numeric
                END) AS total_due_paid,
            round((sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_paid
                    ELSE (0)::numeric
                END) / NULLIF(sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_amount
                    ELSE (0)::numeric
                END), (0)::numeric)), 2) AS overall_collection_rate,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.due_amount_to_date
                    ELSE (0)::numeric
                END) AS total_due_amount_to_date,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.due_paid_to_date
                    ELSE (0)::numeric
                END) AS total_due_paid_to_date,
            round((sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_paid
                    ELSE (0)::numeric
                END) / NULLIF(sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.due_amount_to_date
                    ELSE (0)::numeric
                END), (0)::numeric)), 2) AS collection_rate_to_date,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.due_principal, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_principal_amount,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.paid_principal_only, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_paid_principal,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.due_principal_to_date
                    ELSE (0)::numeric
                END) AS total_principal_to_date,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.paid_principal_to_date
                    ELSE (0)::numeric
                END) AS total_paid_principal_to_date,
            round((sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN l.total_principal_amount
                    ELSE (0)::numeric
                END) / (NULLIF(count(DISTINCT
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN l.loan_id
                    ELSE NULL::character varying
                END), 0))::numeric), 2) AS avg_financed_amount,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.due_interest, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_interest_due,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.paid_interest, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_interest_paid,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.interest_due_to_date
                    ELSE (0)::numeric
                END) AS total_interest_due_to_date,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.interest_paid_to_date
                    ELSE (0)::numeric
                END) AS total_interest_paid_to_date,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN l.loan_admin_fee_amount
                    ELSE (0)::numeric
                END) AS loan_admin_fee_amount,
            max(l.total_principal_amount) AS max_financed_amount,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.unpaid_last_30_days
                    ELSE (0)::bigint
                END) AS unpaid_last_30_days,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.unpaid_31_60_days
                    ELSE (0)::bigint
                END) AS unpaid_31_60_days,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.unpaid_61_90_days
                    ELSE (0)::bigint
                END) AS unpaid_61_90_days,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.unpaid_90_plus_days
                    ELSE (0)::bigint
                END) AS unpaid_90_plus_days,
            max(ac.successful_checkouts) AS successful_checkouts,
            max(ac.total_checkouts) AS total_checkouts,
            round(((max(ac.successful_checkouts))::numeric / NULLIF((max(ac.total_checkouts))::numeric, (0)::numeric)), 2) AS checkout_success_rate
           FROM ((((loans_with_repeat_flag l
             LEFT JOIN li_agg li ON (((l.loan_id)::text = (li.loan_id)::text)))
             LEFT JOIN merchant_base mb ON ((((l.merchant_id)::uuid = mb.partner_id) AND (l.transacted_merchant_brand_id = mb.partner_brand_id))))
             LEFT JOIN brand_details b ON ((((l.merchant_id)::uuid = b.partner_id) AND (l.transacted_merchant_brand_id = b.brand_id))))
             LEFT JOIN all_checkouts ac ON ((((l.merchant_id)::uuid = ac.partner_id) AND (l.transacted_merchant_brand_id = ac.partner_brand_id))))
          GROUP BY l.merchant_id, l.transacted_merchant_brand_id, mb.brand_name, mb.status, l.merchant_type, mb.category
        )
 SELECT partner_id,
    partner_brand_id,
    status,
    brand_name,
    partner_type,
    category,
    is_active_in_last_30_days,
    total_branches,
    active_branches,
    total_governorates,
    total_cities,
    total_areas,
    first_created_at,
    last_updated_at,
    first_loan_date,
    last_loan_date,
    total_loans,
    running_loans,
    closed_loans,
    early_settled_loans,
    partial_refund_loans,
    cancelled_loans,
    total_consumers,
    repeated_consumers,
    repeat_consumer_rate,
    num_of_paid_installments,
    num_of_remaining_installments,
    total_due_amount,
    total_due_paid,
    overall_collection_rate,
    total_due_amount_to_date,
    total_due_paid_to_date,
    collection_rate_to_date,
    total_principal_amount,
    total_paid_principal,
    total_principal_to_date,
    total_paid_principal_to_date,
    avg_financed_amount,
    total_interest_due,
    total_interest_paid,
    total_interest_due_to_date,
    total_interest_paid_to_date,
    loan_admin_fee_amount,
    max_financed_amount,
    unpaid_last_30_days,
    unpaid_31_60_days,
    unpaid_61_90_days,
    unpaid_90_plus_days,
    successful_checkouts,
    total_checkouts,
    checkout_success_rate,
    (now() AT TIME ZONE 'Africa/Cairo'::text) AS last_refreshed_at
   FROM merchant_data;


--
-- Name: v_merchant_brand_monthly; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_merchant_brand_monthly AS
 WITH li_agg AS (
         SELECT mv_loans_sch_info.loan_id,
            mv_loans_sch_info.consumer_id,
            date_trunc('month'::text, (mv_loans_sch_info.due_date)::timestamp with time zone) AS due_month,
            sum(COALESCE(mv_loans_sch_info.due_principal, (0)::numeric)) AS due_principal,
            sum(COALESCE(mv_loans_sch_info.paid_principal, (0)::numeric)) AS paid_principal_only,
            sum(COALESCE(mv_loans_sch_info.due_interest, (0)::numeric)) AS due_interest,
            sum(COALESCE(mv_loans_sch_info.paid_interest, (0)::numeric)) AS paid_interest,
            sum(COALESCE(mv_loans_sch_info.late_fee, (0)::numeric)) AS late_fee,
            sum(COALESCE(mv_loans_sch_info.paid_total, (0)::numeric)) AS total_due_paid,
            sum((COALESCE(mv_loans_sch_info.due_principal, (0)::numeric) + COALESCE(mv_loans_sch_info.due_interest, (0)::numeric))) AS total_due_amount
           FROM public.mv_loans_sch_info
          WHERE (mv_loans_sch_info.due_date <= CURRENT_DATE)
          GROUP BY mv_loans_sch_info.loan_id, mv_loans_sch_info.consumer_id, (date_trunc('month'::text, (mv_loans_sch_info.due_date)::timestamp with time zone))
        ), all_checkouts AS (
         SELECT checkout_baskets.partner_id,
            checkout_baskets.brand_id AS partner_brand_id,
            date_trunc('month'::text, checkout_baskets.created_at) AS checkout_month,
            count(DISTINCT checkout_baskets.id) AS total_checkouts,
            count(DISTINCT
                CASE
                    WHEN ((checkout_baskets.status)::text = 'LOAN_ACTIVATED'::text) THEN checkout_baskets.id
                    ELSE NULL::uuid
                END) AS successful_checkouts
           FROM public.checkout_baskets
          WHERE (checkout_baskets.created_at <= CURRENT_DATE)
          GROUP BY checkout_baskets.partner_id, checkout_baskets.brand_id, (date_trunc('month'::text, checkout_baskets.created_at))
        ), merchant_data AS (
         SELECT l.merchant_id AS partner_id,
            l.transacted_merchant_brand_id AS partner_brand_id,
            li.due_month,
            l.merchant_name AS partner_name,
            l.merchant_type AS partner_type,
            count(DISTINCT li.loan_id) AS total_loans,
            count(DISTINCT li.consumer_id) AS total_consumers,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_amount
                    ELSE (0)::numeric
                END) AS total_due_amount,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_paid
                    ELSE (0)::numeric
                END) AS total_due_paid,
            round((sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_paid
                    ELSE (0)::numeric
                END) / NULLIF(sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN li.total_due_amount
                    ELSE (0)::numeric
                END), (0)::numeric)), 2) AS collection_rate,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.due_principal, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_principal_amount,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.paid_principal_only, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_paid_principal,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.due_interest, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_interest_due,
            sum(
                CASE
                    WHEN (l.loan_cancelled_at IS NULL) THEN COALESCE(li.paid_interest, (0)::numeric)
                    ELSE (0)::numeric
                END) AS total_interest_paid,
            max(ac.total_checkouts) AS total_checkouts,
            max(ac.successful_checkouts) AS successful_checkouts,
            round(((max(ac.successful_checkouts))::numeric / NULLIF((max(ac.total_checkouts))::numeric, (0)::numeric)), 2) AS checkout_success_rate,
            (now() AT TIME ZONE 'Africa/Cairo'::text) AS last_refreshed_at
           FROM ((public.mv_loans_info l
             JOIN li_agg li ON (((l.loan_id)::text = (li.loan_id)::text)))
             LEFT JOIN all_checkouts ac ON ((((l.merchant_id)::uuid = ac.partner_id) AND (l.transacted_merchant_brand_id = ac.partner_brand_id) AND (li.due_month = ac.checkout_month))))
          GROUP BY l.merchant_id, l.transacted_merchant_brand_id, li.due_month, l.merchant_name, l.merchant_type
        )
 SELECT partner_id,
    partner_brand_id,
    due_month,
    partner_name,
    partner_type,
    total_loans,
    total_consumers,
    total_due_amount,
    total_due_paid,
    collection_rate,
    total_principal_amount,
    total_paid_principal,
    total_interest_due,
    total_interest_paid,
    total_checkouts,
    successful_checkouts,
    checkout_success_rate,
    last_refreshed_at
   FROM merchant_data;


--
-- Name: v_merchant_brand_performance; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_merchant_brand_performance AS
 WITH loan_data AS (
         SELECT la.id AS loan_id,
            la.merchant_id AS partner_id,
            cb.brand_id AS partner_brand_id,
            la.borrower_id AS consumer_id,
            (la.booked_at)::date AS loan_booked_date,
            (la.tenor_days / 30) AS tenor,
                CASE
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'NOT_AVAILABLE'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'RESCHEDULED'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'EARLY_SETTLEMENT_REQUESTED'::text)) THEN 'EARLY_SETTLED'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'RESCHEDULED_POSTPONED'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'ACTIVE'::text) AND ((la.sub_state)::text = 'POSTPONED'::text)) THEN 'RUNNING'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'PARTIAL_REFUND_REQUESTED'::text)) THEN 'PARTIAL_REFUND'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'WITHDRAWN'::text)) THEN 'CANCELLED'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'EARLY_SETTLED'::text)) THEN 'EARLY_SETTLED'::text
                    WHEN (((la.state)::text = 'CLOSED'::text) AND ((la.sub_state)::text = 'SETTLED'::text)) THEN 'CLOSED'::text
                    ELSE 'UNKNOWN'::text
                END AS loan_current_status
           FROM ((loan_management.loan_account la
             LEFT JOIN public.checkout_basket_loan_action cbla ON ((cbla.loan_id = (la.id)::uuid)))
             LEFT JOIN public.checkout_baskets cb ON ((cb.id = cbla.checkout_basket_id)))
        ), monetary_amounts AS (
         SELECT lamli.loan_account_id AS loan_id,
            (sum(
                CASE
                    WHEN ((lamli.type)::text = 'DOWN_PAYMENT'::text) THEN lamli.amount_units
                    ELSE (0)::bigint
                END) / 100.0) AS down_payment_amount,
            (sum(
                CASE
                    WHEN ((lamli.type)::text = 'ADMIN_FEE'::text) THEN lamli.amount_units
                    ELSE (0)::bigint
                END) / 100.0) AS admin_fee_amount,
            (sum(
                CASE
                    WHEN ((lamli.type)::text = 'VAT'::text) THEN lamli.amount_units
                    ELSE (0)::bigint
                END) / 100.0) AS vat_amount
           FROM loan_management.loan_account_monetary_line_item lamli
          GROUP BY lamli.loan_account_id
        ), amortization_agg AS (
         SELECT ali.loan_account_id AS loan_id,
            (sum(
                CASE
                    WHEN (ali.canceled_at IS NULL) THEN ali.principal_due_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_principal_due_amount,
            (sum(
                CASE
                    WHEN (((ali.installment_due_date)::date <= CURRENT_DATE) AND (ali.canceled_at IS NULL)) THEN ali.principal_due_units
                    ELSE (0)::bigint
                END) / 100.0) AS principal_due_to_date,
            (sum(
                CASE
                    WHEN (ali.canceled_at IS NULL) THEN ali.principal_paid_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_principal_paid_amount,
            (sum(
                CASE
                    WHEN (ali.canceled_at IS NULL) THEN ali.total_due_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_due_amount,
            (sum(
                CASE
                    WHEN (((ali.installment_due_date)::date <= CURRENT_DATE) AND (ali.canceled_at IS NULL)) THEN ali.total_due_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_due_to_date,
            (sum(
                CASE
                    WHEN (ali.canceled_at IS NULL) THEN ali.total_paid_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_paid_amount,
            (sum(
                CASE
                    WHEN (((ali.installment_due_date)::date <= CURRENT_DATE) AND (ali.canceled_at IS NULL)) THEN ali.total_paid_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_collected_to_date,
            (sum(
                CASE
                    WHEN (((ali.installment_due_date)::date <= CURRENT_DATE) AND (ali.canceled_at IS NULL)) THEN ali.principal_paid_units
                    ELSE (0)::bigint
                END) / 100.0) AS principal_collected_to_date,
            (sum(
                CASE
                    WHEN (ali.canceled_at IS NULL) THEN ali.interest_due_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_interest_due_amount,
            (sum(
                CASE
                    WHEN (ali.canceled_at IS NULL) THEN ali.interest_paid_units
                    ELSE (0)::bigint
                END) / 100.0) AS total_interest_paid_amount,
            (sum(
                CASE
                    WHEN (((ali.installment_due_date)::date <= CURRENT_DATE) AND (ali.canceled_at IS NULL)) THEN ali.interest_due_units
                    ELSE (0)::bigint
                END) / 100.0) AS interest_due_to_date,
            (sum(
                CASE
                    WHEN (((ali.installment_due_date)::date <= CURRENT_DATE) AND (ali.canceled_at IS NULL)) THEN ali.interest_paid_units
                    ELSE (0)::bigint
                END) / 100.0) AS interest_collected_to_date,
            count(
                CASE
                    WHEN ((ali.canceled_at IS NULL) AND (ali.total_paid_units > 0)) THEN 1
                    ELSE NULL::integer
                END) AS paid_installments,
            count(
                CASE
                    WHEN ((ali.total_paid_units = 0) AND (ali.canceled_at IS NULL)) THEN 1
                    ELSE NULL::integer
                END) AS remaining_installments,
            count(
                CASE
                    WHEN ((ali.total_paid_units = 0) AND (ali.canceled_at IS NULL) AND (((ali.installment_due_date)::date >= (CURRENT_DATE - '30 days'::interval)) AND ((ali.installment_due_date)::date <= CURRENT_DATE))) THEN 1
                    ELSE NULL::integer
                END) AS unpaid_last_30_days,
            count(
                CASE
                    WHEN ((ali.total_paid_units = 0) AND (ali.canceled_at IS NULL) AND (((ali.installment_due_date)::date >= (CURRENT_DATE - '60 days'::interval)) AND ((ali.installment_due_date)::date <= (CURRENT_DATE - '31 days'::interval)))) THEN 1
                    ELSE NULL::integer
                END) AS unpaid_31_60_days,
            count(
                CASE
                    WHEN ((ali.total_paid_units = 0) AND (ali.canceled_at IS NULL) AND (((ali.installment_due_date)::date >= (CURRENT_DATE - '90 days'::interval)) AND ((ali.installment_due_date)::date <= (CURRENT_DATE - '61 days'::interval)))) THEN 1
                    ELSE NULL::integer
                END) AS unpaid_61_90_days,
            count(
                CASE
                    WHEN ((ali.total_paid_units = 0) AND (ali.canceled_at IS NULL) AND ((ali.installment_due_date)::date < (CURRENT_DATE - '90 days'::interval))) THEN 1
                    ELSE NULL::integer
                END) AS unpaid_90_plus_days
           FROM loan_management.loan_account_ammortisation_line_item ali
          GROUP BY ali.loan_account_id
        ), consumers_data AS (
         SELECT loan_data.partner_id,
            loan_data.partner_brand_id,
            loan_data.consumer_id,
            count(DISTINCT loan_data.loan_id) AS loans_per_consumer
           FROM loan_data
          GROUP BY loan_data.partner_id, loan_data.partner_brand_id, loan_data.consumer_id
        ), repeat_consumers AS (
         SELECT consumers_data.partner_id,
            consumers_data.partner_brand_id,
            count(DISTINCT consumers_data.consumer_id) AS repeated_consumers
           FROM consumers_data
          WHERE (consumers_data.loans_per_consumer > 1)
          GROUP BY consumers_data.partner_id, consumers_data.partner_brand_id
        ), all_checkouts AS (
         SELECT checkout_baskets.partner_id,
            checkout_baskets.brand_id AS partner_brand_id,
            count(DISTINCT checkout_baskets.id) AS total_checkouts,
            count(DISTINCT
                CASE
                    WHEN ((checkout_baskets.status)::text = 'LOAN_ACTIVATED'::text) THEN checkout_baskets.id
                    ELSE NULL::uuid
                END) AS successful_checkouts
           FROM public.checkout_baskets
          GROUP BY checkout_baskets.partner_id, checkout_baskets.brand_id
        ), merchant_disbursement AS (
         SELECT pb.partner_id,
            pb.id AS partner_brand_id,
            count(DISTINCT lb.loan_id) AS total_loans,
            count(DISTINCT lb.consumer_id) AS total_consumers,
            max(ac.total_checkouts) AS total_checkouts,
            max(ac.successful_checkouts) AS successful_checkouts,
            round(sum(am.total_due_amount), 2) AS total_due_amount,
            round(sum(am.total_paid_amount), 2) AS total_due_paid_amount,
            round(sum(am.total_due_to_date), 2) AS total_due_to_date,
            round(sum(am.total_collected_to_date), 2) AS total_due_paid_to_date,
            round(sum(am.total_principal_due_amount), 2) AS total_principal_amount,
            round(sum(am.total_principal_paid_amount), 2) AS total_principal_paid_amount,
            round(sum(am.principal_due_to_date), 2) AS total_principal_to_date,
            round(sum(am.principal_collected_to_date), 2) AS total_principal_paid_to_date,
            round(sum(am.total_interest_due_amount), 2) AS total_interest_amount,
            round(sum(am.total_interest_paid_amount), 2) AS total_interest_paid_amount,
            round(sum(am.interest_due_to_date), 2) AS total_interest_to_date,
            round(sum(am.interest_collected_to_date), 2) AS total_interest_paid_to_date,
            round(sum(ma.down_payment_amount), 2) AS total_down_payment_amount,
            round(sum(ma.admin_fee_amount), 2) AS total_admin_fee_amount,
            round(avg(am.total_principal_due_amount), 2) AS avg_financed_amount,
            round(max(am.total_principal_due_amount), 2) AS max_financed_amount,
            round(avg(lb.tenor), 2) AS avg_tenor,
            sum(am.paid_installments) AS total_paid_installments,
            sum(am.remaining_installments) AS total_remaining_installments,
            count(DISTINCT
                CASE
                    WHEN (lb.loan_current_status = 'CLOSED'::text) THEN lb.loan_id
                    ELSE NULL::character varying
                END) AS closed_loans,
            count(DISTINCT
                CASE
                    WHEN (lb.loan_current_status = 'RUNNING'::text) THEN lb.loan_id
                    ELSE NULL::character varying
                END) AS running_loans,
            count(DISTINCT
                CASE
                    WHEN (lb.loan_current_status = 'EARLY_SETTLED'::text) THEN lb.loan_id
                    ELSE NULL::character varying
                END) AS early_settled_loans,
            count(DISTINCT
                CASE
                    WHEN (lb.loan_current_status = 'CANCELLED'::text) THEN lb.loan_id
                    ELSE NULL::character varying
                END) AS cancelled_loans,
            count(DISTINCT
                CASE
                    WHEN (lb.loan_current_status = 'PARTIAL_REFUND'::text) THEN lb.loan_id
                    ELSE NULL::character varying
                END) AS partial_refund_loans,
            min(lb.loan_booked_date) AS first_loan_date,
            max(lb.loan_booked_date) AS last_loan_date,
            sum(am.unpaid_last_30_days) AS unpaid_installments_last_30_days,
            sum(am.unpaid_31_60_days) AS unpaid_installments_31_60_days,
            sum(am.unpaid_61_90_days) AS unpaid_installments_61_90_days,
            sum(am.unpaid_90_plus_days) AS unpaid_installments_90_plus_days
           FROM ((((public.partner_brand pb
             LEFT JOIN loan_data lb ON (((pb.partner_id = (lb.partner_id)::uuid) AND (pb.id = lb.partner_brand_id))))
             LEFT JOIN monetary_amounts ma ON (((lb.loan_id)::text = (ma.loan_id)::text)))
             LEFT JOIN amortization_agg am ON (((lb.loan_id)::text = (am.loan_id)::text)))
             LEFT JOIN all_checkouts ac ON (((pb.partner_id = ac.partner_id) AND (pb.id = ac.partner_brand_id))))
          GROUP BY pb.partner_id, pb.id
        ), merchant_base AS (
         SELECT partner_brand.id AS partner_brand_id,
            partner_brand.partner_id,
            (partner_brand.created_at AT TIME ZONE 'Africa/Cairo'::text) AS created_at,
            (partner_brand.updated_at AT TIME ZONE 'Africa/Cairo'::text) AS updated_at,
            partner_brand.status,
            partner_brand.name_en AS brand_name,
            TRIM(BOTH FROM lower((partner_brand.category)::text)) AS category
           FROM public.partner_brand
        ), brand_details AS (
         SELECT brand_branch.brand_id,
            count(DISTINCT brand_branch.id) AS total_branches,
            count(DISTINCT brand_branch.governorate_id) AS total_governorates,
            count(DISTINCT brand_branch.city_id) AS total_cities,
            count(DISTINCT brand_branch.area_id) AS total_areas,
            count(DISTINCT
                CASE
                    WHEN ((brand_branch.status)::text = 'ACTIVE'::text) THEN brand_branch.id
                    ELSE NULL::uuid
                END) AS active_branches
           FROM public.brand_branch
          GROUP BY brand_branch.brand_id
        )
 SELECT md.partner_id,
    md.partner_brand_id,
    md.first_loan_date,
    md.last_loan_date,
    md.total_loans,
    md.running_loans,
    md.closed_loans,
    md.early_settled_loans,
    md.cancelled_loans,
    md.partial_refund_loans,
    md.total_consumers,
    COALESCE(rb.repeated_consumers, (0)::bigint) AS repeat_consumers,
    round((COALESCE((rb.repeated_consumers)::numeric, (0)::numeric) / NULLIF((md.total_consumers)::numeric, (0)::numeric)), 2) AS repeat_consumer_rate_percent,
    md.total_paid_installments,
    md.total_remaining_installments,
    md.total_due_amount,
    md.total_due_paid_amount,
    round((md.total_due_paid_amount / NULLIF(md.total_due_amount, (0)::numeric)), 2) AS overall_collection_rate,
    md.total_due_to_date,
    md.total_due_paid_to_date,
    round((md.total_due_paid_to_date / NULLIF(md.total_due_to_date, (0)::numeric)), 2) AS collection_rate_to_date,
    md.total_principal_amount,
    md.total_principal_paid_amount,
    md.total_principal_to_date,
    md.total_principal_paid_to_date,
    md.total_interest_amount,
    md.total_interest_paid_amount,
    md.total_interest_to_date,
    md.total_interest_paid_to_date,
    round((md.total_interest_amount / NULLIF(md.total_principal_amount, (0)::numeric)), 2) AS interest_to_principal_ratio_percent,
    md.total_admin_fee_amount,
    md.avg_financed_amount,
    md.max_financed_amount,
    md.avg_tenor,
        CASE
            WHEN (md.last_loan_date >= (CURRENT_DATE - '30 days'::interval)) THEN true
            ELSE false
        END AS is_active_in_last_30_days,
    round(((md.successful_checkouts)::numeric / NULLIF((md.total_checkouts)::numeric, (0)::numeric)), 2) AS checkout_success_rate,
    md.unpaid_installments_last_30_days,
    md.unpaid_installments_31_60_days,
    md.unpaid_installments_61_90_days,
    md.unpaid_installments_90_plus_days,
    p.created_at,
    p.updated_at,
    p.status,
    p.brand_name,
    p.category,
    COALESCE(b.total_branches, (0)::bigint) AS total_branches,
    COALESCE(b.active_branches, (0)::bigint) AS active_branches,
    COALESCE(b.total_governorates, (0)::bigint) AS total_governorates,
    COALESCE(b.total_cities, (0)::bigint) AS total_cities,
    COALESCE(b.total_areas, (0)::bigint) AS total_areas,
    (now() AT TIME ZONE 'Africa/Cairo'::text) AS last_refreshed_at
   FROM (((merchant_disbursement md
     LEFT JOIN repeat_consumers rb ON (((md.partner_id = (rb.partner_id)::uuid) AND (md.partner_brand_id = rb.partner_brand_id))))
     LEFT JOIN merchant_base p ON (((md.partner_id = p.partner_id) AND (md.partner_brand_id = p.partner_brand_id))))
     LEFT JOIN brand_details b ON ((p.partner_brand_id = b.brand_id)));


--
-- Name: merchant_payment; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.merchant_payment (
    id uuid NOT NULL,
    payment_account_id character varying(50) NOT NULL,
    payment_connector_type character varying(50) NOT NULL,
    payable_units bigint NOT NULL,
    payable_currency character varying(10) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    sequence_id bigint NOT NULL
);


--
-- Name: merchant_payment_status_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.merchant_payment_status_logs (
    id uuid NOT NULL,
    payment_id uuid NOT NULL,
    status character varying(50) NOT NULL,
    status_date timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);


--
-- Name: party_account; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.party_account (
    id integer NOT NULL,
    global_reference_id character varying(50) NOT NULL,
    account_type character varying(255) NOT NULL,
    account_status character varying(50) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL
);


--
-- Name: temp_merchant_payment; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.temp_merchant_payment (
    id character varying(50) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    merchant_account_id character varying(60) NOT NULL,
    payable_units bigint NOT NULL,
    payable_currency character varying(3) NOT NULL,
    transaction_date timestamp(6) with time zone NOT NULL,
    success_ga_posting boolean NOT NULL,
    ga_posting_response json,
    status character varying(30),
    status_timestamp date,
    serial_id integer NOT NULL
);


--
-- Name: v_merchant_payments; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_merchant_payments AS
 WITH sla_calculation AS (
         SELECT subquery.id,
            subquery.merchant_account_id,
            subquery.payable_amount,
            (((subquery.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date AS local_transaction_date,
            subquery.status_timestamp,
            subquery.status,
                CASE
                    WHEN (EXTRACT(dow FROM (((subquery.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date) = ANY (ARRAY[(0)::numeric, (1)::numeric, (2)::numeric])) THEN (((((subquery.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date + '3 days'::interval))::date
                    WHEN (EXTRACT(dow FROM (((subquery.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date) = ANY (ARRAY[(3)::numeric, (4)::numeric, (5)::numeric, (6)::numeric])) THEN ((((((subquery.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date + (((7)::numeric - EXTRACT(dow FROM (((subquery.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date)))::integer) + '1 day'::interval))::date
                    ELSE NULL::date
                END AS expected_payment_date,
                CASE
                    WHEN ((subquery.status IS NULL) AND (subquery.expected_payment_date < CURRENT_DATE)) THEN 1
                    WHEN ((subquery.status IS NOT NULL) AND (subquery.status_timestamp > subquery.expected_payment_date)) THEN 1
                    ELSE 0
                END AS sla_breach
           FROM ( SELECT merchant_payment_1.id,
                    merchant_payment_1.merchant_account_id,
                    ((merchant_payment_1.payable_units)::double precision / (100)::double precision) AS payable_amount,
                    merchant_payment_1.transaction_date,
                    merchant_payment_1.status_timestamp,
                    merchant_payment_1.status,
                    (((merchant_payment_1.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date AS local_transaction_date,
                        CASE
                            WHEN (EXTRACT(dow FROM (((merchant_payment_1.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date) = ANY (ARRAY[(0)::numeric, (1)::numeric, (2)::numeric])) THEN (((((merchant_payment_1.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date + '3 days'::interval))::date
                            WHEN (EXTRACT(dow FROM (((merchant_payment_1.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date) = ANY (ARRAY[(3)::numeric, (4)::numeric, (5)::numeric, (6)::numeric])) THEN ((((((merchant_payment_1.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date + (((7)::numeric - EXTRACT(dow FROM (((merchant_payment_1.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date)))::integer) + '1 day'::interval))::date
                            ELSE NULL::date
                        END AS expected_payment_date
                   FROM public.temp_merchant_payment merchant_payment_1) subquery
        )
 SELECT p.id AS merchant_id,
    merchant_payment.id,
    merchant_payment.payment_account_id AS merchant_account_id,
    ((merchant_payment.payable_units)::double precision / (100)::double precision) AS payable_amount,
    merchant_payment.created_at AS transaction_date,
    l.status_timestamp,
    l.status,
    (((merchant_payment.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date AS local_transaction_date,
        CASE
            WHEN (EXTRACT(dow FROM (((merchant_payment.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date) = ANY (ARRAY[(0)::numeric, (1)::numeric, (2)::numeric])) THEN (((((merchant_payment.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date + '3 days'::interval))::date
            WHEN (EXTRACT(dow FROM (((merchant_payment.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date) = ANY (ARRAY[(3)::numeric, (4)::numeric, (5)::numeric, (6)::numeric])) THEN ((((((merchant_payment.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date + (((7)::numeric - EXTRACT(dow FROM (((merchant_payment.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date)))::integer) + '1 day'::interval))::date
            ELSE NULL::date
        END AS expected_payment_date
   FROM (((public.merchant_payment
     LEFT JOIN ( SELECT max((merchant_payment_status_logs.status)::text) AS status,
            max(merchant_payment_status_logs.status_date) AS status_timestamp,
            merchant_payment_status_logs.payment_id
           FROM public.merchant_payment_status_logs
          GROUP BY merchant_payment_status_logs.payment_id) l ON ((l.payment_id = merchant_payment.id)))
     LEFT JOIN public.party_account ON (((merchant_payment.payment_account_id)::integer = party_account.id)))
     LEFT JOIN public.partner p ON ((((p.id)::character varying)::text = ((party_account.global_reference_id)::character varying)::text)));


