-- Name: v_repayments_info; Type: VIEW; Schema: auto_views; Owner: -
--

CREATE VIEW auto_views.v_repayments_info AS
 WITH pmy AS (
         SELECT pm.payment_id,
            p.reference,
            p.type,
            'mylo'::text AS source,
            p.status,
            p.consumer_id,
            p.amount AS mylo_and_minicash_amount,
            p.collection_fee_amount,
            p.source_channel AS payment_channel,
            (p.created_at AT TIME ZONE 'Africa/Cairo'::text) AS created_at,
            pm.loan_id AS mylo_loan_id,
            pm.loan_schedule_number AS mylo_loan_schedule_number,
            pm.paid_principal AS mylo_paid_principal,
            pm.paid_interest AS mylo_paid_interest,
            pm.paid_late_fee AS mylo_paid_fee,
            pm.total_amount AS mylo_total_amount,
            pm.partner_name AS mylo_partner_name,
            pm.due_date AS mylo_due_date,
            ''::text AS minicash_order_code,
            NULL::numeric AS minicash_no_of_payment,
            NULL::numeric AS minicash_paid_principal,
            NULL::numeric AS minicash_paid_interest,
            NULL::numeric AS minicash_total_amount,
            NULL::numeric AS minicash_fine_amount,
            NULL::date AS minicash_due_date
           FROM (repayments.payment_mylo pm
             JOIN repayments.payments p ON ((pm.payment_id = p.id)))
        ), pmi AS (
         SELECT pm.payment_id,
            p.reference,
            p.type,
            'minicash'::text AS source,
            p.status,
            p.consumer_id,
            p.amount AS mylo_and_minicash_amount,
            p.collection_fee_amount,
            p.source_channel AS payment_channel,
            (p.created_at AT TIME ZONE 'Africa/Cairo'::text) AS created_at,
            NULL::uuid AS mylo_loan_id,
            NULL::numeric AS mylo_loan_schedule_number,
            NULL::numeric AS mylo_paid_principal,
            NULL::numeric AS mylo_paid_interest,
            NULL::numeric AS mylo_paid_fee,
            NULL::numeric AS mylo_total_amount,
            NULL::text AS mylo_partner_name,
            NULL::date AS mylo_due_date,
            pm.order_code AS minicash_order_code,
            pm.no_of_payment AS minicash_no_of_payment,
            pm.paid_principal AS minicash_paid_principal,
            pm.paid_interest AS minicash_paid_interest,
            pm.installment_amount AS minicash_total_amount,
            pm.fine_amount AS minicash_fine_amount,
            pm.due_date AS minicash_due_date
           FROM (repayments.payment_minicash pm
             JOIN repayments.payments p ON ((pm.payment_id = p.id)))
        ), pm AS (
         SELECT pmy.payment_id,
            pmy.reference,
            pmy.type,
            pmy.source,
            pmy.status,
            pmy.consumer_id,
            pmy.mylo_and_minicash_amount,
            pmy.collection_fee_amount,
            pmy.payment_channel,
            pmy.created_at,
            pmy.mylo_loan_id,
            pmy.mylo_loan_schedule_number,
            pmy.mylo_paid_principal,
            pmy.mylo_paid_interest,
            pmy.mylo_paid_fee,
            pmy.mylo_total_amount,
            pmy.mylo_partner_name,
            pmy.mylo_due_date,
            pmy.minicash_order_code,
            pmy.minicash_no_of_payment,
            pmy.minicash_paid_principal,
            pmy.minicash_paid_interest,
            pmy.minicash_total_amount,
            pmy.minicash_fine_amount,
            pmy.minicash_due_date
           FROM pmy
        UNION
         SELECT pmi.payment_id,
            pmi.reference,
            pmi.type,
            pmi.source,
            pmi.status,
            pmi.consumer_id,
            pmi.mylo_and_minicash_amount,
            pmi.collection_fee_amount,
            pmi.payment_channel,
            pmi.created_at,
            pmi.mylo_loan_id,
            pmi.mylo_loan_schedule_number,
            pmi.mylo_paid_principal,
            pmi.mylo_paid_interest,
            pmi.mylo_paid_fee,
            pmi.mylo_total_amount,
            pmi.mylo_partner_name,
            pmi.mylo_due_date,
            pmi.minicash_order_code,
            pmi.minicash_no_of_payment,
            pmi.minicash_paid_principal,
            pmi.minicash_paid_interest,
            pmi.minicash_total_amount,
            pmi.minicash_fine_amount,
            pmi.minicash_due_date
           FROM pmi
        ), lap AS (
         SELECT lap.loan_account_id,
            lap.payment_reference_id,
            lap.ammortisation_line_item_sequence,
            (lap.booked_at AT TIME ZONE 'Africa/Cairo'::text) AS paid_at,
            ((lap.booked_at AT TIME ZONE 'Africa/Cairo'::text))::date AS paid_date,
            lap.paid_units
           FROM loan_management.loan_account_payment lap
        ), meta AS (
         SELECT mv2.payment_id,
            NULLIF(COALESCE((mv2.metadata ->> 'reference_number'::text), (mv2.metadata ->> 'referenceNumber'::text)), ''::text) AS payment_branch_ref_number,
            NULLIF((mv2.metadata ->> 'payment_method_code'::text), ''::text) AS payment_method_code,
            NULLIF((mv2.metadata ->> 'collected_by'::text), ''::text) AS payment_collected_by,
            NULLIF(COALESCE((mv2.metadata ->> 'collectionAgentEmail'::text), (mv2.metadata ->> 'COLLECTIONAGENTEMAIL'::text)), ''::text) AS collection_agent_email,
            NULLIF(COALESCE((mv2.metadata ->> 'collectionBranchCode'::text), (mv2.metadata ->> 'collection_branch_code'::text), (mv2.metadata ->> 'collection_store_id'::text), (mv2.metadata ->> 'store_id'::text)), ''::text) AS collection_branch_code,
            NULLIF(COALESCE((mv2.metadata ->> 'cardLast4Digits'::text), (mv2.metadata ->> 'card_number'::text)), ''::text) AS card_last4_digits
           FROM repayments.payment_metadata_v2 mv2
        ), final_result AS (
         SELECT DISTINCT pm.payment_id,
            pm.reference,
            pm.type,
            pm.source,
            pm.status,
            pm.consumer_id,
            pm.mylo_and_minicash_amount,
            pm.collection_fee_amount,
            pm.payment_channel,
            pm.mylo_loan_id,
            pm.mylo_loan_schedule_number,
            pm.mylo_paid_principal,
            pm.mylo_paid_interest,
            pm.mylo_paid_fee,
            pm.mylo_total_amount,
            pm.mylo_partner_name,
            pm.mylo_due_date,
            pm.minicash_order_code,
            pm.minicash_no_of_payment,
            pm.minicash_paid_principal,
            pm.minicash_paid_interest,
            pm.minicash_total_amount,
            pm.minicash_fine_amount,
            pm.minicash_due_date,
            COALESCE((lap.paid_at)::timestamp with time zone, pm.created_at) AS paid_at,
            COALESCE(lap.paid_date, (pm.created_at)::date) AS paid_date,
            meta.payment_branch_ref_number,
            meta.payment_method_code,
            meta.payment_collected_by,
            meta.collection_agent_email,
            meta.collection_branch_code,
            meta.card_last4_digits,
            now() AS view_last_refreshed_time
           FROM ((pm
             LEFT JOIN lap ON ((((pm.mylo_loan_id = (lap.loan_account_id)::uuid) AND ((pm.reference)::text = (lap.payment_reference_id)::text) AND (pm.source = 'mylo'::text)) OR (((pm.reference)::text = (lap.payment_reference_id)::text) AND (pm.source = 'minicash'::text)))))
             LEFT JOIN meta ON ((pm.payment_id = meta.payment_id)))
        )
 SELECT payment_id,
    reference,
    type,
    source,
    status,
    consumer_id,
    mylo_and_minicash_amount,
    collection_fee_amount,
    payment_channel,
    mylo_loan_id,
    mylo_loan_schedule_number,
    mylo_paid_principal,
    mylo_paid_interest,
    mylo_paid_fee,
    mylo_total_amount,
    mylo_partner_name,
    mylo_due_date,
    minicash_order_code,
    minicash_no_of_payment,
    minicash_paid_principal,
    minicash_paid_interest,
    minicash_total_amount,
    minicash_fine_amount,
    minicash_due_date,
    paid_at,
    paid_date,
    payment_branch_ref_number,
    payment_method_code,
    payment_collected_by,
    collection_agent_email,
    collection_branch_code,
    card_last4_digits,
    view_last_refreshed_time
   FROM final_result;


