            lap.paid_units
           FROM loan_management.loan_account_payment lap
        ), meta AS (
         SELECT mv2.payment_id,
            max(
                CASE
                    WHEN (j.key = ANY (ARRAY['reference_number'::text, 'referenceNumber'::text])) THEN j.value
