            t_1.voucher,
            t_1.postingprofile,
            t_1.amountcurcredit,
            t_1.amountcurdebit,
            t_1.accountnum,
            t_1.account_name,
            t_1.account_namealias,
            t_1.customername,
            t_1.pa_sourcecustnum,
            t_1.custgroup,
            t_1.pa_oms_nationalid,
            t_1.pa_rmsstoreid,
            t_1.storeid,
            t_1.storename,
            t_1.tendertype,
            t_1.tenders,
            t_1.paymmode,
            t_1.pa_paymmethodtype,
            t_1.rmspaymentmethod,
            t_1.pa_paymentmethod,
            t_1.transdate,
            t_1.createddatetime,
            t_1.transactiontype,
            t_1.reasoncode,
            t_1.resoncodedescription,
            t_1.offsettxt,
            t_1.txt,
            t_1.pa_rmstrxtypedescription,
            t_1.pa_comment,
            t_1.paymentstatus,
            t_1.payment,
            t_1.pa_rmstranskey,
            t_1.pa_paymentsourcetype,
            t_1.invoice,
            t_1.pa_beneficiary,
            t_1.lta_name,
            t_1.bt_enteredby,
            t_1.lta_createdby,
            t_1.lta_modifiedby,
            t_1.lts_createdby,
            t_1.lts_modifiedby,
            t_1.ledgerdimension,
            t_1.bt_requestno,
            t_1.bttdfulfillmenttype,
            t_1.bttdshippmentid,
            t_1.pa_oms_cardnumber,
            t_1.pa_oms_ordernum,
            t_1.pa_oms_shipmentid,
            t_1.salesorderid,
            t_1.pa_rmssetlementtranskey,
            t_1.pa_oms_integrated,
            t_1.bt_referencenum,
            t_1.bt_installmentnum,
            t_1.displayvalue,
            t_1.recid,
            t_1.party,
            t_1.defaultdimension,
            t_1.pa_oms_enteredby,
            t_1.pa_oms_entrytype,
            t_1.bttdminicashordernum,
            t_1.payinoutpostby,
            t_1.posting,
            t_1.modifieddatetime,
            t_1.dataareaid,
            t_1.recid1,
            t_1.frommylo,
            t_1.bt_mylo_journalreference,
            t_1.bt_mylo_requestnumber,
            t_1.pa_d365paymmode,
            t_1.contact,
            t_1.value,
            t_1.halan,
            t_1.souhoola,
            t_1.visa_bankmisr,
            t_1.mylo,
            t_1.visa_cib,
            COALESCE((NULLIF(regexp_replace((COALESCE(t_1.amountcurcredit, ''::character varying))::text, '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric, (0)::numeric) AS credit_amount,
            COALESCE((NULLIF(regexp_replace((COALESCE(t_1.amountcurdebit, ''::character varying))::text, '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric, (0)::numeric) AS debit_amount
           FROM dbo."Treasury" t_1
        ), treasury_references AS MATERIALIZED (
         SELECT DISTINCT treasury_rows.bt_mylo_journalreference AS payment_reference
           FROM treasury_rows
          WHERE (NULLIF(btrim((treasury_rows.bt_mylo_journalreference)::text), ''::text) IS NOT NULL)
        ), repayment_candidates AS MATERIALIZED (
         SELECT (mvr.reference)::text AS payment_reference,
            mvr.payment_id,
            mvr.consumer_id,
            (mvr.paid_at AT TIME ZONE 'UTC'::text) AS created_at,
            mvr.paid_at,
            mvr.payment_channel,
            mvr.payment_method_code
           FROM (public.mv_repayments_info mvr
             JOIN treasury_references tr ON (((tr.payment_reference)::text = (mvr.reference)::text)))
        ), repayment_latest AS MATERIALIZED (
         SELECT DISTINCT ON (repayment_candidates.payment_reference) repayment_candidates.payment_reference,
            repayment_candidates.consumer_id,
            repayment_candidates.created_at,
            repayment_candidates.payment_channel,
            repayment_candidates.payment_method_code
           FROM repayment_candidates
          ORDER BY repayment_candidates.payment_reference, repayment_candidates.paid_at DESC NULLS LAST, repayment_candidates.payment_id DESC NULLS LAST
        ), repayment_payment_method AS MATERIALIZED (
         SELECT DISTINCT ON (repayment_candidates.payment_reference) repayment_candidates.payment_reference,
            repayment_candidates.payment_method_code
           FROM repayment_candidates
          WHERE (NULLIF(btrim(repayment_candidates.payment_method_code), ''::text) IS NOT NULL)
          ORDER BY repayment_candidates.payment_reference, repayment_candidates.paid_at DESC NULLS LAST, repayment_candidates.payment_id DESC NULLS LAST
        ), repayment_info AS MATERIALIZED (
         SELECT latest.payment_reference,
            latest.consumer_id,
            latest.created_at,
            latest.payment_channel,
            COALESCE(NULLIF(btrim(latest.payment_method_code), ''::text), NULLIF(btrim(method.payment_method_code), ''::text)) AS payment_method_code
           FROM (repayment_latest latest
             LEFT JOIN repayment_payment_method method ON ((method.payment_reference = latest.payment_reference)))
        )
 SELECT t.journalnum AS "Journal Num",
    t.accountnum AS "Account Num",
    t.account_name AS "Account Name",
    t.pa_sourcecustnum AS "Source cust num",
    t.custgroup AS "CUSTGROUP",
    t.pa_oms_nationalid AS "NATIONALID",
    t.storeid AS "Store ID",
    t.storename AS "Store Name",
    t.transdate AS "TRANS DATE",
    t.createddatetime AS "CREATED DATE",
    t.transactiontype AS "Transaction Type",
    t.voucher AS "VOUCHER",
    t.tendertype AS "Tender",
    t.tenders AS "Tenders",
    t.amountcurcredit AS "Credit",
    t.amountcurdebit AS "Debit",
    round((t.credit_amount - t.debit_amount), 0) AS "Balance",
    t.postingprofile AS "Posting Profile",
    t.reasoncode AS "Reason Code",
    t.resoncodedescription AS "Reason Disc",
    t.pa_oms_cardnumber AS "Card Num",
    t.pa_comment AS "Comment",
    t.pa_oms_ordernum AS "Order Num",
    t.pa_oms_shipmentid AS "Shipment ID",
    t.salesorderid AS "Sales ID",
    t.pa_rmssetlementtranskey AS "Setlment Trans",
    t.pa_rmstrxtypedescription AS "TRXTYPE",
    t.lta_name AS "TRX Name",
    t.lta_createdby AS "Created By",
    t.lta_modifiedby AS "Modified By",
    t.bt_enteredby AS "BT ENTEREDBY",
    t.pa_oms_enteredby AS "PA OMS ENTEREDBY",
    t.payinoutpostby AS "PAYINOUTPOSTBY",
    t.bttdminicashordernum AS "BTTDMINICASHORDERNUM",
    t.bt_installmentnum AS "BT INSTALLMENTNUM",
    t.bt_referencenum AS "BT REFERENCENUM",
    t.bt_requestno AS "BT REQUESTNO",
    t.posting AS "POSTING",
    t.frommylo AS "From mylo",
    t.bt_mylo_journalreference AS "mylo journalreference",
    t.bt_mylo_requestnumber AS "mylo requestnumber",
    COALESCE(r.created_at, (t.createddatetime)::timestamp without time zone) AS created_at,
    COALESCE(c.full_name, (NULLIF((t.customername)::text, ''::text))::character varying) AS full_name,
    COALESCE(c.national_id, (NULLIF((t.pa_oms_nationalid)::text, ''::text))::character varying) AS national_id,
    COALESCE(c.phone_number, (NULLIF(btrim((t.contact)::text), ''::text))::character varying) AS phone_number,
    r.payment_channel,
        CASE
            WHEN (NULLIF(btrim((t.bt_mylo_journalreference)::text), ''::text) IS NULL) THEN NULLIF(btrim((t.tenders)::text), ''::text)
            ELSE COALESCE(NULLIF(btrim((t.pa_paymentmethod)::text), ''::text), NULLIF(btrim(r.payment_method_code), ''::text), NULLIF(btrim((t.tenders)::text), ''::text))
        END AS payment_method_code,
        CASE
            WHEN (NULLIF(btrim((t.bt_mylo_journalreference)::text), ''::text) IS NOT NULL) THEN 'MATCHED_TREASURY'::text
            ELSE 'OUTSIDE_TREASURY_SCOPE'::text
        END AS reconciliation_status
   FROM ((treasury_rows t
     LEFT JOIN repayment_info r ON ((r.payment_reference = (t.bt_mylo_journalreference)::text)))
     LEFT JOIN LATERAL ( SELECT consumer.full_name,
            consumer.national_id,
            consumer.phone_number
           FROM public.consumers consumer
          WHERE (consumer.id = r.consumer_id)
         LIMIT 1) c ON (true))
  ORDER BY t.createddatetime, t.journalnum, t.voucher;


