);


--
-- Name: mv_egbank_consumers; Type: MATERIALIZED VIEW; Schema: offloading; Owner: -
--

CREATE MATERIALIZED VIEW offloading.mv_egbank_consumers AS
 WITH latest_scoring_output AS (
         SELECT DISTINCT ON (so_1.consumer_id) so_1.consumer_id,
            GREATEST((so_1.final_net_income / 100), 5000) AS predicted_income
           FROM (_services.scoring_output so_1
             LEFT JOIN public.consumer_user_details cud ON ((so_1.consumer_id = cud.consumer_id)))
          WHERE (so_1.final_net_income > 0)
          ORDER BY so_1.consumer_id, so_1.created_at DESC
        ), latest_iscore AS (
         SELECT DISTINCT ON (iscore.consumer_id) iscore.consumer_id,
            iscore.iscore_score
           FROM public.iscore
          ORDER BY iscore.consumer_id, iscore.created_at DESC
        ), consumer_data AS (
         SELECT c_1.id,
            cud.national_id,
            cud.full_name,
            cms.status_name_en AS marital_status,
            cs.active_since,
            cp.phone_number_e164,
            ca.address_line_1,
            ca.city_id,
            ca.governorate_id,
            ck.job_title AS mylo_job_code,
            ck.job_category AS mylo_job_category_code,
            ck.company_name,
            ck.primary_income AS salary,
            (GREATEST(((EXTRACT(year FROM CURRENT_DATE) - (
                CASE "substring"(TRIM(BOTH FROM cud.national_id), 1, 1)
                    WHEN '2'::text THEN (1900 + ("substring"(TRIM(BOTH FROM cud.national_id), 2, 2))::integer)
                    WHEN '3'::text THEN (2000 + ("substring"(TRIM(BOTH FROM cud.national_id), 2, 2))::integer)
                    ELSE NULL::integer
                END)::numeric) - (22)::numeric), (0)::numeric) * (12)::numeric) AS work_duration
           FROM ((((((public.new_consumers c_1
             JOIN public.consumer_user_details cud ON ((c_1.id = cud.consumer_id)))
             JOIN public.consumer_phone cp ON (((cud.consumer_id = cp.consumer_id) AND (cp.is_primary = true) AND (cp.is_active = true))))
             JOIN ( SELECT ranked_address.consumer_id,
                    ranked_address.address_line_1,
                    ranked_address.governorate_id,
                    ranked_address.city_id
                   FROM ( SELECT ca_1.consumer_id,
                            ca_1.address_line_1,
                            ca_1.governorate_id,
                            ca_1.city_id,
                            row_number() OVER (PARTITION BY ca_1.consumer_id ORDER BY ca_1.updated_at DESC NULLS LAST) AS rn
                           FROM public.consumer_address ca_1
                          WHERE (ca_1.is_primary = true)) ranked_address
                  WHERE (ranked_address.rn = 1)) ca ON ((cud.consumer_id = ca.consumer_id)))
             JOIN public.consumer_kyc ck ON ((cud.consumer_id = ck.consumer_id)))
             JOIN ( SELECT DISTINCT ON (consumer_state.consumer_id) consumer_state.id,
                    consumer_state.consumer_id,
                    consumer_state.state,
                    consumer_state.active_since,
                    consumer_state.created_at,
                    consumer_state.created_by,
                    consumer_state.comment,
                    consumer_state.branch
                   FROM public.consumer_state
                  ORDER BY consumer_state.consumer_id, consumer_state.active_since DESC) cs ON ((cs.consumer_id = c_1.id)))
             JOIN lookup_tables.int_marital_status cms ON (((ck.marital_status)::text = (cms.id)::text)))
        )
 SELECT 127 AS "ProtocolID",
    c.national_id AS "NationalId",
    c.id AS "CompanyCustomerId",
    c.full_name AS "FullNameEN",
    c.full_name AS "FullNameAR",
    COALESCE(msl.marital_status_code, '1'::character varying) AS "MaritalStatus",
    '3'::text AS "EducationLevel",
    NULL::text AS "NID_ISSUANCE_DATE",
    to_char((c.active_since + '1 mon'::interval), 'YYYYMMDD'::text) AS "NIDExpiryDate",
    0 AS "DEPENDENT_RELATIVES",
    0 AS "DEPENDENT_CHILDRENS",
    NULL::text AS "CONTACT_HOME",
    regexp_replace((c.phone_number_e164)::text, '^\+2'::text, ''::text) AS "ContactMobile1",
    NULL::text AS "CONTACT_MOBILE2",
    NULL::text AS "CONTACT_EMAIL1",
    NULL::text AS "CONTACT_EMAIL2",
    c.address_line_1 AS "RESAddress",
    c.city_id AS "MYLO_CITY_ID",
    NULL::text AS "RES_LANDMARK",
    COALESCE(gcl.city_code, 1) AS "RESCity",
    COALESCE(gdl.district_code, 1) AS "RESDistrict",
    '7'::text AS "RESType",
    '1'::text AS "RESOwnershipType",
    NULL::text AS "RES_APPARTMENT_AREA",
    NULL::text AS "RES_CURRENT_YEARS",
    NULL::text AS "RES_PREVIOUS_YEARS",
    NULL::text AS "WRK_COMPANY_ADDRESS",
    COALESCE(9004001) AS "WRKPrivateBusiness",
    to_char((CURRENT_DATE - ((c.work_duration || ' months'::text))::interval), 'YYYYMMDD'::text) AS "WRK_EMPLOYMENT_DATE",
    c.work_duration AS "WRKEmploymentDuration",
    c.company_name AS "WRK_EMPLOYER_NAME",
    NULL::text AS "WRK_EMPLOYER_TYPE",
    '6'::text AS "WRKJobTitle",
    21 AS "WRK_COMPANY_CODE",
    NULL::text AS "WRK_PREVIOUS_EMPLOYER_NAME",
    COALESCE(mejm.egbank_code, mejcm.egbank_code, 1190) AS "WRKPROFESSION",
    COALESCE(wel.experience_level, NULL::integer) AS "WRKExperienceLevel",
    0 AS "WRKISNEWCOMPANY",
    NULL::text AS "WRK_COM_REG_NO",
    NULL::text AS "WRK_COM_REG_CITY",
    NULL::text AS "WRK_COM_REG_DATE",
    NULL::text AS "WRK_TAX_NO",
    NULL::text AS "WRK_TAX_UNIT",
    NULL::text AS "WRK_TAX_DATE",
    '1'::text AS "WRKNegativeTier",
    COALESCE(oms.salary, (c.salary / 100), so.predicted_income, 5000) AS "INCCalculatedMonthlyIncome",
    0 AS "INCAnnualProfit",
    COALESCE(oms.salary, (c.salary / 100), so.predicted_income, 5000) AS "INCNetMonthlyIncome",
    0 AS "INC_NET_ADDITIONAL_INCOME_AMT",
    0 AS "INC_ADDITION_INCOME_SOURCE",
    12 AS "INCAdditionalIncomeFrequency",
    0 AS "INCAnualBonus",
    0 AS "INCADDITIONALMONTHLYVARIABLE",
    0 AS "INCTransferSalary",
    0 AS "AST_HAS_OWNED_ASSET",
    NULL::text AS "AST_CAR_TYPE",
    NULL::text AS "AST_CAR_MODEL",
    NULL::text AS "AST_CAR_MODEL_YEAR",
    NULL::text AS "AST_CAR_PRICE",
    127 AS "SCRProgramType",
    204 AS "SCRSegment",
        CASE
            WHEN ((ccl.credit_limit / 100) < 5000) THEN 20000
            ELSE (ccl.credit_limit / 100)
        END AS "SCRCustomerLimit",
    NULL::text AS "SCRRequestedLimit",
    to_char((c.active_since + '3 years'::interval), 'YYYYMMDD'::text) AS "SCR_CUST_LIMIT_EXP_DATE",
    NULL::text AS "SCR_MONTHLY_COMMITMENT",
    COALESCE(isc.iscore_score, 0) AS "SCR_ISCORE_SCORING",
    NULL::text AS "SCR_ISCORE_FACILITIES",
    'Not available'::text AS "SCR_INSURANCE_DATA",
    'positive'::text AS "IVSInvestigationResults",
    'positive'::text AS "IVSFraud",
    NULL::text AS "IVS_CPV_DATE",
    NULL::text AS "IVS_CPV_NOTES",
    NULL::text AS "IVS_PROFFESION_TITLE",
    NULL::text AS "IVS_PROFFESION_EMPLOYEER",
    NULL::text AS "IVS_RESIDANCE_ADDRESS",
    NULL::text AS "IVS_RESIDANCE_LATITUTE",
    NULL::text AS "IVS_RESIDANCE_LONGTITUE",
    to_char(c.active_since, 'YYYYMMDD'::text) AS "EffectiveDate",
    NULL::text AS "UPDATE_REASON",
    0 AS "AFFECTS_DBR",
    NULL::text AS "SCR_APPROVAL_FINAL_COMMENT",
    to_char(c.active_since, 'YYYYMMDD'::text) AS "CompanyApprovalDate",
    NULL::text AS "ScrAssessmentFinalComment",
    1 AS "ScrBackgroundCheck",
    NULL::text AS "ScrBackgroundCheckComment",
    0 AS "ScrCalculatedDbr",
    NULL::text AS "COMPANY_SERIAL",
    NULL::text AS "CLUB_CODE"
   FROM ((((((((((consumer_data c
     JOIN ( SELECT latest_credit_limits.consumer_id,
            latest_credit_limits.credit_limit
           FROM ( SELECT DISTINCT ON (ccl_1.consumer_id) ccl_1.consumer_id,
                    ccl_1.max_credit_limit AS credit_limit
                   FROM (public.consumer_credit_limits ccl_1
                     JOIN public.consumer_user_details cud ON ((ccl_1.consumer_id = cud.consumer_id)))
                  ORDER BY ccl_1.consumer_id, ccl_1.created_at DESC) latest_credit_limits) ccl ON ((ccl.consumer_id = c.id)))
     LEFT JOIN latest_scoring_output so ON ((so.consumer_id = c.id)))
     LEFT JOIN latest_iscore isc ON ((isc.consumer_id = c.id)))
     LEFT JOIN public.offloading_minicash_salaries oms ON (((oms.national_id)::text = (c.national_id)::text)))
     LEFT JOIN offloading.egbank_marital_status_lookup msl ON (((msl.marital_status_key)::text = (c.marital_status)::text)))
     LEFT JOIN offloading.egbank_governorate_city_lookup gcl ON ((gcl.governorate_id = c.governorate_id)))
     LEFT JOIN offloading.egbank_governorate_district_lookup gdl ON ((gdl.governorate_id = c.governorate_id)))
     LEFT JOIN offloading.egbank_work_experience_lookup wel ON ((((c.work_duration / (12)::numeric) >= (wel.min_years)::numeric) AND ((wel.max_years = 999) OR ((c.work_duration / (12)::numeric) < (wel.max_years)::numeric)))))
     LEFT JOIN offloading.mylo_egbank_job_mapping mejm ON (((mejm.mylo_code)::text = (c.mylo_job_code)::text)))
     LEFT JOIN offloading.mylo_egbank_job_category_mapping mejcm ON (((mejcm.mylo_code)::text = c.mylo_job_category_code)))
  WHERE ((c.work_duration > (0)::numeric) AND ((c.id)::character(36) IN ( SELECT offloading_consumers.consumer_id
           FROM offloading.offloading_consumers)))
  WITH NO DATA;


