--
-- Name: mv_egbank_loans; Type: MATERIALIZED VIEW; Schema: offloading; Owner: -
--

CREATE MATERIALIZED VIEW offloading.mv_egbank_loans AS
 WITH loan_schedules_agg AS (
         SELECT ls_1.loan_account_id AS loan_id,
            (max(ls_1.total_due_units) / 100) AS total_due_units,
            (sum(ls_1.principal_due_units) / (100)::numeric) AS total_principal,
            (sum(ls_1.interest_due_units) / (100)::numeric) AS total_interest,
            ((sum(ls_1.principal_due_units) + sum(ls_1.interest_due_units)) / (100)::numeric) AS total_balance,
            ((sum(ls_1.principal_due_units) - COALESCE(sum(ls_1.principal_paid_units), (0)::numeric)) / (100)::numeric) AS remaining_principal,
            ((sum(ls_1.interest_due_units) - COALESCE(sum(ls_1.interest_paid_units), (0)::numeric)) / (100)::numeric) AS remaining_interest,
            (((sum(ls_1.principal_due_units) - COALESCE(sum(ls_1.principal_paid_units), (0)::numeric)) + (sum(ls_1.interest_due_units) - COALESCE(sum(ls_1.interest_paid_units), (0)::numeric))) / (100)::numeric) AS total_remaining_balance,
            count(*) FILTER (WHERE ((ls_1.total_paid_units = 0) AND (ls_1.canceled = false))) AS unpaid_installments
           FROM (loan_management.loan_account_ammortisation_line_item ls_1
             JOIN loan_management.loan_account l ON (((l.id)::text = (ls_1.loan_account_id)::text)))
          GROUP BY ls_1.loan_account_id
        )
 SELECT mvrl.consumer_id AS "CompanyCustomerId",
    cud.national_id AS "NationalId",
    mvrl.loan_id AS "COMPANY_INVOICE_ID",
    mvrl.total_principal_amount AS "INVOICE_AMOUNT",
    to_char(mvrl.loan_booked_at, 'YYYYMMDD'::text) AS "INVOICE_DATE",
    mvrl.merchant_id AS "MERCHANT_CODE",
    mvrl.merchant_name AS "MERCHANT_NAME",
    to_char(mvrl.loan_booked_at, 'YYYYMMDD'::text) AS "BOOKING_DATE",
    mvrl.loan_admin_fee_amount AS "ADMIN_FEES",
    0 AS "DOWN_PAYMENT",
    ls.total_remaining_balance AS "REQUEST_LOAN_AMOUNT",
    mvrl.annual_interest_percent AS "INTEREST_RATE",
    ls.remaining_principal AS "PRINCIPLE_AMOUNT",
    ls.remaining_interest AS "INTEREST_AMOUNT",
    ls.total_due_units AS "INSTALLMENT_AMOUNT",
    ls.unpaid_installments AS "INSTALLMENTS_COUNT",
    1 AS "PAYMENT_FREQUENCY",
    mvrl.tenor AS "TENOR",
    mvrl.retail_category AS "Category",
    ( SELECT string_agg(replace((item.value ->> 'name'::text), ','::text, ''::text), ', '::text) AS string_agg
           FROM jsonb_array_elements(cb.products) item(value)) AS "Code",
    to_char(mvrl.loan_booked_at, 'YYYYMMDD'::text) AS "Delivery_Date",
    ( SELECT string_agg((item.value ->> 'name'::text), ', '::text) AS string_agg
           FROM jsonb_array_elements(cb.products) item(value)) AS "Description",
    mvrl.total_principal_amount AS "Price",
    1 AS "Quantity",
    ( SELECT string_agg((item.value ->> 'name'::text), ', '::text) AS string_agg
           FROM jsonb_array_elements(cb.products) item(value)) AS "Title"
   FROM (((public.mv_loans_info mvrl
     JOIN public.checkout_baskets cb ON ((((cb.loan_id)::character varying)::text = (mvrl.loan_id)::text)))
     JOIN loan_schedules_agg ls ON (((ls.loan_id)::text = (mvrl.loan_id)::text)))
     JOIN public.consumer_user_details cud ON ((((cud.consumer_id)::character varying)::text = (mvrl.consumer_id)::text)))
  WHERE ((mvrl.loan_batch_status IS NULL) AND ((mvrl.loan_id)::character(36) IN ( SELECT offloading_loans.loan_id
           FROM offloading.offloading_loans)))
  WITH NO DATA;


