--
-- Name: orca_closed_end_evaluations; Type: VIEW; Schema: orca_analytics; Owner: -
--

CREATE VIEW orca_analytics.orca_closed_end_evaluations AS
 SELECT evaluation_id,
    consumer_nid,
    created_at,
    updated_at,
    success,
    error_message,
    ((eligibility_result ->> 'eligible'::text))::boolean AS eligible,
    ((eligibility_result ->> 'fico_score'::text))::integer AS fico_score,
    ((eligibility_result ->> 'current_utilization'::text))::double precision AS current_utilization,
    ((eligibility_result ->> 'avg_3m_utilization'::text))::double precision AS avg_3m_utilization,
    ((eligibility_result ->> 'max_utilization_threshold'::text))::double precision AS max_utilization_threshold,
    COALESCE(((eligibility_result -> 'rejection_reasons'::text) ? 'CSO_CHECK_FAILED'::text), false) AS cso_failed,
    ((revolving_snapshot ->> 'total_used'::text))::double precision AS total_used,
    ((revolving_snapshot ->> 'total_granted_cl'::text))::double precision AS total_granted_cl,
    ((revolving_snapshot ->> 'total_utilization'::text))::double precision AS total_utilization,
    ((revolving_snapshot ->> 'available_capacity'::text))::double precision AS available_capacity,
    ((capacity_result ->> 'max_nfa'::text))::double precision AS max_nfa_piasters,
    (((capacity_result ->> 'max_nfa'::text))::double precision / (100.0)::double precision) AS max_nfa_egp,
    (((capacity_result ->> 'max_nfa'::text))::double precision >= (5000000)::double precision) AS nfa_cap_hit,
    ((capacity_result ->> 'max_nfa'::text) IS NOT NULL) AS capacity_granted
   FROM midas.orca_closed_end_light_evaluation_log;


--
-- Name: orca_closed_end_rejection_reasons; Type: VIEW; Schema: orca_analytics; Owner: -
--

CREATE VIEW orca_analytics.orca_closed_end_rejection_reasons AS
 SELECT log.evaluation_id,
    log.consumer_nid,
    log.created_at,
    reason.rejection_reason
   FROM (midas.orca_closed_end_light_evaluation_log log
     CROSS JOIN LATERAL jsonb_array_elements_text((log.eligibility_result -> 'rejection_reasons'::text)) reason(rejection_reason))
  WHERE (((log.eligibility_result ->> 'eligible'::text) = 'false'::text) AND (jsonb_typeof((log.eligibility_result -> 'rejection_reasons'::text)) = 'array'::text));


--
-- Name: orca_open_end_evaluations; Type: VIEW; Schema: orca_analytics; Owner: -
--

CREATE VIEW orca_analytics.orca_open_end_evaluations AS
 SELECT evaluation_id,
    consumer_nid,
    created_at,
    success,
    error_message,
    iscore_computed,
    rejection_inference_status,
    mri_model_version,
    income_model_version,
    (decision_result ->> 'decision'::text) AS decision,
    (decision_result ->> 'customer_risk_grade'::text) AS customer_risk_grade,
    ((decision_result ->> 'iscore_passed'::text))::boolean AS iscore_passed,
    ((decision_result ->> 'crg_passed'::text))::boolean AS crg_passed,
    ((decision_result ->> 'dti_passed'::text))::boolean AS dti_passed,
    ((mri_result ->> 'mri_score'::text))::double precision AS mri_score,
    (mri_result ->> 'suggested_decision'::text) AS mri_suggested_decision,
    ((dti_result ->> 'dti_pre_granting'::text))::double precision AS dti_pre_granting,
    ((dti_result ->> 'monthly_obligations'::text))::double precision AS monthly_obligations,
    (income_estimation_result ->> 'income_source'::text) AS income_source,
    ((income_estimation_result ->> 'stated_income'::text))::double precision AS stated_income,
    ((income_estimation_result ->> 'estimated_income'::text))::double precision AS estimated_income,
    ((income_estimation_result ->> 'income_used'::text))::double precision AS income_used,
    ((iscore_result ->> 'score'::text))::double precision AS iscore_score,
    ((iscore_result #>> '{consumer_credit_data_instance,fico_score}'::text[]))::integer AS fico_score,
    ((credit_limit_result ->> 'credit_limit'::text))::double precision AS credit_limit_piasters,
    (((credit_limit_result ->> 'credit_limit'::text))::double precision / (100.0)::double precision) AS credit_limit_egp,
    ((credit_limit_result ->> 'disposable_income'::text))::double precision AS disposable_income_egp,
    ((credit_limit_result ->> 'reject_grade'::text))::boolean AS reject_grade
   FROM midas.orca_open_end_full_evaluation_log;


--
-- Name: orca_open_end_raw; Type: VIEW; Schema: orca_analytics; Owner: -
--

CREATE VIEW orca_analytics.orca_open_end_raw AS
 SELECT evaluation_id,
    consumer_nid,
    created_at,
    iscore_computed,
    request_input,
    iscore_result,
    income_estimation_result,
    dti_result,
    mri_result,
    decision_result,
    credit_limit_result,
    mri_model_version,
    income_model_version,
    success,
    error_message,
    version,
    rejection_inference_status
   FROM midas.orca_open_end_full_evaluation_log;


--
-- Name: orca_open_end_rejection_reasons; Type: VIEW; Schema: orca_analytics; Owner: -
--

CREATE VIEW orca_analytics.orca_open_end_rejection_reasons AS
 SELECT log.evaluation_id,
    log.consumer_nid,
    log.created_at,
    (log.decision_result ->> 'customer_risk_grade'::text) AS customer_risk_grade,
    reason.rejection_reason
   FROM (midas.orca_open_end_full_evaluation_log log
     CROSS JOIN LATERAL jsonb_array_elements_text((log.decision_result -> 'rejection_reasons'::text)) reason(rejection_reason))
  WHERE (((log.decision_result ->> 'decision'::text) = 'reject'::text) AND (jsonb_typeof((log.decision_result -> 'rejection_reasons'::text)) = 'array'::text));


