--
-- Name: migrated_customer_partation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.migrated_customer_partation (
    id uuid,
    phone_number character varying(20),
    status character varying(255),
    iam_id character varying(8000),
    full_name character varying(8000),
    first_name character varying(8000),
    last_name character varying(8000),
    national_id character varying(8000),
    job_name character varying(8000),
    work_type character varying(8000),
    company character varying(8000),
    club character varying(8000),
    house_type character varying(8000),
    city character varying(8000),
    district character varying(8000),
    governorate character varying(8000),
    consumer_income numeric(10,2),
    address_description text,
    guarantor_job character varying(8000),
    guarantor_relationship character varying(8000),
    car_year integer,
    address text,
    activated_at timestamp(6) without time zone,
    created_at timestamp(6) without time zone NOT NULL,
    updated_at timestamp(6) without time zone,
    single_payment_day integer,
    origination_channel character varying(8000),
    additional_salary_source text,
    work_phone_number character varying(20),
    home_phone_number character varying(20),
    company_address text,
    national_id_address text,
    classification character varying(8000),
    activated_by_iam_id character varying(8000),
    activation_branch character varying(8000),
    updated_by character varying(100),
    comment text,
    clientid integer,
    age integer,
    age_bucket text,
    gender character varying(10),
    marital_status character varying(10),
    branchname character varying(100),
    activation_branch_adjusted character varying(8000),
    address_adjusted character varying(200),
    new_returning_flag text,
    "Finisher" integer,
    "Pre_Finsher" integer,
    "Running" integer,
    churn_status text,
    credit_limit integer,
    income_bucket text,
    credit_limit_bucket text,
    cl_utl_bucket text,
    available_credit_limit integer,
    utl numeric,
    unified_city text,
    iduuid uuid DEFAULT gen_random_uuid() NOT NULL
)
PARTITION BY RANGE (created_at);


