   FROM auto_views.t_merchant_payments;


--
-- Name: mv_migrated_customer; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_migrated_customer AS
 SELECT DISTINCT id,
    phone_number,
    status,
    iam_id,
    full_name,
    first_name,
    last_name,
    national_id,
    job_name,
    work_type,
    company,
    club,
    house_type,
    city,
    district,
    governorate,
    round(((salary + additional_salary) / (100)::numeric), 2) AS consumer_income,
    address_description,
    guarantor_job,
    guarantor_relationship,
    car_year,
    address,
    activated_at,
    created_at,
    updated_at,
    single_payment_day,
    origination_channel,
    additional_salary_source,
    work_phone_number,
    home_phone_number,
    company_address,
    national_id_address,
    classification,
    activated_by_iam_id,
    activation_branch,
    updated_by,
    comment,
    clientid,
    age,
        CASE
            WHEN (age <= (25)::numeric) THEN '<=25'::text
            WHEN ((age > (25)::numeric) AND (age <= (36)::numeric)) THEN '26-36'::text
            WHEN ((age > (36)::numeric) AND (age <= (50)::numeric)) THEN '37-50'::text
            WHEN ((age > (50)::numeric) AND (age <= (60)::numeric)) THEN '51-60'::text
            ELSE '+60'::text
        END AS age_bucket,
    gender,
        CASE
            WHEN (((marital_status)::text ~~ '%غ%'::text) OR ((marital_status)::text ~~ '%Single%'::text) OR ((marital_status)::text ~~ '%ارمل%'::text) OR ((marital_status)::text ~~ '%مطلق%'::text)) THEN 'Single'::text
            WHEN (((marital_status)::text = ''::text) OR (marital_status IS NULL)) THEN 'N/A'::text
            ELSE 'Married'::text
        END AS marital_status,
    branchname,
    activation_branch_adjusted,
    address_adjusted,
    new_returning_flag,
    "Finisher",
    "Pre_Finsher",
    "Running",
        CASE
            WHEN ("Finisher" = 1) THEN 'Finsher'::text
            WHEN ("Pre_Finsher" = 1) THEN 'Pre_Finsher'::text
            WHEN ("Running" = 1) THEN 'Running'::text
            ELSE 'Non_Transacted'::text
        END AS churn_status,
    max_credit_limit AS credit_limit,
        CASE
            WHEN ((salary + additional_salary) = (0)::numeric) THEN '=0'::text
            WHEN (((salary + additional_salary) > (0)::numeric) AND ((salary + additional_salary) <= (10000)::numeric)) THEN '0-10K'::text
            WHEN (((salary + additional_salary) > (10000)::numeric) AND ((salary + additional_salary) <= (20000)::numeric)) THEN '10-20K'::text
            WHEN (((salary + additional_salary) > (20000)::numeric) AND ((salary + additional_salary) <= (30000)::numeric)) THEN '20-30K'::text
            WHEN (((salary + additional_salary) > (30000)::numeric) AND ((salary + additional_salary) <= (40000)::numeric)) THEN '30-40K'::text
            WHEN (((salary + additional_salary) > (40000)::numeric) AND ((salary + additional_salary) <= (50000)::numeric)) THEN '40-50K'::text
            WHEN (((salary + additional_salary) > (50000)::numeric) AND ((salary + additional_salary) <= (60000)::numeric)) THEN '50-60K'::text
            WHEN (((salary + additional_salary) > (60000)::numeric) AND ((salary + additional_salary) <= (70000)::numeric)) THEN '60-70K'::text
            WHEN (((salary + additional_salary) > (70000)::numeric) AND ((salary + additional_salary) <= (80000)::numeric)) THEN '70-80K'::text
            WHEN (((salary + additional_salary) > (80000)::numeric) AND ((salary + additional_salary) <= (90000)::numeric)) THEN '80-90K'::text
            WHEN (((salary + additional_salary) > (90000)::numeric) AND ((salary + additional_salary) <= (100000)::numeric)) THEN '90-100K'::text
            WHEN ((salary + additional_salary) > (100000)::numeric) THEN '>100K'::text
            ELSE ((salary + additional_salary))::text
        END AS income_bucket,
        CASE
            WHEN (max_credit_limit <= 0) THEN '=0'::text
            WHEN ((max_credit_limit > 0) AND (max_credit_limit <= 20000)) THEN '0-20K'::text
            WHEN ((max_credit_limit > 20000) AND (max_credit_limit <= 40000)) THEN '20-40K'::text
            WHEN ((max_credit_limit > 40000) AND (max_credit_limit <= 60000)) THEN '40-60K'::text
            WHEN ((max_credit_limit > 60000) AND (max_credit_limit <= 80000)) THEN '60-80K'::text
            WHEN ((max_credit_limit > 80000) AND (max_credit_limit <= 100000)) THEN '80-100K'::text
            WHEN ((max_credit_limit > 100000) AND (max_credit_limit <= 200000)) THEN '100-200K'::text
            WHEN ((max_credit_limit > 200000) AND (max_credit_limit <= 300000)) THEN '200-300K'::text
            WHEN (max_credit_limit > 300000) THEN '>300K'::text
            ELSE '>=100K'::text
        END AS credit_limit_bucket,
        CASE
            WHEN (utl = (0)::numeric) THEN '=0%'::text
            WHEN ((utl > (0)::numeric) AND (utl <= (20)::numeric)) THEN '0%-20%'::text
            WHEN ((utl > (20)::numeric) AND (utl <= (40)::numeric)) THEN '20%-40%'::text
            WHEN ((utl > (40)::numeric) AND (utl <= (60)::numeric)) THEN '40%-60%'::text
            WHEN ((utl > (60)::numeric) AND (utl <= (80)::numeric)) THEN '60%-80%'::text
            WHEN ((utl > (80)::numeric) AND (utl <= (100)::numeric)) THEN '80%-100%'::text
            ELSE '=0%'::text
        END AS cl_utl_bucket,
    available_credit_limit,
    utl,
    bran_unified_city AS unified_city
   FROM ( SELECT DISTINCT c.id,
            c.phone_number,
            c.status,
            c.iam_id,
            c.full_name,
            c.first_name,
            c.last_name,
            c.national_id,
            c.job_name,
            c.work_type,
            c.company,
            c.club,
            c.house_type,
            c.city,
            c.district,
            c.governorate,
            COALESCE(c.salary, (0)::numeric) AS salary,
            COALESCE(c.additional_salary, (0)::numeric) AS additional_salary,
            c.address_description,
            c.guarantor_job,
            c.guarantor_relationship,
            c.car_year,
            c.marital_status,
            c.address,
            c.activated_at,
            c.created_at,
            c.updated_at,
            c.single_payment_day,
            c.origination_channel,
            c.additional_salary_source,
            c.work_phone_number,
            c.home_phone_number,
            c.company_address,
            c.national_id_address,
            c.classification,
            c.activated_by_iam_id,
            c.activation_branch,
            c.updated_by,
            c.comment,
            a_1."Finisher",
            a_1."Pre_Finsher",
            a_1."Running",
            cs.clientid,
            bran.unified_city AS bran_unified_city,
            (COALESCE(cc.max_credit_limit, 0) / 100) AS max_credit_limit,
            (COALESCE(cc.available_credit_limit, 0) / 100) AS available_credit_limit,
            COALESCE(cc.utl, (0)::numeric) AS utl,
            EXTRACT(year FROM age((to_date(((((
                CASE
                    WHEN ((SUBSTRING(c.national_id FROM 2 FOR 2))::integer >= 30) THEN ('19'::text || SUBSTRING(c.national_id FROM 2 FOR 2))
                    ELSE ('20'::text || SUBSTRING(c.national_id FROM 2 FOR 2))
                END || '-'::text) ||
                CASE
                    WHEN (((SUBSTRING(c.national_id FROM 4 FOR 2))::integer >= 1) AND ((SUBSTRING(c.national_id FROM 4 FOR 2))::integer <= 12)) THEN SUBSTRING(c.national_id FROM 4 FOR 2)
                    ELSE '01'::text
                END) || '-'::text) ||
                CASE
                    WHEN (((SUBSTRING(c.national_id FROM 6 FOR 2))::integer >= 1) AND ((SUBSTRING(c.national_id FROM 6 FOR 2))::integer <= 31)) THEN SUBSTRING(c.national_id FROM 6 FOR 2)
                    ELSE '01'::text
                END), 'YYYY-MM-DD'::text))::timestamp with time zone)) AS age,
                CASE
                    WHEN (SUBSTRING(c.national_id FROM (length((c.national_id)::text) - 1) FOR 1) = ANY (ARRAY['1'::text, '3'::text, '5'::text, '7'::text, '9'::text])) THEN 'Male'::text
                    ELSE 'Female'::text
                END AS gender,
            cs.branchname,
                CASE
                    WHEN ((c.activation_branch IS NULL) OR ((c.activation_branch)::text = ''::text)) THEN cs.branchname
                    WHEN ((c.created_at >= '2024-01-01 00:00:00'::timestamp without time zone) AND (c.created_at <= '2024-09-04 00:00:00'::timestamp without time zone)) THEN 'Asyut'::character varying
                    ELSE c.activation_branch
                END AS activation_branch_adjusted,
                CASE
                    WHEN (c.address ~~ '%ايوط%'::text) THEN 'Asyut'::text
                    WHEN (c.address ~~ '%سوهاج%'::text) THEN 'Sohag'::text
                    WHEN (c.address ~~ '%نجع%'::text) THEN 'Nagaa Hamadi'::text
                    WHEN (c.address ~~ '%الفيوم%'::text) THEN 'Faiyum'::text
                    WHEN (c.address ~~ '%قنا%'::text) THEN 'Qena'::text
                    WHEN (c.address ~~ '%بني%'::text) THEN 'Beni Suef'::text
                    WHEN ((c.created_at >= '2024-01-01 00:00:00'::timestamp without time zone) AND (c.created_at <= '2024-09-04 00:00:00'::timestamp without time zone)) THEN 'Asyut'::text
                    ELSE 'Asyut'::text
                END AS address_adjusted,
                CASE
                    WHEN ((abs(EXTRACT(day FROM ((cs.registerdate)::timestamp without time zone - c.created_at))) < (1)::numeric) OR ((c.origination_channel)::text = 'mylo'::text)) THEN 'MCN'::text
                    ELSE 'MCR'::text
                END AS new_returning_flag
           FROM ((((public.consumers c
             LEFT JOIN ( SELECT cs_1.clientid,
                    cs_1.registerdate,
                    cs_1.ssn,
                    cs_1.branchname
                   FROM public.dim_clients cs_1
                  WHERE ((cs_1.runningorders >= 1) OR ((cs_1.runningorders = 0) AND (cs_1.finishedorders >= 1) AND (cs_1.monthssincelastpayment <= 12)) OR ((cs_1.runningorders = 0) AND (cs_1.finishedorders = 0) AND (cs_1.maxcreditlimit >= (100)::double precision) AND (cs_1.monthssincelastregister <= 12)))) cs ON ((TRIM(BOTH FROM c.national_id) = TRIM(BOTH FROM cs.ssn))))
             LEFT JOIN ( SELECT COALESCE(
                        CASE
                            WHEN (l.max_credit_limit = 0) THEN NULL::numeric
                            ELSE round((((((l.max_credit_limit - l.available_credit_limit))::numeric * 1.0) / (l.max_credit_limit)::numeric) * (100)::numeric), 0)
                        END, (0)::numeric) AS utl,
                    l.max_credit_limit,
                    l.available_credit_limit,
                    l.consumer_id
                   FROM public.consumer_credit_limits l
                  WHERE ((l.active_since, l.consumer_id) IN ( SELECT max(consumer_credit_limits.active_since) AS max,
                            consumer_credit_limits.consumer_id
                           FROM public.consumer_credit_limits
                          GROUP BY consumer_credit_limits.consumer_id))) cc ON ((cc.consumer_id = c.id)))
             LEFT JOIN ( SELECT DISTINCT cb.consumer_id,
                        CASE
                            WHEN (sum(
                            CASE
                                WHEN (ls.paid_date IS NULL) THEN 1
                                ELSE 0
                            END) = 0) THEN 1
                            ELSE 0
                        END AS "Finisher",
                        CASE
                            WHEN (sum(
                            CASE
                                WHEN (ls.paid_date IS NULL) THEN 1
                                ELSE 0
                            END) <= 2) THEN 1
                            ELSE 0
                        END AS "Pre_Finsher",
                        CASE
                            WHEN (sum(
                            CASE
                                WHEN (ls.paid_date IS NULL) THEN 1
                                ELSE 0
                            END) > 2) THEN 1
                            ELSE 0
                        END AS "Running"
                   FROM (public.loan_schedule ls
                     LEFT JOIN public.checkout_baskets cb ON ((cb.loan_id = (ls.loan_id)::uuid)))
                  WHERE ((cb.status)::text = 'LOAN_ACTIVATED'::text)
                  GROUP BY cb.consumer_id) a_1 ON ((a_1.consumer_id = c.id)))
             LEFT JOIN public.branches bran ON ((NOT (bran.activation_branch_adjusted IS DISTINCT FROM (
                CASE
                    WHEN ((c.activation_branch IS NULL) OR ((c.activation_branch)::text = ''::text)) THEN cs.branchname
                    WHEN ((c.created_at >= '2024-01-01 00:00:00'::timestamp without time zone) AND (c.created_at <= '2024-09-04 00:00:00'::timestamp without time zone)) THEN 'Asyut'::character varying
                    ELSE c.activation_branch
                END)::text))))) a
  WHERE ((status)::text = 'ACTIVE'::text)
  WITH NO DATA;


--
-- Name: mv_reporting_finance; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_reporting_finance AS
 WITH active_loans_month_year_cte AS (
         SELECT DISTINCT l.id AS loan_id,
            ((date_trunc('week'::text, ((l.booked_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text)) - '1 day'::interval))::date AS week_start
           FROM (((public.loan l
             JOIN public.loan_status active_ls ON ((((l.id)::text = (active_ls.loan_id)::text) AND ((active_ls.status)::text = 'ACTIVE'::text))))
             LEFT JOIN public.loan_status cancelled_ls ON ((((l.id)::text = (cancelled_ls.loan_id)::text) AND ((cancelled_ls.status)::text = 'CANCELLED'::text))))
             LEFT JOIN public.loan_status early_ls ON ((((l.id)::text = (early_ls.loan_id)::text) AND ((early_ls.status)::text = 'EARLY_SETTLED'::text))))
          WHERE ((cancelled_ls.created_at IS NULL) AND (active_ls.created_at IS NOT NULL))
        ), loans_booked_cte AS (
         SELECT ("substring"((co.tenure)::text, '^[0-9]+'::text))::integer AS tenor,
            cte.week_start,
            sum((((principal_journal.amount)::double precision / (100)::double precision) + ((co.down_payment)::double precision / (100)::double precision))) AS total_basket_value,
            sum(((co.down_payment)::double precision / (100)::double precision)) AS total_loan_downpayment,
            sum(((principal_journal.amount)::double precision / (100)::double precision)) AS total_loan_financed_amount,
            sum(((interest_journal.amount)::double precision / (100)::double precision)) AS total_loan_expected_interest_amount
           FROM (((((active_loans_month_year_cte cte
             JOIN public.loan l ON (((l.id)::text = (cte.loan_id)::text)))
             JOIN public.checkout_baskets cb ON ((((cb.loan_id)::text = (l.id)::text) AND ((cb.status)::text = 'LOAN_ACTIVATED'::text))))
             JOIN public.commercial_offer co ON (((cb.selected_commercial_offer_id)::text = (co.id)::text)))
             JOIN public.journal principal_journal ON ((((l.id)::text = (principal_journal.loan_id)::text) AND ((principal_journal.account)::text = 'MurabhaPrincipalReceivable'::text) AND ((principal_journal.direction)::text = 'DEBIT'::text))))
             JOIN public.journal interest_journal ON ((((l.id)::text = (interest_journal.loan_id)::text) AND ((interest_journal.account)::text = 'MurabhaInterestReceivable'::text) AND ((interest_journal.direction)::text = 'DEBIT'::text))))
          GROUP BY ("substring"((co.tenure)::text, '^[0-9]+'::text))::integer, cte.week_start
          ORDER BY ("substring"((co.tenure)::text, '^[0-9]+'::text))::integer
        ), net_total_loan_financed_amount_cte AS (
         SELECT loans_booked_cte.week_start,
            sum(loans_booked_cte.total_loan_financed_amount) AS net_total_loan_financed_amount
           FROM loans_booked_cte
          GROUP BY loans_booked_cte.week_start
        ), annualized_interest_cte AS (
         SELECT loans_booked_cte.tenor,
            loans_booked_cte.week_start,
            loans_booked_cte.total_basket_value,
            loans_booked_cte.total_loan_downpayment,
            loans_booked_cte.total_loan_financed_amount,
            loans_booked_cte.total_loan_expected_interest_amount,
            round((((loans_booked_cte.total_loan_expected_interest_amount / (loans_booked_cte.tenor)::double precision) * (12)::double precision))::numeric, 2) AS annualised_interest
           FROM loans_booked_cte
        ), flat_apr_cte AS (
         SELECT annualized_interest_cte.tenor,
            annualized_interest_cte.week_start,
            annualized_interest_cte.total_basket_value,
            annualized_interest_cte.total_loan_downpayment,
            annualized_interest_cte.total_loan_financed_amount,
            annualized_interest_cte.total_loan_expected_interest_amount,
            annualized_interest_cte.annualised_interest,
            round(((((annualized_interest_cte.annualised_interest)::double precision / annualized_interest_cte.total_loan_financed_amount) * (100)::double precision))::numeric, 2) AS flat_apr_percent
           FROM annualized_interest_cte
        ), lifetime_flat_apr_cte AS (
         SELECT flat_apr_cte.tenor,
            flat_apr_cte.week_start,
            flat_apr_cte.total_basket_value,
            flat_apr_cte.total_loan_downpayment,
            flat_apr_cte.total_loan_financed_amount,
            flat_apr_cte.total_loan_expected_interest_amount,
            flat_apr_cte.annualised_interest,
            flat_apr_cte.flat_apr_percent,
            round(((((flat_apr_cte.flat_apr_percent)::double precision / (12)::double precision) * (flat_apr_cte.tenor)::double precision))::numeric, 2) AS lifetime_flat_apr_percent
           FROM flat_apr_cte
        ), portfolio_weight_cte AS (
         SELECT lbc.tenor,
            lbc.week_start,
            lbc.total_basket_value,
            lbc.total_loan_downpayment,
            lbc.total_loan_financed_amount,
            lbc.total_loan_expected_interest_amount,
            lbc.annualised_interest,
            lbc.flat_apr_percent,
            lbc.lifetime_flat_apr_percent,
            round((((lbc.total_loan_financed_amount / cf.net_total_loan_financed_amount) * (100)::double precision))::numeric, 2) AS portfolio_weight_percent
           FROM (lifetime_flat_apr_cte lbc
             JOIN net_total_loan_financed_amount_cte cf ON ((lbc.week_start = cf.week_start)))
        ), weighted_flat_apr_cte AS (
         SELECT portfolio_weight_cte.tenor,
            portfolio_weight_cte.week_start,
            portfolio_weight_cte.total_basket_value,
            portfolio_weight_cte.total_loan_downpayment,
            portfolio_weight_cte.total_loan_financed_amount,
            portfolio_weight_cte.total_loan_expected_interest_amount,
            portfolio_weight_cte.annualised_interest,
            portfolio_weight_cte.flat_apr_percent,
            portfolio_weight_cte.lifetime_flat_apr_percent,
            portfolio_weight_cte.portfolio_weight_percent,
            round((((portfolio_weight_cte.flat_apr_percent / (100)::numeric) * (portfolio_weight_cte.portfolio_weight_percent / (100)::numeric)) * (100)::numeric), 2) AS weighted_flat_apr_percent
           FROM portfolio_weight_cte
        ), weighted_avg_tenor_cte AS (
         SELECT weighted_flat_apr_cte.tenor,
            weighted_flat_apr_cte.week_start,
            weighted_flat_apr_cte.total_basket_value,
            weighted_flat_apr_cte.total_loan_downpayment,
            weighted_flat_apr_cte.total_loan_financed_amount,
            weighted_flat_apr_cte.total_loan_expected_interest_amount,
            weighted_flat_apr_cte.annualised_interest,
            weighted_flat_apr_cte.flat_apr_percent,
            weighted_flat_apr_cte.lifetime_flat_apr_percent,
            weighted_flat_apr_cte.portfolio_weight_percent,
            weighted_flat_apr_cte.weighted_flat_apr_percent,
            round(((weighted_flat_apr_cte.tenor)::numeric * (weighted_flat_apr_cte.portfolio_weight_percent / (100)::numeric)), 2) AS weighted_average_tenor
           FROM weighted_flat_apr_cte
        ), monthly_installments_cte AS (
         SELECT weighted_avg_tenor_cte.tenor,
            weighted_avg_tenor_cte.week_start,
            weighted_avg_tenor_cte.total_basket_value,
            weighted_avg_tenor_cte.total_loan_downpayment,
            weighted_avg_tenor_cte.total_loan_financed_amount,
            weighted_avg_tenor_cte.total_loan_expected_interest_amount,
            weighted_avg_tenor_cte.annualised_interest,
            weighted_avg_tenor_cte.flat_apr_percent,
            weighted_avg_tenor_cte.lifetime_flat_apr_percent,
            weighted_avg_tenor_cte.portfolio_weight_percent,
            weighted_avg_tenor_cte.weighted_flat_apr_percent,
            weighted_avg_tenor_cte.weighted_average_tenor,
            round(((weighted_avg_tenor_cte.total_loan_financed_amount / (weighted_avg_tenor_cte.tenor)::double precision) + (((weighted_avg_tenor_cte.total_loan_financed_amount * (((weighted_avg_tenor_cte.lifetime_flat_apr_percent / (100)::numeric) / (weighted_avg_tenor_cte.tenor)::numeric))::double precision))::numeric)::double precision)) AS monthly_instalments
           FROM weighted_avg_tenor_cte
        ), reducing_apr_cte AS (
         SELECT monthly_installments_cte.tenor,
            monthly_installments_cte.week_start,
            monthly_installments_cte.total_basket_value,
            monthly_installments_cte.total_loan_downpayment,
            monthly_installments_cte.total_loan_financed_amount,
            monthly_installments_cte.total_loan_expected_interest_amount,
            monthly_installments_cte.annualised_interest,
            monthly_installments_cte.flat_apr_percent,
            monthly_installments_cte.lifetime_flat_apr_percent,
            monthly_installments_cte.portfolio_weight_percent,
            monthly_installments_cte.weighted_flat_apr_percent,
            monthly_installments_cte.weighted_average_tenor,
            monthly_installments_cte.monthly_instalments,
            round((public.calculate_rate(tenor_months => monthly_installments_cte.tenor, monthly_installment => (monthly_installments_cte.monthly_instalments)::numeric, total_financed_amount => (monthly_installments_cte.total_loan_financed_amount)::numeric) * (100)::numeric), 2) AS reducing_apr_percent
           FROM monthly_installments_cte
        ), average_weighted_reducing_apr_cte AS (
         SELECT reducing_apr_cte.tenor,
            reducing_apr_cte.week_start,
            reducing_apr_cte.total_basket_value,
            reducing_apr_cte.total_loan_downpayment,
            reducing_apr_cte.total_loan_financed_amount,
            reducing_apr_cte.total_loan_expected_interest_amount,
            reducing_apr_cte.annualised_interest,
            reducing_apr_cte.flat_apr_percent,
            reducing_apr_cte.lifetime_flat_apr_percent,
            reducing_apr_cte.portfolio_weight_percent,
            reducing_apr_cte.weighted_flat_apr_percent,
            reducing_apr_cte.weighted_average_tenor,
            reducing_apr_cte.monthly_instalments,
            reducing_apr_cte.reducing_apr_percent,
            round((((reducing_apr_cte.reducing_apr_percent / (100)::numeric) * (reducing_apr_cte.portfolio_weight_percent / (100)::numeric)) * (100)::numeric), 2) AS weighted_reducing_apr_percent
           FROM reducing_apr_cte
        )
 SELECT tenor,
    week_start,
    total_basket_value,
    total_loan_downpayment,
    total_loan_financed_amount,
    total_loan_expected_interest_amount,
    annualised_interest,
    flat_apr_percent,
    lifetime_flat_apr_percent,
    portfolio_weight_percent,
    weighted_flat_apr_percent,
    weighted_average_tenor,
    monthly_instalments,
    reducing_apr_percent,
    weighted_reducing_apr_percent
   FROM average_weighted_reducing_apr_cte
  WITH NO DATA;


--
-- Name: mv_reporting_finance_table; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mv_reporting_finance_table (
    tenor integer,
    week_start date,
    total_basket_value double precision,
    total_loan_downpayment double precision,
    total_loan_financed_amount double precision,
    total_loan_expected_interest_amount double precision,
    annualised_interest numeric,
    flat_apr_percent numeric,
    lifetime_flat_apr_percent numeric,
    portfolio_weight_percent numeric,
    weighted_flat_apr_percent numeric,
    weighted_average_tenor numeric,
    monthly_instalments double precision,
    reducing_apr_percent numeric,
    weighted_reducing_apr_percent numeric
);


--
-- Name: mv_rescheduling_performance; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_rescheduling_performance AS
 WITH schedules_grouped_by_created_date AS (
         SELECT laali.loan_account_id,
            la.borrower_id AS consumer_id,
            min(laali.created_at) AS activation_schedules_date,
            max(laali.created_at) AS current_schedules_date
           FROM ((loan_management.loan_account_ammortisation_line_item laali
             JOIN loan_management.loan_account_reschedule_logs logs ON (((logs.loan_account_id)::text = (laali.loan_account_id)::text)))
             JOIN loan_management.loan_account la ON (((la.id)::text = (laali.loan_account_id)::text)))
          WHERE (((la.state)::text <> 'CLOSED'::text) AND (NOT ((la.id)::text IN ( SELECT financial_requests.entity_id
                   FROM public.financial_requests
                  WHERE ((financial_requests.type)::text = 'UNADVISED_POSTPONEMENT'::text)))))
          GROUP BY laali.loan_account_id, la.borrower_id
        ), activation_schedules_cancellation AS (
         SELECT DISTINCT ON (laali.loan_account_id) laali.loan_account_id,
            laali.canceled_at AS activation_schedules_canceled_at,
            round(((((now())::date - (laali.canceled_at)::date))::real / (30)::double precision)) AS months_since_activation_schedules_canceled_at
           FROM (loan_management.loan_account_ammortisation_line_item laali
             JOIN schedules_grouped_by_created_date sdates ON ((((sdates.loan_account_id)::text = (laali.loan_account_id)::text) AND (laali.created_at = sdates.activation_schedules_date) AND (laali.canceled_at IS NOT NULL))))
          ORDER BY laali.loan_account_id, laali.canceled_at
        ), consumer_activation_cancellation AS (
         SELECT sdates.consumer_id,
            min(ascancel.activation_schedules_canceled_at) AS activation_schedules_canceled_at,
            round(((((now())::date - (min(ascancel.activation_schedules_canceled_at))::date))::real / (30)::double precision)) AS months_since_activation_schedules_canceled_at
           FROM (activation_schedules_cancellation ascancel
             JOIN schedules_grouped_by_created_date sdates ON (((sdates.loan_account_id)::text = (ascancel.loan_account_id)::text)))
          GROUP BY sdates.consumer_id
        ), dued_activation_schedules AS (
         SELECT laali.loan_account_id,
            sdates.consumer_id,
            laali.line_item_sequence,
            laali.installment_due_date,
            laali.total_due_units,
            laali.total_paid_units,
            laali.canceled,
            laali.canceled_reason,
            laali.created_at,
            ascancel.activation_schedules_canceled_at,
            ascancel.months_since_activation_schedules_canceled_at
           FROM ((loan_management.loan_account_ammortisation_line_item laali
             JOIN schedules_grouped_by_created_date sdates ON ((((sdates.loan_account_id)::text = (laali.loan_account_id)::text) AND (sdates.activation_schedules_date = laali.created_at))))
             JOIN activation_schedules_cancellation ascancel ON (((ascancel.loan_account_id)::text = (laali.loan_account_id)::text)))
          WHERE ((laali.installment_due_date < ascancel.activation_schedules_canceled_at) AND ((NOT laali.canceled) OR ((laali.canceled_reason)::text = ANY ((ARRAY['Rescheduled'::character varying, 'Postponed'::character varying])::text[]))) AND (laali.created_at = sdates.activation_schedules_date))
        ), dued_current_schedules AS (
         SELECT laali.loan_account_id,
            sdates.consumer_id,
            laali.line_item_sequence,
            laali.installment_due_date,
            laali.total_due_units,
            laali.total_paid_units,
            laali.canceled,
            laali.created_at
           FROM (loan_management.loan_account_ammortisation_line_item laali
             JOIN schedules_grouped_by_created_date sdates ON ((((sdates.loan_account_id)::text = (laali.loan_account_id)::text) AND (sdates.current_schedules_date = laali.created_at))))
          WHERE (((laali.installment_due_date < now()) AND (NOT laali.canceled)) OR ((laali.installment_due_date > now()) AND (NOT laali.canceled) AND (laali.total_paid_units > 0)))
        ), activation_schdules_metrics AS (
         SELECT agg.consumer_id,
            agg.payment_percentage,
            agg.payment_count_percentage,
            agg.max_dpd_days
           FROM ( SELECT dued_activation_schedules.consumer_id,
                    round(((sum(dued_activation_schedules.total_paid_units) / NULLIF(sum(dued_activation_schedules.total_due_units), (0)::numeric)) * (100)::numeric), 2) AS payment_percentage,
                    round((((count(*) FILTER (WHERE (dued_activation_schedules.total_paid_units > 0)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 2) AS payment_count_percentage,
                    COALESCE(max(((dued_activation_schedules.activation_schedules_canceled_at)::date - (dued_activation_schedules.installment_due_date)::date)) FILTER (WHERE (dued_activation_schedules.total_paid_units < dued_activation_schedules.total_due_units)), 0) AS max_dpd_days
                   FROM dued_activation_schedules
                  GROUP BY dued_activation_schedules.consumer_id) agg
        ), current_schedule_metrics AS (
         SELECT agg.consumer_id,
            agg.payment_percentage,
            agg.payment_count_percentage,
            agg.max_dpd_days
           FROM ( SELECT dued_current_schedules.consumer_id,
                    round(((sum(dued_current_schedules.total_paid_units) / NULLIF(sum(dued_current_schedules.total_due_units), (0)::numeric)) * (100)::numeric), 2) AS payment_percentage,
                    round((((count(*) FILTER (WHERE (dued_current_schedules.total_paid_units > 0)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 2) AS payment_count_percentage,
                    COALESCE(max(((now())::date - (dued_current_schedules.installment_due_date)::date)) FILTER (WHERE (dued_current_schedules.total_paid_units < dued_current_schedules.total_due_units)), 0) AS max_dpd_days
                   FROM dued_current_schedules
                  GROUP BY dued_current_schedules.consumer_id) agg
        ), consumers AS (
         SELECT DISTINCT schedules_grouped_by_created_date.consumer_id
           FROM schedules_grouped_by_created_date
        ), stats AS (
         SELECT c.consumer_id,
            cac.months_since_activation_schedules_canceled_at,
            asm.payment_percentage AS activation_schedules_payment_percentage,
            asm.payment_count_percentage AS activation_schedules_payment_count_percentage,
            asm.max_dpd_days AS activation_schedules_dpd_days,
            csm.payment_percentage AS current_schedules_payment_percentage,
            csm.payment_count_percentage AS current_schedules_payment_count_percentage,
            csm.max_dpd_days AS current_schedules_dpd_days
           FROM (((consumers c
             LEFT JOIN consumer_activation_cancellation cac ON (((cac.consumer_id)::text = (c.consumer_id)::text)))
             LEFT JOIN activation_schdules_metrics asm ON (((asm.consumer_id)::text = (c.consumer_id)::text)))
             LEFT JOIN current_schedule_metrics csm ON (((csm.consumer_id)::text = (c.consumer_id)::text)))
          WHERE ((csm.max_dpd_days IS NOT NULL) AND (asm.max_dpd_days IS NOT NULL))
        ), aggregated_stats AS (
         SELECT (stats.months_since_activation_schedules_canceled_at || '_Months'::text) AS rescheduled_since,
            count(*) AS consumer_count,
            round(avg(stats.activation_schedules_payment_percentage), 2) AS avg_before_rescheduling_payment_percentage,
            round(avg(stats.current_schedules_payment_percentage), 2) AS avg_current_payment_percentage,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 0) AND (stats.activation_schedules_dpd_days <= 29))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_0_30_pct,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 30) AND (stats.activation_schedules_dpd_days <= 59))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_30_60_pct,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 60) AND (stats.activation_schedules_dpd_days <= 89))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_60_90_pct,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 90) AND (stats.activation_schedules_dpd_days <= 119))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_90_120_pct,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 120) AND (stats.activation_schedules_dpd_days <= 149))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_120_150_pct,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 150) AND (stats.activation_schedules_dpd_days <= 179))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_150_180_pct,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 180) AND (stats.activation_schedules_dpd_days <= 209))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_180_210_pct,
            round((((count(*) FILTER (WHERE (stats.activation_schedules_dpd_days >= 210)))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_210_plus_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 0) AND (stats.current_schedules_dpd_days <= 29))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_0_30_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 30) AND (stats.current_schedules_dpd_days <= 59))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_30_60_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 60) AND (stats.current_schedules_dpd_days <= 89))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_60_90_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 90) AND (stats.current_schedules_dpd_days <= 119))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_90_120_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 120) AND (stats.current_schedules_dpd_days <= 149))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_120_150_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 150) AND (stats.current_schedules_dpd_days <= 179))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_150_180_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 180) AND (stats.current_schedules_dpd_days <= 209))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_180_210_pct,
            round((((count(*) FILTER (WHERE (stats.current_schedules_dpd_days >= 210)))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_210_plus_pct
           FROM stats
          GROUP BY stats.months_since_activation_schedules_canceled_at
        UNION ALL
         SELECT 'All'::text AS rescheduled_since,
            count(*) AS consumer_count,
            round(avg(stats.activation_schedules_payment_percentage), 2) AS before_rescheduling_payment_percentage,
            round(avg(stats.current_schedules_payment_percentage), 2) AS avg_current_payment_percentage,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 0) AND (stats.activation_schedules_dpd_days <= 29))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_0_30_pct,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 30) AND (stats.activation_schedules_dpd_days <= 59))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_30_60_pct,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 60) AND (stats.activation_schedules_dpd_days <= 89))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_60_90_pct,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 90) AND (stats.activation_schedules_dpd_days <= 119))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_90_120_pct,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 120) AND (stats.activation_schedules_dpd_days <= 149))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_120_150_pct,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 150) AND (stats.activation_schedules_dpd_days <= 179))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_150_180_pct,
            round((((count(*) FILTER (WHERE ((stats.activation_schedules_dpd_days >= 180) AND (stats.activation_schedules_dpd_days <= 209))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_180_210_pct,
            round((((count(*) FILTER (WHERE (stats.activation_schedules_dpd_days >= 210)))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS before_rescheduling_dpd_210_plus_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 0) AND (stats.current_schedules_dpd_days <= 29))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_0_30_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 30) AND (stats.current_schedules_dpd_days <= 59))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_30_60_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 60) AND (stats.current_schedules_dpd_days <= 89))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_60_90_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 90) AND (stats.current_schedules_dpd_days <= 119))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_90_120_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 120) AND (stats.current_schedules_dpd_days <= 149))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_120_150_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 150) AND (stats.current_schedules_dpd_days <= 179))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_150_180_pct,
            round((((count(*) FILTER (WHERE ((stats.current_schedules_dpd_days >= 180) AND (stats.current_schedules_dpd_days <= 209))))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_180_210_pct,
            round((((count(*) FILTER (WHERE (stats.current_schedules_dpd_days >= 210)))::numeric / (count(*))::numeric) * (100)::numeric), 2) AS current_dpd_210_plus_pct
           FROM stats
        )
 SELECT rescheduled_since,
    consumer_count,
    avg_before_rescheduling_payment_percentage,
    avg_current_payment_percentage,
    before_rescheduling_dpd_0_30_pct,
    before_rescheduling_dpd_30_60_pct,
    before_rescheduling_dpd_60_90_pct,
    before_rescheduling_dpd_90_120_pct,
    before_rescheduling_dpd_120_150_pct,
    before_rescheduling_dpd_150_180_pct,
    before_rescheduling_dpd_180_210_pct,
    before_rescheduling_dpd_210_plus_pct,
    current_dpd_0_30_pct,
    current_dpd_30_60_pct,
    current_dpd_60_90_pct,
    current_dpd_90_120_pct,
    current_dpd_120_150_pct,
    current_dpd_150_180_pct,
    current_dpd_180_210_pct,
    current_dpd_210_plus_pct
   FROM aggregated_stats
  ORDER BY rescheduled_since DESC NULLS LAST
  WITH NO DATA;


