--
-- Name: pending_approval_consumers_categorized; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.pending_approval_consumers_categorized AS
 SELECT ca.id AS consumer_application_id,
    ca.consumer_id,
    cud.full_name,
    latest.state,
    latest.reason,
    latest.active_since AS pending_since,
        CASE
            WHEN ((latest.reason ~~* '%ocr%'::text) OR (latest.reason ~~* '%MIDAS%'::text)) THEN 'NID'::text
            WHEN ((latest.reason ~~* '%CONSUMER_IN_TERRORIST_LIST%'::text) OR (latest.reason ~~* '%sanction%'::text) OR (latest.reason ~~* '%terrorist%'::text)) THEN 'Sanction List'::text
            WHEN (latest.reason ~~* '%fraud%'::text) THEN 'Fraud Check'::text
            WHEN ((latest.reason ~~* '%NID_MISMATCH%'::text) OR (latest.reason ~~* '%first_name failed%'::text) OR (latest.reason ~~* '%last_name failed%'::text) OR (latest.reason ~~* '%expiration_date failed%'::text) OR (latest.reason ~~* '%fcn failed%'::text)) THEN 'CSO Validation'::text
            WHEN ((latest.reason ~~* '%check_blocked_consumer%'::text) OR (latest.reason ~~* '%check_employment_student_age%'::text)) THEN 'Risk Rules'::text
            ELSE 'Other'::text
        END AS category
   FROM ((public.consumer_application ca
     JOIN LATERAL ( SELECT cas.state,
            cas.reason,
            cas.active_since
           FROM public.consumer_application_state cas
          WHERE (cas.consumer_application_id = ca.id)
          ORDER BY cas.active_since DESC
         LIMIT 1) latest ON (true))
     JOIN public.consumer_user_details cud ON ((cud.consumer_id = ca.consumer_id)))
  WHERE ((latest.state)::text = ANY ((ARRAY['PENDING_ONBOARDING_APPROVAL'::character varying, 'PENDING_ACTIVATION_APPROVAL'::character varying])::text[]))
  WITH NO DATA;


