--
-- Name: v_merchant_payments; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_merchant_payments AS
 WITH sla_calculation AS (
         SELECT subquery.id,
            subquery.merchant_account_id,
            subquery.payable_amount,
            (((subquery.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date AS local_transaction_date,
            subquery.status_timestamp,
            subquery.status,
                CASE
                    WHEN (EXTRACT(dow FROM (((subquery.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date) = ANY (ARRAY[(0)::numeric, (1)::numeric, (2)::numeric])) THEN (((((subquery.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date + '3 days'::interval))::date
                    WHEN (EXTRACT(dow FROM (((subquery.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date) = ANY (ARRAY[(3)::numeric, (4)::numeric, (5)::numeric, (6)::numeric])) THEN ((((((subquery.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date + (((7)::numeric - EXTRACT(dow FROM (((subquery.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date)))::integer) + '1 day'::interval))::date
                    ELSE NULL::date
                END AS expected_payment_date,
                CASE
                    WHEN ((subquery.status IS NULL) AND (subquery.expected_payment_date < CURRENT_DATE)) THEN 1
                    WHEN ((subquery.status IS NOT NULL) AND (subquery.status_timestamp > subquery.expected_payment_date)) THEN 1
                    ELSE 0
                END AS sla_breach
           FROM ( SELECT merchant_payment_1.id,
                    merchant_payment_1.merchant_account_id,
                    ((merchant_payment_1.payable_units)::double precision / (100)::double precision) AS payable_amount,
                    merchant_payment_1.transaction_date,
                    merchant_payment_1.status_timestamp,
                    merchant_payment_1.status,
                    (((merchant_payment_1.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date AS local_transaction_date,
                        CASE
                            WHEN (EXTRACT(dow FROM (((merchant_payment_1.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date) = ANY (ARRAY[(0)::numeric, (1)::numeric, (2)::numeric])) THEN (((((merchant_payment_1.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date + '3 days'::interval))::date
                            WHEN (EXTRACT(dow FROM (((merchant_payment_1.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date) = ANY (ARRAY[(3)::numeric, (4)::numeric, (5)::numeric, (6)::numeric])) THEN ((((((merchant_payment_1.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date + (((7)::numeric - EXTRACT(dow FROM (((merchant_payment_1.transaction_date AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date)))::integer) + '1 day'::interval))::date
                            ELSE NULL::date
                        END AS expected_payment_date
                   FROM public.temp_merchant_payment merchant_payment_1) subquery
        )
 SELECT p.id AS merchant_id,
    merchant_payment.id,
    merchant_payment.payment_account_id AS merchant_account_id,
    ((merchant_payment.payable_units)::double precision / (100)::double precision) AS payable_amount,
    merchant_payment.created_at AS transaction_date,
    l.status_timestamp,
    l.status,
    (((merchant_payment.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date AS local_transaction_date,
        CASE
            WHEN (EXTRACT(dow FROM (((merchant_payment.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date) = ANY (ARRAY[(0)::numeric, (1)::numeric, (2)::numeric])) THEN (((((merchant_payment.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date + '3 days'::interval))::date
            WHEN (EXTRACT(dow FROM (((merchant_payment.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date) = ANY (ARRAY[(3)::numeric, (4)::numeric, (5)::numeric, (6)::numeric])) THEN ((((((merchant_payment.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date + (((7)::numeric - EXTRACT(dow FROM (((merchant_payment.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Africa/Cairo'::text))::date)))::integer) + '1 day'::interval))::date
            ELSE NULL::date
        END AS expected_payment_date
   FROM (((public.merchant_payment
     LEFT JOIN ( SELECT max((merchant_payment_status_logs.status)::text) AS status,
            max(merchant_payment_status_logs.status_date) AS status_timestamp,
            merchant_payment_status_logs.payment_id
           FROM public.merchant_payment_status_logs
          GROUP BY merchant_payment_status_logs.payment_id) l ON ((l.payment_id = merchant_payment.id)))
     LEFT JOIN public.party_account ON (((merchant_payment.payment_account_id)::integer = party_account.id)))
     LEFT JOIN public.partner p ON ((((p.id)::character varying)::text = ((party_account.global_reference_id)::character varying)::text)));


